window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0176", [{"word":"national income","ipa_uk":"/ˈnæʃənəl ˈɪnkʌm/","ipa_us":"/ˌnæʃəˈnɑːl ˈɪnkʌm/","definition_zh":"国民收入；一国居民与企业在一定时期内获得的收入总和，用于衡量经济规模","definition_en":"the total income earned by the residents and businesses of a country over a period, used as a measure of the size and health of its economy","core_image":"一间国家账房把千万户的工资、租金与利润汇进同一本总账，账页越厚，经济规模越大","scene":"二十世纪三十年代的统计员第一次把全国工资与利润加进同一本账。Economists use national income to compare how much a country produces and earns in a year.","sceneCN":"此处指「一国居民与企业在一定时期内获得的收入总和」（第 1 个义项：全国收入的汇总量）；句意为经济学家用国民收入比较一国一年内的产出与收入。图中可辨识物件：木制账台、成摞账簿、算盘、写满数字的黑板。","pos":[{"tag":"n.","zh":"国民收入（一国居民与企业在一定时期内获得的收入总额）"},{"tag":"n.","zh":"（经济学的）国民收入总量指标"}],"collocations":[{"phrase":"national income per capita","zh":"人均国民收入"},{"phrase":"national income accounts","zh":"国民收入核算"},{"phrase":"national income statistics","zh":"国民收入统计"},{"phrase":"national income growth","zh":"国民收入增长"},{"phrase":"share of national income","zh":"国民收入份额"},{"phrase":"national income estimate","zh":"国民收入估算"}],"forms":[{"label":"单数","form":"national income"},{"label":"复数（不同国家或不同年度的总量）","form":"national incomes"}],"derivatives":[{"word":"nation","pos":"n.","zh":"国家；民族"},{"word":"national","pos":"adj.","zh":"国家的；全国的"},{"word":"nationally","pos":"adv.","zh":"在全国范围内"},{"word":"nationality","pos":"n.","zh":"国籍"},{"word":"nationalist","pos":"n./adj.","zh":"民族主义者 / 民族主义的"},{"word":"income","pos":"n.","zh":"收入"}],"senses":[{"no":"01","title":"Total income of a nation","titleCN":"全国收入汇总量","definition":"the sum of all incomes earned by a country's households and firms within a given period","definitionCN":"一国居民与企业在一定时期内所得收入的总和","example":"National income rose faster than the population, so income per head improved.","exampleCN":"国民收入增长快于人口增长，因此人均收入提高了。","why":"The phrase joins a whole country with money coming in, so its first reading is a national total.","whyCN":"这个词组把「整个国家」与「进来的钱」直接放在一起，因此第一层意思就是全国的收入总量。"},{"no":"02","title":"The official accounting measure","titleCN":"国民经济核算的官方口径","definition":"the aggregate figure compiled under national accounts rules, usually net of depreciation and adjusted for earnings from abroad","definitionCN":"按国民核算规则编制的总量数字，通常扣除折旧并对境外收入作出调整","example":"The statistics office publishes national income every quarter using the same accounting rules.","exampleCN":"统计部门每季度按同一套核算规则公布国民收入。","why":"Once governments needed comparable numbers, a loose national total was fixed into a formal accounting measure.","whyCN":"政府需要可比的数字之后，原本笼统的全国总量被固定成正式的核算口径。"},{"no":"03","title":"Income actually received by residents and firms","titleCN":"居民与企业实际收到的收入","definition":"the income actually paid out to households and businesses, before or after taxes depending on the measure used","definitionCN":"实际支付给家庭与企业的收入，按所用口径决定是税前还是税后","example":"Wages and profits both feed into national income at the point where they are paid out.","exampleCN":"工资与利润在支付出去的那一刻都计入国民收入。","why":"The total is built from payments actually made, so it can be read as the income that people and firms receive.","whyCN":"总量由实际支付构成，因此也可理解为个人与企业收到的收入。"},{"no":"04","title":"National measure distinct from domestic product","titleCN":"与国内产出相区别的国民口径","definition":"a measure of income earned by a country's residents, including earnings abroad and excluding income earned locally by foreigners","definitionCN":"衡量本国居民所得收入的指标，包含境外收入，但不含外国人在本地赚取的收入","example":"National income differs from domestic product when many citizens work abroad.","exampleCN":"当大量公民在海外工作时，国民收入与国内产出就会不同。","why":"Domestic product counts what is produced inside the borders, while national income follows who earns it, so the two separate when money crosses borders.","whyCN":"国内产出算的是境内生产了多少，国民收入看的是收入归谁，钱一跨国界两者就分开。"},{"no":"05","title":"A yardstick for comparing countries","titleCN":"用于比较各国经济水平的指标","definition":"a figure used to rank or compare countries by the total income their economies generate","definitionCN":"用来按经济所产生的收入总量排列或比较各国的数字","example":"Analysts put national income per person beside life expectancy when they rank countries.","exampleCN":"分析人员排列各国时，把人均国民收入与预期寿命并列。","why":"A comparable total makes a convenient yardstick, so the term took on the role of a cross-country benchmark.","whyCN":"可比的总量最方便当尺子，这个词因此承担起跨国比较基准的角色。"},{"no":"06","title":"The shares going to wages, profits and rents","titleCN":"国民收入在工资、利润与租金之间的分配","definition":"the division of a country's total income among wages, profits, rents and other payments to the owners of production","definitionCN":"把一国收入总量分给工资、利润、租金及其他生产要素报酬","example":"Economists asked how national income was split between workers and owners.","exampleCN":"经济学家追问国民收入在劳动者与所有者之间如何划分。","why":"A total can also be examined from the inside as slices belonging to different earners, which is the distribution sense.","whyCN":"总量也可以从内部看，分成属于不同收入者的几块，这就是分配义。"},{"no":"07","title":"The published statistic","titleCN":"公布出来的统计数字","definition":"the number or set of figures reported in official statistics and news reports","definitionCN":"官方统计与新闻报道中报出的数字或一组数字","example":"The revised national income figure was higher than the earlier estimate.","exampleCN":"修正后的国民收入数字高于早先的估计。","why":"An abstract total becomes a concrete number once it is printed, so the phrase also names the reported statistic itself.","whyCN":"抽象的总量一经公布就成了具体数字，因此这个词组也指报出的统计数字本身。"},{"no":"08","title":"The theoretical aggregate in economics","titleCN":"经济学理论中的总量概念","definition":"the economy-wide total of incomes used in models of demand, saving and growth","definitionCN":"需求、储蓄与增长模型所使用的全国收入总量","example":"In the model, national income determines how much households can spend.","exampleCN":"在模型中，国民收入决定家庭能支出多少。","why":"Theory treats the whole economy as one account, so the phrase works as a variable rather than a headline number.","whyCN":"理论把整个经济当成一本账，这个词组因此是模型变量，而不只是新闻标题里的数字。"}],"etymology":{"intro":{"en":"National income is a two-layer compound: the first half comes from Latin through French, the second is native English. It became an economic term only when national accounts were built. Dates are approximate.","cn":"国民收入是一个两层来源的复合词：前半经法语来自拉丁语，后半为英语本族词。直到国民核算体系建立，它才成为经济术语。年代均为约数。"},"items":[{"era":"LATIN NATIO","en":"Natio meant 'birth, race, people' and came from nasci 'to be born'. The noun entered English through Old French.","cn":"natio 意为「出生、族群、人民」，出自 nasci「出生」。该名词经古法语进入英语。"},{"era":"NATIONAL","en":"Latin nationalis, built from natio with an adjective suffix, entered English in the sixteenth century with the sense 'belonging to a whole people'.","cn":"由 natio 加形容词后缀构成的 nationalis 于十六世纪进入英语，意为「属于整个民族的」。"},{"era":"OLD ENGLISH INCOME","en":"Income joins a prefix meaning 'in' to the verb 'to come', literally 'that which comes in', and it named money received rather than money paid out.","cn":"收入一词由表示「进入」的前缀加动词「来」构成，字面就是「进来的东西」，指收到的钱而非付出去的钱。"},{"era":"POLITICAL ARITHMETIC","en":"Seventeenth-century writers on political arithmetic began adding up a whole country's earnings, though they did not yet use the modern term.","cn":"十七世纪的政治算术作者开始把一国收入加总，但尚未使用今天的术语。"},{"era":"NATIONAL ACCOUNTS","en":"The term became standard in the 1930s and 1940s, when official national accounts were built to guide policy through depression and war.","cn":"这一术语在二十世纪三十至四十年代定型，当时为应对萧条与战争建立了官方国民核算体系。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the exact first appearance of the compound is not recorded, and estimates of the earliest use differ.","cn":"首见年代不确定：这一复合词的确切首见未被记录，对最早用例的估计也有分歧。"}]},"similar":{"note":{"en":"Group one separates the totals that learners constantly confuse; group two lists measures that answer a closely related question.","cn":"第一组区分几个经常混淆的总量指标；第二组列出回答相近问题的其他度量。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gross domestic product","ipa":"/ɡrəʊs dəˈmestɪk ˈprɒdʌkt/","tag":"output, not income","definition":"GDP counts what is produced inside a country's borders, whoever produces it; national income counts what residents earn.","definitionCN":"国内生产总值算的是境内生产了多少，不论生产者是谁；国民收入算的是本国居民赚了多少。"},{"word":"gross national product","ipa":"/ɡrəʊs ˈnæʃənəl ˈprɒdʌkt/","tag":"national output total","definition":"GNP adds citizens' earnings abroad to domestic output; it measures output, while national income measures income.","definitionCN":"国民生产总值把公民的境外收入加到国内产出上，衡量的是产出，而国民收入衡量的是收入。"},{"word":"national wealth","ipa":"/ˈnæʃənəl welθ/","tag":"stock, not flow","definition":"National wealth is a stock of assets at one moment; national income is a flow over a period.","definitionCN":"国民财富是某一时刻的资产存量；国民收入是一段时期内的流量。"},{"word":"net national income","ipa":"/net ˈnæʃənəl ˈɪnkʌm/","tag":"after depreciation","definition":"Net national income subtracts depreciation from the total, giving a narrower accounting figure.","definitionCN":"净国民收入从总量中扣除折旧，是口径更窄的核算数字。"}]},{"heading":"NEAR MEANING","entries":[{"word":"national output","ipa":"/ˈnæʃənəl ˈaʊtpʊt/","tag":"production side","definition":"National output looks at goods and services produced, the other side of the same national account.","definitionCN":"国民产出看的是生产出的商品与服务，是同一本国民账的另一面。"},{"word":"domestic income","ipa":"/dəˈmestɪk ˈɪnkʌm/","tag":"inside the border","definition":"Domestic income is earned inside the country by anyone working there, regardless of nationality.","definitionCN":"国内收入是境内任何人赚到的收入，不问国籍。"},{"word":"aggregate income","ipa":"/ˈæɡrɪɡeɪt ˈɪnkʌm/","tag":"sum of incomes","definition":"Aggregate income is the plain sum of all incomes, a term used in models rather than in official reports.","definitionCN":"总收入就是所有收入的简单加总，多用于模型而非官方报告。"},{"word":"per capita income","ipa":"/pər ˈkæpɪtə ˈɪnkʌm/","tag":"divided by population","definition":"Per capita income divides the total by the number of people, turning a national figure into an average.","definitionCN":"人均收入把总量除以人口，把全国数字变成平均值。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real halves of the compound, real accounting phrases and real relatives.","cn":"正常联想：真实的构词两半、真实的核算说法与真实的同族词。"},"normal":[{"en":"A whole people plus an adjective suffix gives the national half.","cn":"「整个民族」加形容词后缀，就是「国家的」这一半。"},{"en":"A prefix meaning 'in' plus the verb 'to come' gives income, money that comes in.","cn":"表示「进入」的前缀加动词「来」，构成收入，也就是进来的钱。"},{"en":"The two halves answer different questions: whose country, and how much came in.","cn":"两半回答不同问题：属于哪个国家，以及进来了多少。"},{"en":"Fixed accounting phrases keep the technical sense: national income accounts and national income statistics.","cn":"固定的核算说法保留技术义：国民收入核算、国民收入统计。"},{"en":"It sits beside domestic product, which counts output rather than earnings.","cn":"它与国内产出并列，后者算产出而不是收入。"}],"abstract":[{"en":"Picture one ledger on a national desk with every wage and profit written on the same page.","cn":"想象一张国家账台上摊着一本总账，每笔工资与利润都写在同一页。"},{"en":"Picture a family budget copied a million times and then added into one column.","cn":"想象一份家庭预算被复制百万次，再加进同一列。"},{"en":"Picture a ruler long enough to measure a whole country's yearly earning.","cn":"想象一把长到足以丈量一国全年收入的尺子。"}]},"examples":[{"en":"The survey found that national income had grown while the poorest households gained little.","cn":"调查发现国民收入在增长，而最贫困家庭的所得几乎没有增加。"},{"en":"National income is usually reported both before and after taxes.","cn":"国民收入通常同时报告税前与税后两个口径。"},{"en":"Comparing national income across countries requires adjusting for price differences.","cn":"跨国比较国民收入需要按物价差异作出调整。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「国家」加「收入」——把一国的工资、利润与租金都放进同一本账，就是国民收入","word":"national income"},"root":"拉丁 natio「出生、族群」出自 nasci「出生」，经古法语进入英语并派生形容词；后半为英语本族复合词，由表示「进入」的前缀加动词「来」构成，字面为「进来的东西」。两部分合为国民收入。","sensesIntro":{"en":"Eight senses follow one movement: money earned across a whole country is gathered into one account, then read as a measure, a comparison, a share and a model variable.","cn":"八个义项沿同一个动作展开：全国赚到的钱被收进同一本账，再被读成指标、比较基准、分配份额与模型变量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a national ledger room where every wage, rent and profit is entered on one page.","cn":"核心意象：一间国家账房，把每笔工资、租金与利润都记在同一页上。"},"chain":["EARN","SUM ALL EARNERS","NATIONWIDE TOTAL","OFFICIAL ACCOUNT","CROSS-COUNTRY YARDSTICK","SHARES OF THE TOTAL"],"branches":[{"senses":"01 · 03","en":"THE SUM ITSELF: what households and firms actually receive is added into one figure.","cn":"总量本身：家庭与企业实际收到的钱被加成同一个数字。"},{"senses":"02 · 07","en":"THE ACCOUNT AND ITS PRINTED FORM: the same total becomes a formal measure and then a reported statistic.","cn":"账目与印刷形态：同一个总量先成为正式指标，再成为报出的统计数字。"},{"senses":"04","en":"THE BORDER TEST: following who earns the money separates national income from domestic product.","cn":"边界检验：追问钱归谁赚，就把国民收入与国内产出分开。"},{"senses":"05 · 08","en":"THE YARDSTICK: a comparable total serves both as a ranking device and as a model variable.","cn":"尺子：可比的总量既是排名工具，也是模型变量。"},{"senses":"06","en":"THE INSIDE VIEW: one total can also be read as slices belonging to different earners.","cn":"内部视角：同一个总量也可读成属于不同收入者的几块。"}]},"affixes":{"intro":{"en":"The compound is built from a Latin noun and a native English verb, and its parts also build a large family of everyday words.","cn":"这个复合词由拉丁名词与英语本族动词构成，两部分还构成一大批日常词。"},"latinIntro":{"en":"Natio and nasci supply the first half; the second half is native Germanic, so the compound mixes two language layers.","cn":"前半由 natio 与 nasci 提供；后半是日耳曼语本族词，因此这个复合词混合了两个语言层。"},"items":[{"word":"nation","structure":"natio (Latin noun) through Old French","meaning":"a people or country","meaningCN":"民族；国家","example":"The nation rebuilt its ports after the war.","exampleCN":"战后这个国家重建了港口。"},{"word":"national","structure":"nation + -al (adjective suffix)","meaning":"belonging to a whole people","meaningCN":"国家的；全国的","example":"National figures hide wide differences between regions.","exampleCN":"全国数字掩盖了地区之间的巨大差异。"},{"word":"nationally","structure":"national + -ly (adverb suffix)","meaning":"across the whole country","meaningCN":"在全国范围内","example":"The scheme was rolled out nationally in two years.","exampleCN":"这项计划两年内在全国推开。"},{"word":"nationality","structure":"national + -ity (noun suffix)","meaning":"the state of belonging to a country","meaningCN":"国籍","example":"She holds dual nationality.","exampleCN":"她拥有双重国籍。"},{"word":"nationalist","structure":"national + -ist (person or adherent suffix)","meaning":"one who puts the nation first","meaningCN":"民族主义者","example":"The nationalist party gained seats in the election.","exampleCN":"民族主义政党在选举中赢得席位。"},{"word":"nationalize","structure":"national + -ize (verb suffix)","meaning":"to bring under state ownership","meaningCN":"收归国有","example":"The government nationalized the railway.","exampleCN":"政府把铁路收归国有。"},{"word":"income","structure":"in- (prefix 'in') + come (verb 'to come')","meaning":"money that comes in","meaningCN":"收入","example":"Household income stagnated for a decade.","exampleCN":"家庭收入停滞了十年。"},{"word":"incoming","structure":"in + come + -ing (adjective suffix)","meaning":"coming in from outside","meaningCN":"进来的；即将到任的","example":"Incoming students register in September.","exampleCN":"新生在九月注册。"},{"word":"comer","structure":"come + -er (person suffix)","meaning":"one who comes, especially a promising newcomer","meaningCN":"来者；有前途的新人","example":"She was praised as a strong comer in the firm.","exampleCN":"她被称赞为公司里很有前途的新人。"}],"latinEntries":[{"word":"natio","structure":"natio, nationis (f., third declension)","meaning":"birth, race, people","meaningCN":"出生；族群；人民"},{"word":"nasci","structure":"nasci, natus sum (deponent verb)","meaning":"to be born","meaningCN":"出生"},{"word":"nationalis","structure":"nationalis, nationale (adj., third declension)","meaning":"of a nation","meaningCN":"民族的；国家的"}],"derivatives":[{"word":"nation","pos":"n.","zh":"国家；民族"},{"word":"national","pos":"adj.","zh":"国家的；全国的"},{"word":"nationally","pos":"adv.","zh":"在全国范围内"},{"word":"nationality","pos":"n.","zh":"国籍"},{"word":"nationalist","pos":"n./adj.","zh":"民族主义者 / 民族主义的"},{"word":"income","pos":"n.","zh":"收入"}]}},{"word":"standard of living","ipa_uk":"/ˈstændəd əv ˈlɪvɪŋ/","ipa_us":"/ˈstændərd əv ˈlɪvɪŋ/","definition_zh":"生活水平；人们在食物、住房、医疗、教育等方面达到的舒适与保障程度","definition_en":"the level of comfort, goods and services that a person, group or country can enjoy, especially as measured by income and access to necessities","core_image":"一户人家的餐桌、住房与医院账单并排摆着，数量与质量共同标出这家人过得如何","scene":"报告比较了沿海城市与内陆村庄的住房、饮食与就医条件。The report measures the standard of living in coastal cities against that in inland villages.","sceneCN":"此处指「人们在食物、住房、医疗、教育等方面达到的舒适与保障程度」（第 1 个义项：生活舒适度的总体水平）；句意为报告把沿海城市的生活水平与内陆村庄作比较。图中可辨识物件：餐桌、住房、病历、学校课本。","pos":[{"tag":"n.","zh":"生活水平（以物质条件与公共服务衡量的生活舒适程度）"},{"tag":"n.","zh":"（可数用法）某种具体的生活水准"}],"collocations":[{"phrase":"a high standard of living","zh":"高水平的生活"},{"phrase":"a low standard of living","zh":"低水平的生活"},{"phrase":"raise the standard of living","zh":"提高生活水平"},{"phrase":"a decent standard of living","zh":"体面的生活水平"},{"phrase":"the standard of living of a region","zh":"某地区的生活水平"},{"phrase":"compare standards of living","zh":"比较生活水平"}],"forms":[{"label":"单数","form":"standard of living"},{"label":"复数（多种或不同地区的生活水平）","form":"standards of living"}],"derivatives":[{"word":"standard","pos":"n./adj.","zh":"标准；标准的"},{"word":"living","pos":"n./adj.","zh":"生活；活着的"},{"word":"standardize","pos":"v.","zh":"使标准化"},{"word":"standardization","pos":"n.","zh":"标准化"},{"word":"livable","pos":"adj.","zh":"适宜居住的"},{"word":"livelihood","pos":"n.","zh":"生计"}],"senses":[{"no":"01","title":"Overall comfort and access to necessities","titleCN":"整体的舒适程度与基本生活保障","definition":"the general level of comfort in which people live, judged by food, housing, health care and other necessities","definitionCN":"人们生活的一般舒适程度，以食物、住房、医疗等基本需要衡量","example":"The survey compares the standard of living of rural households with that of city dwellers.","exampleCN":"这项调查把农村家庭的生活水平与城市居民作比较。","why":"The phrase pairs a measuring rod with the act of living, so it asks how well, not merely whether, people live.","whyCN":"这个词组把「衡量尺度」与「生活」放在一起，问的是人们过得好不好，而不只是有没有在活。"},{"no":"02","title":"Measured by goods and services per person","titleCN":"按人均商品与服务衡量","definition":"the level of consumption of goods and services available to each person","definitionCN":"每个人可以使用到的商品与服务数量所体现的水准","example":"A rising standard of living shows up as more varied food and better housing per person.","exampleCN":"生活水平提高，会表现为人均食物更丰富、住房更好。","why":"Consumption is the most visible face of comfort, so a per-person basket of goods became the common measure.","whyCN":"消费是舒适最直观的一面，因此人均商品篮成了常用尺度。"},{"no":"03","title":"A national or regional average","titleCN":"国家或地区的平均水平","definition":"the average condition of a whole population rather than of one household","definitionCN":"整群人口的平均状况，而非单个家庭的状况","example":"The standard of living in the capital is far above the national average.","exampleCN":"首都的生活水平远高于全国平均。","why":"Once the phrase is applied to a population, it becomes an average that hides differences inside the group.","whyCN":"这个词组一旦用于整群人口，就成了掩盖群体内部差异的平均值。"},{"no":"04","title":"A minimum acceptable threshold","titleCN":"可接受的最低生活水准","definition":"the minimum level of comfort and provision that a society considers acceptable","definitionCN":"一个社会认为可以接受的最低舒适与供给水平","example":"Charity workers argued that no family should fall below a basic standard of living.","exampleCN":"慈善工作者主张，任何家庭都不应跌到基本生活水平以下。","why":"A measuring rod can mark a floor as well as an average, and the floor sense drives welfare policy.","whyCN":"尺子既能标出平均线，也能标出底线，底线义推动了福利政策。"},{"no":"05","title":"Quality of life beyond material goods","titleCN":"超出物质层面的生活质量","definition":"the part of wellbeing that comes from leisure, education, health and a clean environment rather than income alone","definitionCN":"来自闲暇、教育、健康与清洁环境而非单纯收入的福祉部分","example":"Planners now include green space when they discuss the standard of living.","exampleCN":"规划者在讨论生活水平时，如今把绿地也计算在内。","why":"Living well is not only owning much, so the phrase stretched to cover the non-material side of comfort.","whyCN":"过得好不只是拥有得多，这个词组因此扩展到舒适的非物质层面。"},{"no":"06","title":"A level that rises over time","titleCN":"随时间提高的生活水准","definition":"the historically changing level of comfort that each generation expects as normal","definitionCN":"每一代人视为正常、并随历史变化的舒适程度","example":"Each generation measures the standard of living against what its parents already had.","exampleCN":"每一代人都以父辈已经拥有的条件来衡量生活水平。","why":"Expectations are learned, so what counts as adequate shifts upward as goods become ordinary.","whyCN":"期待是被养成的，商品一旦普及，所谓「够用」的标准就随之上移。"},{"no":"07","title":"Purchasing power against the cost of living","titleCN":"与生活成本相对的购买力水平","definition":"the real level of comfort given a money income, after the prices people must pay are taken into account","definitionCN":"在计入人们必须支付的价格之后，一定货币收入带来的实际舒适程度","example":"A pay rise that only matches prices leaves the standard of living unchanged.","exampleCN":"只与物价涨幅持平的加薪，不会改变生活水平。","why":"Comfort depends on what money can buy, so the phrase is always read against prices rather than income alone.","whyCN":"舒适取决于钱能买到什么，因此这个词组总要对照物价来读，而不能只看收入。"},{"no":"08","title":"Official statistical indicator","titleCN":"官方统计指标","definition":"an index or set of indicators used by governments and agencies to report living conditions","definitionCN":"政府与机构用来报告生活状况的指数或一组指标","example":"The annual report tracks the standard of living through housing, health and schooling indicators.","exampleCN":"年度报告通过住房、健康与教育指标追踪生活水平。","why":"When comfort is reported as numbers, the phrase becomes the name of the indicator itself.","whyCN":"当舒适被报成数字，这个词组便成了指标本身的名称。"}],"etymology":{"intro":{"en":"Standard has an uncertain Frankish origin and reached English through Old French; living is a native Germanic word. The full phrase is a modern social and statistical term. Dates are approximate.","cn":"前半经古法语进入英语，可能来自法兰克语，来源不确定；后半是日耳曼语本族词。完整词组是近现代的社会与统计术语。年代均为约数。"},"items":[{"era":"FRANKISH RECONSTRUCTION","en":"Standard goes back to Old French estandart 'banner, rallying point'. A common suggestion derives it from a Frankish form meaning 'stand firm', but that form is a reconstruction and the source is uncertain.","cn":"「标准」可追溯到古法语 estandart「旗帜、集合点」。常见假说认为它来自法兰克语中表示「站稳」的形式，但该形式属重构，来源不确定。"},{"era":"MIDDLE ENGLISH STANDARD","en":"English adopted the word in the fourteenth century for a banner and then for an authorized weight or measure, from which the modern sense of a level of quality grew.","cn":"英语在十四世纪借入该词，先指旗帜，后指官方认可的度量衡，现代「水准」义由此发展而来。"},{"era":"OLD ENGLISH LIVING","en":"Living comes from Old English libban 'to live', a native Germanic verb with no Latin ancestor.","cn":"「生活」部分来自古英语表示「活着」的动词，是日耳曼语本族词，没有拉丁语祖先。"},{"era":"PHRASE FORMATION","en":"The full phrase appeared in the nineteenth century, when reformers needed a term for the material conditions of workers and the poor.","cn":"完整词组出现于十九世纪，当时改革者需要为工人与穷人的物质状况命名。"},{"era":"STATISTICAL USE","en":"In the twentieth century the phrase became a statistical measure of consumption, housing and access to services.","cn":"到二十世纪，这个词组成为衡量消费、住房与服务可及性的统计指标。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (Frankish origin): no attested Frankish form survives, and the earliest use of the full phrase is not precisely dated.","cn":"来源不确定（法兰克语来源）：没有留存可证的法兰克语形式，完整词组的最早用例也没有确切年代。"}]},"similar":{"note":{"en":"Group one holds phrases that look almost identical but measure something else; group two holds words that describe how well people live.","cn":"第一组是外形几乎相同、却测量别的东西的词组；第二组是描述人们过得好不好的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cost of living","ipa":"/kɒst əv ˈlɪvɪŋ/","tag":"prices, not comfort","definition":"The cost of living is the money needed to buy everyday goods and services; the standard of living is the comfort those purchases actually deliver.","definitionCN":"生活成本是购买日常商品与服务所需的钱；生活水平则是这些购买实际带来的舒适程度。"},{"word":"living standard","ipa":"/ˈlɪvɪŋ ˈstændəd/","tag":"same idea, word order reversed","definition":"Living standard is the common reversed form with the same meaning; standard of living is the more formal statistical phrasing.","definitionCN":"生活水准是其常见的倒序形式，含义相同；生活水平是更正式、更统计化的说法。"},{"word":"quality of life","ipa":"/ˈkwælɪti əv laɪf/","tag":"wellbeing, wider than goods","definition":"Quality of life covers health, freedom, environment and happiness, while the standard of living leans on material provision.","definitionCN":"生活质量涵盖健康、自由、环境与幸福感，生活水平则偏向物质供给。"},{"word":"way of life","ipa":"/weɪ əv laɪf/","tag":"customs, not comfort","definition":"A way of life is the customs and habits of a group, not a measurable level of comfort.","definitionCN":"生活方式是一群人的习俗与习惯，不是可测量的舒适程度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"wellbeing","ipa":"/ˌwelˈbiːɪŋ/","tag":"broad condition of thriving","definition":"Wellbeing includes health, security and satisfaction, of which material comfort is only one part.","definitionCN":"福祉包含健康、安全与满足感，物质舒适只是其中一部分。"},{"word":"affluence","ipa":"/əˈfluːəns/","tag":"abundant wealth","definition":"Affluence is a high level of wealth and consumption; it describes the top end that the standard of living measures on average.","definitionCN":"富裕是财富与消费的高水平，描述生活水平在均值上衡量的高端。"},{"word":"prosperity","ipa":"/prəˈsperəti/","tag":"economic success","definition":"Prosperity is the success of an economy or group, a condition that usually raises the standard of living.","definitionCN":"繁荣是经济或群体的成功状态，通常会抬高生活水平。"},{"word":"material conditions","ipa":"/məˈtɪəriəl kənˈdɪʃənz/","tag":"the measurable base","definition":"Material conditions are the concrete housing, food and services behind any standard of living.","definitionCN":"物质条件是任何生活水平背后的住房、食物与服务等具体基础。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real halves, real measures and real phrases, not invented rhymes.","cn":"正常联想：真实的构词两半、真实的度量与真实的说法，而不是编造的顺口溜。"},"normal":[{"en":"A standard is a measuring rod; living is being alive; together they ask how well a life measures.","cn":"标准是一把尺，生活是活着，合起来就是问日子量出来有多好。"},{"en":"The phrase is reported as a number, but it always describes people's actual conditions.","cn":"这个词组虽以数字报告，却始终描述人们的实际处境。"},{"en":"Fixed phrases show the floor sense: a basic standard of living, a decent standard of living.","cn":"固定搭配体现底线义：基本生活水平、体面生活水平。"},{"en":"It is read against prices, because money alone does not buy comfort.","cn":"它要对照物价来读，因为单有钱并不等于舒适。"},{"en":"It is close to cost of living, but the two point in opposite directions: one is comfort, the other is price.","cn":"它与生活成本相近，但方向相反：一个说舒适，一个说价格。"}],"abstract":[{"en":"Picture a table set with just enough plates, and then with more than enough.","cn":"想象一张餐桌先摆出刚好够用的盘子，后来又摆出用不完的盘子。"},{"en":"Picture a thermometer that measures not heat but how easily a family gets food and medicine.","cn":"想象一支温度计，量的不是热度，而是一家人获得食物与药品的容易程度。"},{"en":"Picture a ladder whose lowest rung is called decent and whose top is never reached.","cn":"想象一架梯子，最下一级叫「体面」，最高一级永远够不到。"}]},"examples":[{"en":"The report found a wide gap in the standard of living between the coast and the interior.","cn":"报告发现沿海与内陆之间生活水平差距很大。"},{"en":"Rising incomes do not automatically raise the standard of living when rents rise just as fast.","cn":"当租金涨得同样快时，收入增加并不会自动提高生活水平。"},{"en":"Clean water and schooling are now counted as part of the standard of living.","cn":"清洁饮水与教育如今被计入生活水平。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「标准」加「生活」——用一把尺去量日子过得好不好，就是生活水平","word":"standard of living"},"root":"前半经古法语 estandart「旗帜、集合点」进入英语，可能来自法兰克语重构形式，来源不确定；后半为古英语本族词，意为「活着」。合起来指生活所达到的水准。","sensesIntro":{"en":"Eight senses follow one act of measuring: a life is held against goods, against an average, against a floor, against prices and finally against a printed indicator.","cn":"八个义项沿同一个衡量动作展开：把生活分别对照商品、平均值、底线、物价，最后对照公布的指标。"},"semanticMap":{"core":{"en":"CORE IMAGE: a family table, a roof and a medical bill placed side by side as one measuring rod.","cn":"核心意象：把餐桌、屋顶与医疗账单并排放好，合成一把衡量生活的尺。"},"chain":["LIVE","CONSUME GOODS","COMFORT LEVEL","MINIMUM THRESHOLD","QUALITY BEYOND GOODS","RISING EXPECTATION"],"branches":[{"senses":"01 · 02","en":"THE BASKET: comfort is first read off the goods and services a person can actually use.","cn":"篮子：舒适首先从一个人实际能用的商品与服务读出来。"},{"senses":"03","en":"THE AVERAGE: one basket is multiplied into a population figure.","cn":"平均值：一只篮子被放大成整群人口的数字。"},{"senses":"04 · 08","en":"THE FLOOR AND THE REPORT: a minimum is set, then published as an indicator.","cn":"底线与报告：先设最低线，再作为指标公布。"},{"senses":"05","en":"BEYOND GOODS: comfort extends to leisure, health and a clean environment.","cn":"超出商品：舒适扩展到闲暇、健康与清洁环境。"},{"senses":"06 · 07","en":"TIME AND PRICE: expectations rise, and money is always read against what it can buy.","cn":"时间与价格：期待会上移，而钱总要对照它能买到什么来读。"}]},"affixes":{"intro":{"en":"The phrase joins a word of uncertain Frankish origin for an authorized measure with a native Germanic word for being alive.","cn":"这个词组把来源不确定、经古法语而来的「官方尺度」与日耳曼语本族的「活着」拼在一起。"},"latinIntro":{"en":"There is no Latin source here: the first half is Frankish through French, and the second half is native English.","cn":"这里没有拉丁语来源：前半经法语来自法兰克语，后半是英语本族词。"},"items":[{"word":"standard","structure":"Old French estandart (banner, authorized measure)","meaning":"an accepted measure or level","meaningCN":"标准；水准","example":"The hotel fell below its own standard.","exampleCN":"这家旅馆没达到它自己的标准。"},{"word":"standardize","structure":"standard + -ize (verb suffix)","meaning":"to make uniform by a standard","meaningCN":"使标准化","example":"The agency standardized the forms across regions.","exampleCN":"该机构把各地表格统一标准化。"},{"word":"standardization","structure":"standardize + -ation (noun suffix)","meaning":"the act of making uniform","meaningCN":"标准化","example":"Standardization cut the cost of spare parts.","exampleCN":"标准化降低了备件成本。"},{"word":"living","structure":"Old English libban + -ing (noun suffix)","meaning":"the state or activity of being alive","meaningCN":"生活；生计","example":"The cost of living rose sharply.","exampleCN":"生活成本急剧上升。"},{"word":"live","structure":"Old English libban (verb)","meaning":"to be alive","meaningCN":"活着；居住","example":"Many families live on one income.","exampleCN":"许多家庭靠一份收入生活。"},{"word":"livable","structure":"live + -able (adjective suffix)","meaning":"fit to live in","meaningCN":"适宜居住的","example":"The city became more livable after the parks opened.","exampleCN":"公园开放后这座城市更宜居了。"},{"word":"livelihood","structure":"live + -lihood (noun suffix)","meaning":"the means of supporting life","meaningCN":"生计","example":"Fishing remains the main livelihood here.","exampleCN":"捕鱼仍是这里的主要生计。"},{"word":"standard of living","structure":"standard + of + living (fixed phrase)","meaning":"the measure of a life's comfort","meaningCN":"生活水平","example":"The phrase names what the indicators try to capture.","exampleCN":"这个词组命名了各项指标试图捕捉的东西。"}],"latinEntries":[],"derivatives":[{"word":"standard","pos":"n./adj.","zh":"标准；标准的"},{"word":"standardize","pos":"v.","zh":"使标准化"},{"word":"standardization","pos":"n.","zh":"标准化"},{"word":"living","pos":"n./adj.","zh":"生活；活着的"},{"word":"livable","pos":"adj.","zh":"适宜居住的"},{"word":"livelihood","pos":"n.","zh":"生计"}]}},{"word":"living standard","ipa_uk":"/ˈlɪvɪŋ ˈstændəd/","ipa_us":"/ˈlɪvɪŋ ˈstændərd/","definition_zh":"生活水准；与「生活水平」同义，指人们在物质与公共服务方面达到的条件","definition_en":"the level of material comfort and access to services enjoyed by a person, group or country; a common variant of standard of living","core_image":"同一间屋子的屋顶、饭桌与药箱被摆成一排，旁边立着一把量尺","scene":"乡镇干部把新修的公路、学校和诊所列进同一份清单。The study tracks the living standard of mountain villages over ten years.","sceneCN":"此处指「人们在物质与公共服务方面达到的条件」（第 1 个义项：生活舒适程度）；句意为这项研究追踪山区村庄十年间的居住水准变化。图中可辨识物件：屋顶、饭桌、药箱、量尺。","pos":[{"tag":"n.","zh":"生活水准（与生活水平同义，偏口语与统计报道）"},{"tag":"n.","zh":"（复数）不同群体的生活条件"}],"collocations":[{"phrase":"a rising living standard","zh":"不断提高的生活水准"},{"phrase":"a basic living standard","zh":"基本生活水准"},{"phrase":"living standards improve","zh":"生活水准改善"},{"phrase":"living standards fall","zh":"生活水准下降"},{"phrase":"the living standard of a region","zh":"某地区的生活水准"},{"phrase":"compare living standards","zh":"比较生活水准"}],"forms":[{"label":"单数","form":"living standard"},{"label":"复数（多群体或多地区的生活水准）","form":"living standards"}],"derivatives":[{"word":"living","pos":"n./adj.","zh":"生活；活着的"},{"word":"standard","pos":"n./adj.","zh":"标准；标准的"},{"word":"standardize","pos":"v.","zh":"使标准化"},{"word":"livable","pos":"adj.","zh":"适宜居住的"},{"word":"livelihood","pos":"n.","zh":"生计"},{"word":"standardization","pos":"n.","zh":"标准化"}],"senses":[{"no":"01","title":"Level of material comfort","titleCN":"物质舒适程度","definition":"the degree of comfort in housing, food, clothing and everyday goods that people enjoy","definitionCN":"人们在住房、食物、衣着与日常用品方面享有的舒适程度","example":"Better housing lifted the living standard of the whole district.","exampleCN":"住房改善抬高了整个城区的生活水准。","why":"The reversed word order keeps the same measuring idea: a level attached to the act of living.","whyCN":"倒序的说法保留同一个衡量思路：给「生活」这一动作标出一个高低。"},{"no":"02","title":"Income-based measure","titleCN":"以收入衡量的水准","definition":"the level of comfort estimated from household or personal income","definitionCN":"根据家庭或个人收入估算出的舒适程度","example":"Per capita income is often used as a rough living standard.","exampleCN":"人均收入常被当作粗略的生活水准。","why":"Money is the easiest proxy for comfort, so income figures stand in for the fuller measure.","whyCN":"钱是舒适最容易的替身，因此收入数字常被用来代替更完整的衡量。"},{"no":"03","title":"Adequacy of food and housing","titleCN":"食物与住房的充足程度","definition":"whether people have enough to eat and a secure place to live","definitionCN":"人们是否有足够的食物与安全的居所","example":"The charity asked whether the living standard of the poorest families covered food and rent.","exampleCN":"慈善机构询问最贫困家庭的生活水准能否覆盖饮食与房租。","why":"At the bottom of the scale, comfort reduces to the question of enough food and shelter.","whyCN":"在尺度的底端，舒适缩减为食物与住所够不够的问题。"},{"no":"04","title":"Comparison between regions","titleCN":"地区之间的比较","definition":"the relative condition of one area measured against another","definitionCN":"把一个地区的生活条件相对于另一个地区来衡量","example":"Living standards in the northern provinces caught up with the south.","exampleCN":"北方各省的生活水准追上了南方。","why":"A level only becomes visible when two places are set side by side.","whyCN":"水准只有在两地并列时才会显现出来。"},{"no":"05","title":"A minimum acceptable level","titleCN":"最低可接受的水准","definition":"the floor below which a society thinks living conditions should not fall","definitionCN":"社会认为生活条件不应跌破的下限","example":"The plan set a living standard below which no pensioner should fall.","exampleCN":"该计划设定了一个任何领取养老金者都不应跌破的生活水准。","why":"The word standard can mark a floor as well as a rank, and policy uses the floor reading.","whyCN":"「标准」既能标出等级，也能标出底线，政策用的是底线义。"},{"no":"06","title":"Improvement across generations","titleCN":"世代之间的提高","definition":"the change in comfort that each generation compares with its parents' condition","definitionCN":"每一代人与父辈条件相比较而得出的舒适变化","example":"Her grandparents saw a living standard their parents could not have imagined.","exampleCN":"她的祖辈见到了父辈无法想象的生活水准。","why":"Because expectations are handed down, the phrase often appears in stories of upward change.","whyCN":"由于期待会代代相传，这个词组常出现在生活上升的叙述里。"},{"no":"07","title":"Plural conditions of a group","titleCN":"复数指一群人的整体条件","definition":"the conditions of several groups or places taken together, usually in the plural","definitionCN":"若干群体或地区合在一起的生活条件，通常用复数","example":"The report compared living standards across income groups.","exampleCN":"报告比较了不同收入群体的生活水准。","why":"English often pluralizes the phrase when several populations are compared, and the plural became a set phrase.","whyCN":"当比较多个群体时，英语常把这个词组变复数，复数形式遂成固定说法。"},{"no":"08","title":"Broader wellbeing including public services","titleCN":"含公共服务的综合福祉","definition":"the wider condition of life that includes schools, clinics, transport and clean water alongside private goods","definitionCN":"除私人物品外，还包括学校、诊所、交通与清洁饮水的更广生活条件","example":"Villages gained a living standard that included a clinic and a bus route.","exampleCN":"村庄获得的生活水准包含了诊所与公交线路。","why":"Public provision is part of how well people live, so the phrase expanded beyond private consumption.","whyCN":"公共服务是人们过得好不好的一部分，这个词组因此超出私人消费。"}],"etymology":{"intro":{"en":"The phrase reverses standard of living and uses the same two sources: a word of uncertain Frankish origin for a measure, and a native Germanic word for being alive. Dates are approximate.","cn":"这个词组是「生活水平」的倒序形式，两部分来源相同：一个来源不确定、经法语而来的「尺度」，加一个日耳曼语本族的「活着」。年代均为约数。"},"items":[{"era":"OLD ENGLISH LIVING","en":"Living descends from Old English libban 'to live' and keeps the native Germanic sense of being alive and making a livelihood.","cn":"「生活」来自古英语表示「活着」的动词，保留日耳曼语本族「活着、谋生」的意思。"},{"era":"FRANKISH RECONSTRUCTION","en":"Standard came through Old French estandart 'banner, rallying point', probably from a Frankish form meaning 'stand firm'; the form is a reconstruction and the source is uncertain.","cn":"「标准」经古法语 estandart「旗帜、集合点」而来，可能出自法兰克语中表示「站稳」的形式；该形式属重构，来源不确定。"},{"era":"REVERSED ORDER","en":"English freely reverses noun phrases of this shape, and living standard appeared alongside standard of living without any difference in meaning.","cn":"英语可以自由调换这类名词短语的词序，生活水准与生活水平并行出现，含义没有差别。"},{"era":"STATISTICAL DIFFUSION","en":"The reversed form spread in twentieth-century journalism and development reports, where it reads more compactly in headlines.","cn":"倒序形式在二十世纪新闻与发展报告中流行，因为它在标题里更紧凑。"},{"era":"PLURAL USE","en":"The plural living standards became the usual form when several countries or groups are compared.","cn":"当比较多个国家或群体时，复数形式成为惯用说法。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the earliest use of the reversed form is not recorded, and its rise may have been journalistic rather than academic.","cn":"首见年代不确定：倒序形式的最早用例未被记录，它的流行可能来自新闻而非学术写作。"}]},"similar":{"note":{"en":"Group one contrasts the reversed phrase with its neighbours; group two holds broader words for how well a society lives.","cn":"第一组把这个倒序词组与邻近说法作对比；第二组是描述社会整体生活状况的更宽泛的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"standard of living","ipa":"/ˈstændəd əv ˈlɪvɪŋ/","tag":"same meaning, formal order","definition":"Standard of living is the same measure in the more formal order and is favoured in statistical writing.","definitionCN":"生活水平是同一衡量标准的更正式词序，统计写作更偏爱它。"},{"word":"cost of living","ipa":"/kɒst əv ˈlɪvɪŋ/","tag":"prices, not comfort","definition":"The cost of living is the price of maintaining a household; the living standard is the comfort actually achieved.","definitionCN":"生活成本是维持一个家庭所需的价钱；生活水准是实际达到的舒适程度。"},{"word":"living wage","ipa":"/ˈlɪvɪŋ weɪdʒ/","tag":"income floor, not a measure","definition":"A living wage is the pay needed to cover basic needs, one input into a living standard rather than the whole measure.","definitionCN":"基本生活工资是覆盖基本需要所需的报酬，只是生活水准的一个投入，而非整体衡量。"},{"word":"living conditions","ipa":"/ˈlɪvɪŋ kənˈdɪʃənz/","tag":"concrete circumstances","definition":"Living conditions are the concrete facts of housing, sanitation and safety, while the living standard summarises them as a level.","definitionCN":"生活条件指住房、卫生与安全等具体事实，生活水准则把它们概括成一个高低。"}]},{"heading":"NEAR MEANING","entries":[{"word":"wellbeing","ipa":"/ˌwelˈbiːɪŋ/","tag":"wider than material comfort","definition":"Wellbeing covers health, security and satisfaction, of which a living standard is only the material part.","definitionCN":"福祉涵盖健康、安全与满足感，生活水准只是其中的物质部分。"},{"word":"prosperity","ipa":"/prəˈsperəti/","tag":"economic success","definition":"Prosperity is the success of an economy, a condition that usually lifts living standards.","definitionCN":"繁荣是经济的成功状态，通常会抬升生活水准。"},{"word":"quality of life","ipa":"/ˈkwælɪti əv laɪf/","tag":"includes the non-material","definition":"Quality of life adds freedom, environment and happiness to the material level.","definitionCN":"生活质量在物质水准之外加上自由、环境与幸福感。"},{"word":"deprivation","ipa":"/dɪˌpraɪˈveɪʃən/","tag":"the low end of the scale","definition":"Deprivation names the lack of basic goods and services, the bottom of any living standard scale.","definitionCN":"匮乏指基本商品与服务的缺失，是任何生活水准尺度的底端。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real halves, real comparisons and real headlines.","cn":"正常联想：真实的构词两半、真实的比较与真实的标题用法。"},"normal":[{"en":"The word order is reversed but the measuring idea is identical.","cn":"词序是倒的，衡量思路却完全一样。"},{"en":"It is the compact form that fits headlines and development reports.","cn":"它是适合标题与发展报告的紧凑形式。"},{"en":"The plural is usual when countries or income groups are compared.","cn":"比较国家或收入群体时，复数形式更常用。"},{"en":"A living wage is an input; the living standard is the outcome.","cn":"基本生活工资是投入，生活水准是结果。"},{"en":"It rises and falls with prices as much as with pay.","cn":"它既随工资起落，也随物价起落。"}],"abstract":[{"en":"Picture the same ruler turned around in the hand: the markings have not changed.","cn":"想象同一把尺在手中转了个方向，刻度并没有变。"},{"en":"Picture a village where a new clinic counts as part of the family's comfort.","cn":"想象一个村庄，新开的诊所也算进家庭舒适的一部分。"},{"en":"Picture a headline that fits a whole generation's hope into two words.","cn":"想象一个标题，把一整代人的盼望压进两个词。"}]},"examples":[{"en":"Living standards in the province rose steadily after electricity reached the villages.","cn":"电力进入村庄后，该省的生活水准稳步上升。"},{"en":"The two phrases are interchangeable, though reports often prefer the longer one.","cn":"这两个说法可以互换，不过报告常偏爱较长的那个。"},{"en":"Living standards are measured differently in rural and urban surveys.","cn":"农村与城市调查衡量生活水准的方式不同。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「生活」加「标准」——把日子摆在尺子旁边看高低，就是生活水准","word":"living standard"},"root":"前半为古英语本族词，意为「活着、谋生」；后半经古法语 estandart「旗帜、集合点」进入英语，可能出自法兰克语重构形式，来源不确定。两部分倒序组合，含义与「生活水平」相同。","sensesIntro":{"en":"Eight senses follow one reversed measure: a level is applied to life itself, then to income, to food and shelter, to regions, to a floor, to generations, to groups and to public services.","cn":"八个义项沿同一个倒过来的衡量展开：先给生活标高低，再依次用于收入、食宿、地区、底线、世代、群体与公共服务。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same measuring rod turned around in the hand, its markings unchanged.","cn":"核心意象：同一把量尺在手中转了个方向，刻度没有变。"},"chain":["LIVE","EARN INCOME","ADEQUATE FOOD AND SHELTER","COMPARE REGIONS","SET A FLOOR","BETTER OVER TIME"],"branches":[{"senses":"01 · 02","en":"THE MEASURE: comfort is first estimated from goods and then from income.","cn":"衡量：舒适先由商品估算，再由收入估算。"},{"senses":"03 · 08","en":"THE NECESSITIES: food, shelter and public services define the base of the scale.","cn":"必需之物：食物、住所与公共服务界定尺度的底座。"},{"senses":"04","en":"SIDE BY SIDE: a level appears only when two places are compared.","cn":"并列：水准只有在两地相比时才显现。"},{"senses":"05","en":"THE FLOOR: the same rod can mark the line nobody should fall below.","cn":"底线：同一把尺也能标出任何人都不该跌破的线。"},{"senses":"06 · 07","en":"ACROSS TIME AND GROUPS: expectations rise, and plural forms compare whole populations.","cn":"跨时间与群体：期待上移，复数形式用来比较整群人口。"}]},"affixes":{"intro":{"en":"The phrase is a reversed twin of standard of living; both halves also build ordinary English words.","cn":"这个词组是「生活水平」的倒序孪生形式，两部分也构成普通英语词。"},"latinIntro":{"en":"No Latin source is involved: both halves are either native English or Frankish through French.","cn":"这里不涉及拉丁语来源：两半要么是英语本族词，要么经法语来自法兰克语。"},"items":[{"word":"living","structure":"Old English libban + -ing (noun suffix)","meaning":"the state of being alive","meaningCN":"生活；生计","example":"Living costs have risen faster than wages.","exampleCN":"生活成本涨得比工资快。"},{"word":"live","structure":"Old English libban (verb)","meaning":"to be alive","meaningCN":"活着；居住","example":"They live beside the new road.","exampleCN":"他们住在新公路旁。"},{"word":"livable","structure":"live + -able (adjective suffix)","meaning":"fit to live in","meaningCN":"适宜居住的","example":"The rebuilt quarter is more livable.","exampleCN":"重建的街区更宜居。"},{"word":"livelihood","structure":"live + -lihood (noun suffix)","meaning":"means of supporting life","meaningCN":"生计","example":"Tourism gave the village a new livelihood.","exampleCN":"旅游业给村庄带来新的生计。"},{"word":"standard","structure":"Old French estandart (banner, authorized measure)","meaning":"an accepted measure","meaningCN":"标准；水准","example":"The clinic meets the national standard.","exampleCN":"这家诊所达到了国家标准。"},{"word":"standardize","structure":"standard + -ize (verb suffix)","meaning":"to make uniform","meaningCN":"使标准化","example":"The province standardized rural clinics.","exampleCN":"该省把农村诊所标准化。"},{"word":"standardization","structure":"standardize + -ation (noun suffix)","meaning":"the act of making uniform","meaningCN":"标准化","example":"Standardization improved rural care.","exampleCN":"标准化改善了农村医疗。"},{"word":"standardize","structure":"standard + -ize (verb suffix)","meaning":"to make uniform","meaningCN":"使标准化","example":"Standards were unified across counties.","exampleCN":"各县的标准被统一起来。"}],"latinEntries":[],"derivatives":[{"word":"living","pos":"n./adj.","zh":"生活；活着的"},{"word":"standard","pos":"n./adj.","zh":"标准；标准的"},{"word":"livable","pos":"adj.","zh":"适宜居住的"},{"word":"livelihood","pos":"n.","zh":"生计"},{"word":"standardize","pos":"v.","zh":"使标准化"},{"word":"standardization","pos":"n.","zh":"标准化"}]}},{"word":"poverty","ipa_uk":"/ˈpɒvəti/","ipa_us":"/ˈpɑːvərti/","definition_zh":"贫穷；贫困；缺乏钱财与基本生活资源的状态；也指某种东西的匮乏或贫瘠","definition_en":"the state of being extremely poor, lacking the money and resources needed for basic living; also a general scarcity or barrenness","core_image":"一只空碗放在缺了角的桌上，窗外的田里只长着稀疏的草，屋里屋外都显出「不够」","scene":"救济站里的登记表写满了名字，很多人连过冬的煤都买不起。The charity works to reduce poverty among families in the river valley.","sceneCN":"此处指「缺乏钱财与基本生活资源的状态」（第 1 个义项：缺钱维持基本生活）；句意为这家慈善机构致力于减轻河谷家庭的贫困。图中可辨识物件：空碗、破桌、稀疏的田草、救济登记表。","pos":[{"tag":"n.","zh":"贫穷；贫困（缺乏基本生活资源的状态）"},{"tag":"n.","zh":"匮乏；贫瘠（某种东西数量少或质量差）"}],"collocations":[{"phrase":"extreme poverty","zh":"极端贫困"},{"phrase":"relative poverty","zh":"相对贫困"},{"phrase":"poverty line","zh":"贫困线"},{"phrase":"live in poverty","zh":"生活在贫困中"},{"phrase":"escape poverty","zh":"摆脱贫困"},{"phrase":"poverty of resources","zh":"资源的匮乏"},{"phrase":"poverty of ideas","zh":"思想的贫乏"}],"forms":[{"label":"单数","form":"poverty"},{"label":"复数（罕见，指多种贫困状况）","form":"poverties"}],"derivatives":[{"word":"poor","pos":"adj.","zh":"贫穷的；差的"},{"word":"poorly","pos":"adv.","zh":"差地；身体不适地"},{"word":"impoverish","pos":"v.","zh":"使贫穷；使贫瘠"},{"word":"impoverished","pos":"adj.","zh":"贫困的；贫瘠的"},{"word":"impoverishment","pos":"n.","zh":"贫困化；贫瘠化"},{"word":"poverty-stricken","pos":"adj.","zh":"饱受贫困之苦的"}],"senses":[{"no":"01","title":"Lack of money for basic needs","titleCN":"缺钱满足基本需要","definition":"the condition of not having enough money to pay for food, shelter, clothing and health care","definitionCN":"没有足够的钱支付食物、住房、衣着与医疗","example":"Half the village lives in poverty and often skips meals.","exampleCN":"村里一半人生活在贫困中，常常省掉饭食。","why":"The word names a shortage of the means of living, so its core sense is money that does not stretch to necessities.","whyCN":"这个词命名的是维生手段的短缺，因此核心义就是钱不足以覆盖基本需要。"},{"no":"02","title":"The state of being poor","titleCN":"贫穷的状态","definition":"the ongoing social condition of being poor, with its insecurity and limited choices","definitionCN":"长期处于贫穷的社会状态，伴随不安全与选择受限","example":"Poverty traps families in unsafe housing and unstable work.","exampleCN":"贫困把家庭困在不安全的住房与不稳定的工作里。","why":"Poverty is not only a moment of shortage but a condition that persists and shapes a life.","whyCN":"贫困不只是一时的短缺，而是一种持续并塑造生活的状态。"},{"no":"03","title":"Officially measured deprivation","titleCN":"官方测量的匮乏","definition":"the level of deprivation defined by income falling below a government or research threshold","definitionCN":"以收入低于政府或研究机构设定的门槛来界定的匮乏程度","example":"The census reports poverty by counting households below the threshold.","exampleCN":"人口普查通过统计低于门槛的家庭来报告贫困。","why":"Modern states turned an old condition into a number by drawing a line and counting who falls under it.","whyCN":"现代国家画一条线、数清线下人数，把古老的处境变成了数字。"},{"no":"04","title":"Scarcity of a resource","titleCN":"某种资源的短缺","definition":"a serious shortage of something needed, such as water, soil nutrients or energy","definitionCN":"水、土壤养分或能源等必需品严重不足","example":"Poverty of rainfall kept the fields bare for months.","exampleCN":"降雨稀少让田地空了好几个月。","why":"The idea of having too little extends from money to any resource, which gives the word its scarcity sense.","whyCN":"「拥有的太少」这一想法从钱扩展到任何资源，于是有了短缺义。"},{"no":"05","title":"Barrenness or poor quality","titleCN":"贫瘠或低劣","definition":"the state of land or material being thin, worn out or lacking richness","definitionCN":"土地或材料稀薄、耗竭、缺乏肥力的状态","example":"The poverty of the soil forced farmers to move every few years.","exampleCN":"土壤贫瘠迫使农民每隔几年就迁移。","why":"Land that yields little looks poor in the same way a person with little money does, so the word describes thinness of quality.","whyCN":"产出很少的土地，看起来就像缺钱的人一样「穷」，于是这个词也描述质地的贫薄。"},{"no":"06","title":"Lack of ideas or imagination","titleCN":"思想或想象力的贫乏","definition":"the quality of being unoriginal, thin or lacking intellectual substance","definitionCN":"缺乏创意、内容单薄、思想贫乏的性质","example":"Critics attacked the poverty of the plan's imagination.","exampleCN":"批评者抨击这份计划想象力的贫乏。","why":"If a field can be poor, so can an argument, and the metaphor of thinness carries over to thought.","whyCN":"田地可以贫瘠，论证也可以，贫薄这个比喻就延伸到思想上。"},{"no":"07","title":"Voluntary humility in religious writing","titleCN":"宗教写作中自愿的谦卑","definition":"the deliberate giving up of worldly wealth or self-importance, especially in religious tradition","definitionCN":"尤其在宗教传统中，主动放弃世俗财富或自我重要感","example":"Monks took a vow of poverty and owned nothing.","exampleCN":"修士立下守贫之愿，不拥有任何财物。","why":"Religious tradition reframed lack as a virtue when it is chosen, so poverty gained a voluntary, spiritual sense.","whyCN":"宗教传统把自愿的缺乏重新解释为美德，于是贫困获得了自愿的、精神性的义项。"},{"no":"08","title":"Destitution and dependence on charity","titleCN":"赤贫与依赖救济","definition":"the extreme end of poverty in which a person depends on begging or public relief to survive","definitionCN":"贫困的极端一端，人靠乞讨或公共救济才能活下去","example":"The old poorhouse sheltered people reduced to poverty.","exampleCN":"旧时的济贫院收容陷入赤贫的人。","why":"At its worst the condition leaves a person with nothing to sell but labour or appeal, and this is the destitution sense.","whyCN":"到最严重时，人除了劳力或求助已无物可售，这就是赤贫义。"}],"etymology":{"intro":{"en":"Poverty comes from Latin paupertas, the abstract noun of pauper 'poor', through Old French. The deeper origin of pauper is not established. Dates are approximate.","cn":"该词经古法语来自拉丁语 paupertas，即 pauper「贫穷」的抽象名词。pauper 的更早来源未查明。年代均为约数。"},"items":[{"era":"LATIN PAUPER","en":"Pauper meant 'poor, needy'. Its deeper origin is not established; the old link to a root meaning 'produce little' is a hypothesis.","cn":"pauper 意为「贫穷、匮乏」。其更深来源无定论；把它与表示「产出很少」的词根相联系的旧说只是假说。"},{"era":"LATIN PAUPERTAS","en":"Paupertas 'poverty, want' was the abstract noun, and it passed into Old French as poverte.","cn":"paupertas「贫穷、匮乏」是对应的抽象名词，后来变成古法语的 poverte。"},{"era":"OLD FRENCH POVERTE","en":"Old French poverte entered English in the thirteenth century, naming both the condition and the lack of goods.","cn":"古法语 poverte 于十三世纪进入英语，既指贫穷状态，也指物品的匮乏。"},{"era":"RELIGIOUS SENSE","en":"Religious writing used poverty of spirit for voluntary humility, a sense that survives in set phrases.","cn":"宗教文献用「精神上的贫穷」指自愿的谦卑，这一义项保留在固定说法里。"},{"era":"ECONOMIC MEASURE","en":"From the nineteenth century poverty became an object of social measurement, defined by income against a line.","cn":"从十九世纪起，贫穷成为社会测量对象，以收入是否低于某条线来界定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (pre-Latin origin of pauper): no agreed Indo-European etymology exists, and the date of the abstract noun is approximate.","cn":"来源不确定（pauper 的拉丁语之前来源）：没有公认的印欧语词源，抽象名词的年代为约数。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but come from other roots; group two holds words for hardship and shortage.","cn":"第一组是形近或音近却另有词源的词；第二组是表示困苦与短缺的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"property","ipa":"/ˈprɒpəti/","tag":"different root","definition":"Property comes from Latin proprietas 'ownership', built on proprius 'one's own'; it has nothing to do with pauper.","definitionCN":"财产来自拉丁 proprietas「所有权」，出自 proprius「自己的」，与 pauper 毫无关系。"},{"word":"propriety","ipa":"/prəˈpraɪəti/","tag":"different root","definition":"Propriety also goes back to proprius and means correctness of behaviour, not lack of money.","definitionCN":"礼节同样出自 proprius，指行为得体，与缺钱无关。"},{"word":"paucity","ipa":"/ˈpɔːsəti/","tag":"small quantity, different root","definition":"Paucity means a small number or amount and comes from Latin paucus 'few'; it is a near neighbour in meaning but not in root.","definitionCN":"少量来自拉丁 paucus「少」，意思相近，词根却不同。"},{"word":"poor","ipa":"/pɔː/","tag":"the adjective behind the noun","definition":"Poor is the everyday adjective related to poverty, but it comes through Old French povre from the same Latin pauper.","definitionCN":"poor 是与贫穷相关的日常形容词，经古法语 povre 来自同一个拉丁 pauper。"}]},{"heading":"NEAR MEANING","entries":[{"word":"destitution","ipa":"/ˌdestɪˈtjuːʃən/","tag":"the extreme end","definition":"Destitution is poverty so severe that a person lacks food, shelter and any means of recovery.","definitionCN":"赤贫是严重到缺乏食物、住所与任何恢复手段的贫困。"},{"word":"deprivation","ipa":"/dɪˌpraɪˈveɪʃən/","tag":"lack of necessities","definition":"Deprivation stresses the absence of specific necessities such as heating, food or schooling.","definitionCN":"匮乏强调取暖、食物或教育等具体必需品的缺失。"},{"word":"hardship","ipa":"/ˈhɑːdʃɪp/","tag":"suffering from difficulty","definition":"Hardship is suffering caused by difficult conditions, which may occur without absolute poverty.","definitionCN":"困苦是艰难处境带来的痛苦，未必达到绝对贫困。"},{"word":"scarcity","ipa":"/ˈskɑːsəti/","tag":"short supply of a resource","definition":"Scarcity is a short supply of a particular resource and is the general form of the resource sense.","definitionCN":"稀缺指某种资源供应不足，是资源义的一般化形式。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin base, real relatives and real fixed phrases.","cn":"正常联想：真实的拉丁词根、真实的同族词与真实的固定搭配。"},"normal":[{"en":"The Latin base means poor, and the abstract ending turns it into the state of being poor.","cn":"拉丁词根意为贫穷，抽象后缀把它变成「贫穷的状态」。"},{"en":"The everyday adjective and the formal noun belong to the same family.","cn":"日常形容词与正式名词属于同一词族。"},{"en":"Fixed phrases carry the measured sense: poverty line, relative poverty, extreme poverty.","cn":"固定说法承载测量义：贫困线、相对贫困、极端贫困。"},{"en":"The same word can describe thin soil or a thin argument, because both are forms of not having enough.","cn":"同一个词既能形容贫瘠的土壤，也能形容单薄的论证，因为两者都是「不够」。"},{"en":"Religious tradition added the voluntary sense: a vow of poverty is a choice, not a misfortune.","cn":"宗教传统加上自愿义：守贫之愿是选择，而非不幸。"}],"abstract":[{"en":"Picture a bowl that is always half empty, however often it is filled.","cn":"想象一只碗，无论添多少次，总有一半是空的。"},{"en":"Picture a field that grows grass but never grain.","cn":"想象一块地只长草，从不结粮。"},{"en":"Picture a room full of furniture and still somehow bare.","cn":"想象一间堆满家具却仍显得空荡的屋子。"}]},"examples":[{"en":"The programme cut poverty among older people by raising the basic pension.","cn":"该项目通过提高基本养老金减少了老年人的贫困。"},{"en":"Poverty of data made the report's conclusions uncertain.","cn":"数据的匮乏让报告的结论难以确定。"},{"en":"She took a vow of poverty and gave away her inheritance.","cn":"她立下守贫之愿，把继承的财产捐了出去。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「破屋」——屋顶漏风、米缸见底，就是贫穷；记住「破」与「贫」的连带感","word":"poverty"},"root":"拉丁 pauper「贫穷」经古法语进入英语，加上抽象名词后缀构成 paupertas「贫穷、匮乏」，再演变为今天的贫穷一词；pauper 的拉丁语之前来源不确定，相关词根联系多为假说。","sensesIntro":{"en":"Eight senses follow one shortage: money is missing, then the condition persists, is counted, is extended to resources, to soil, to thought, to chosen humility and finally to total destitution.","cn":"八个义项沿同一种「短缺」展开：先是缺钱，继而状态持续、被计数，再扩展到资源、土壤、思想、自愿的谦卑，最后到一无所有。"},"semanticMap":{"core":{"en":"CORE IMAGE: an empty bowl on a broken table, with thin grass outside and an empty coal sack by the door.","cn":"核心意象：缺角桌上的空碗，窗外稀疏的草，门边空着的煤袋。"},"chain":["LACK MONEY","FALL BELOW SUFFICIENCY","OFFICIAL DEPRIVATION","SCARCE RESOURCE","BARREN QUALITY","EMPTINESS OF MIND"],"branches":[{"senses":"01 · 02","en":"THE SHORTAGE ITSELF: money is missing, and the lack settles into a lasting condition.","cn":"短缺本身：钱不够，而且这种缺乏沉淀为持久状态。"},{"senses":"03","en":"THE COUNT: a line is drawn and the condition becomes an official number.","cn":"计数：画一条线，处境就变成官方数字。"},{"senses":"04 · 05","en":"FROM MONEY TO MATERIAL: the same thinness describes a scarce resource and barren soil.","cn":"从钱到物：同一种「薄」也能形容短缺的资源与贫瘠的土壤。"},{"senses":"06","en":"THIN THOUGHT: an argument can be as poor as a field.","cn":"单薄的思想：论证可以像田地一样贫瘠。"},{"senses":"07 · 08","en":"CHOSEN AND TOTAL LACK: lack becomes a vow at one end and destitution at the other.","cn":"自愿的与彻底的缺乏：一端是守贫之愿，另一端是赤贫。"}]},"affixes":{"intro":{"en":"Poverty is a Latin abstract noun that grew a wide metaphorical reach in English, from money to soil to ideas.","cn":"贫穷是一个拉丁抽象名词，在英语里长出了很宽的比喻范围，从金钱到土壤再到思想。"},"latinIntro":{"en":"Pauper and paupertas supply the core; English added the adjective, the verb and several compounds.","cn":"pauper 与 paupertas 提供核心，英语再加形容词、动词与若干复合词。"},"items":[{"word":"poverty","structure":"paupertas (Latin noun) through Old French","meaning":"the state of being poor","meaningCN":"贫穷；匮乏","example":"Poverty kept the family in one room.","exampleCN":"贫穷让这家人挤在一个房间。"},{"word":"poor","structure":"pauper (Latin adjective) through Old French","meaning":"having little money","meaningCN":"贫穷的；差的","example":"The poorest households lack heating.","exampleCN":"最贫困的家庭缺少取暖。"},{"word":"poorly","structure":"poor + -ly (adverb suffix)","meaning":"in a poor way; also unwell","meaningCN":"差地；身体不适地","example":"The clinic was poorly supplied.","exampleCN":"这家诊所物资供应很差。"},{"word":"impoverish","structure":"en- (prefix 'make') + poverty (noun)","meaning":"to make poor or thin","meaningCN":"使贫穷；使贫瘠","example":"Debt impoverished the whole district.","exampleCN":"债务使整个城区陷入贫困。"},{"word":"impoverished","structure":"impoverish + -ed (adjective suffix)","meaning":"made poor","meaningCN":"贫困的；贫瘠的","example":"The soil was impoverished by years of planting.","exampleCN":"连年种植使土壤贫瘠。"},{"word":"impoverishment","structure":"impoverish + -ment (noun suffix)","meaning":"the process of becoming poor","meaningCN":"贫困化；贫瘠化","example":"Impoverishment followed the closure of the mine.","exampleCN":"矿井关闭后出现了贫困化。"},{"word":"poverty-stricken","structure":"poverty + stricken (compound adjective)","meaning":"struck by poverty","meaningCN":"饱受贫困之苦的","example":"Aid reached the poverty-stricken villages late.","exampleCN":"援助很晚才到达饱受贫困之苦的村庄。"},{"word":"paucity","structure":"paucus (Latin adjective 'few') + -ity (noun suffix)","meaning":"a small number or amount","meaningCN":"少量；缺乏","example":"A paucity of evidence weakened the case.","exampleCN":"证据不足削弱了论点。"}],"latinEntries":[{"word":"pauper","structure":"pauper, pauperis (adj., third declension)","meaning":"poor, needy","meaningCN":"贫穷的；匮乏的"},{"word":"paupertas","structure":"paupertas, paupertatis (f., third declension)","meaning":"poverty, want","meaningCN":"贫穷；匮乏"},{"word":"pauperies","structure":"pauperies, pauperiei (f., fifth declension)","meaning":"poverty, scarcity","meaningCN":"贫穷；短缺"}],"derivatives":[{"word":"poor","pos":"adj.","zh":"贫穷的；差的"},{"word":"poorly","pos":"adv.","zh":"差地；身体不适地"},{"word":"impoverish","pos":"v.","zh":"使贫穷；使贫瘠"},{"word":"impoverished","pos":"adj.","zh":"贫困的；贫瘠的"},{"word":"impoverishment","pos":"n.","zh":"贫困化；贫瘠化"},{"word":"poverty-stricken","pos":"adj.","zh":"饱受贫困之苦的"}]}},{"word":"poverty rate","ipa_uk":"/ˈpɒvəti reɪt/","ipa_us":"/ˈpɑːvərti reɪt/","definition_zh":"贫困率；收入低于贫困线的人口占全部人口的比例","definition_en":"the share of a population whose income falls below the poverty line, usually expressed as a percentage","core_image":"一条画在地上的线把人群分成两半，站在线下的人被逐一计数，比例写进表格","scene":"统计局把城乡家庭的收入逐户核对，再算出一条线以下的人占多少。The poverty rate fell after the new benefit reached rural households.","sceneCN":"此处指「收入低于贫困线的人口占全部人口的比例」（第 1 个义项：在线人数所占比例）；句意为新补贴覆盖农村家庭之后贫困率下降。图中可辨识物件：地面上的分界线、计数的表格、家庭账簿、百分比刻度。","pos":[{"tag":"n.","zh":"贫困率（低于贫困线人口所占比例）"},{"tag":"n.","zh":"（特定口径的）贫困人口比率"}],"collocations":[{"phrase":"the official poverty rate","zh":"官方贫困率"},{"phrase":"a rising poverty rate","zh":"上升的贫困率"},{"phrase":"the child poverty rate","zh":"儿童贫困率"},{"phrase":"the poverty rate before transfers","zh":"转移支付前的贫困率"},{"phrase":"reduce the poverty rate","zh":"降低贫困率"},{"phrase":"measure the poverty rate","zh":"测量贫困率"}],"forms":[{"label":"单数","form":"poverty rate"},{"label":"复数（不同群体或不同地区的贫困率）","form":"poverty rates"}],"derivatives":[{"word":"poverty","pos":"n.","zh":"贫穷；贫困"},{"word":"poor","pos":"adj.","zh":"贫穷的"},{"word":"rate","pos":"n.","zh":"比率；速度"},{"word":"rating","pos":"n.","zh":"评级；评分"},{"word":"ratio","pos":"n.","zh":"比；比例"},{"word":"impoverished","pos":"adj.","zh":"贫困的"}],"senses":[{"no":"01","title":"Share below the poverty line","titleCN":"低于贫困线的人口比例","definition":"the proportion of people whose household income is below the official poverty line","definitionCN":"家庭收入低于官方贫困线的人所占比例","example":"The poverty rate rose when wages failed to keep up with rents.","exampleCN":"当工资跟不上租金时，贫困率上升了。","why":"A rate is a fixed proportion, so the phrase first means the counted share of people under the line.","whyCN":"比率就是固定的比例，因此这个词组首先指线下人口被计数后所占的份额。"},{"no":"02","title":"Official headcount ratio","titleCN":"官方人头比率","definition":"the government's headline measure, computed by counting people below the line rather than by measuring the depth of their shortfall","definitionCN":"政府的首要指标，按线下人数计算，而不衡量缺口深浅","example":"The official poverty rate ignores how far below the line some households fall.","exampleCN":"官方贫困率不衡量有些家庭距线以下有多远。","why":"Counting heads is the simplest way to produce a rate, which is why the headcount version dominates official reports.","whyCN":"数人头是得出比率最简单的办法，因此人头口径主导官方报告。"},{"no":"03","title":"Rate for a subgroup","titleCN":"特定群体的贫困率","definition":"the poverty rate calculated for one group such as children, older people or a region","definitionCN":"针对儿童、老年人或某地区等单一群体计算的贫困率","example":"The child poverty rate is twice the rate for the population as a whole.","exampleCN":"儿童贫困率是总人口贫困率的两倍。","why":"Any population can be divided into groups, and each group can have its own share below the line.","whyCN":"任何人口都能分成群体，每个群体都可以有自己线下的比例。"},{"no":"04","title":"Rate before taxes and transfers","titleCN":"转移支付前的贫困率","definition":"the share of people below the line when only market income is counted","definitionCN":"只计算市场收入时线下人口所占比例","example":"The poverty rate before taxes is much higher than the rate after benefits.","exampleCN":"税前贫困率远高于补贴后的贫困率。","why":"The order of counting matters: market income alone leaves out the effect of taxes and benefits.","whyCN":"计数的次序很关键：只看市场收入，就漏掉税收与补贴的作用。"},{"no":"05","title":"Rate after taxes and transfers","titleCN":"转移支付后的贫困率","definition":"the share of people below the line once taxes and benefits have changed their disposable income","definitionCN":"税收与补贴改变可支配收入之后线下人口所占比例","example":"Benefits cut the poverty rate among pensioners by half.","exampleCN":"补贴把领取养老金者的贫困率降低了一半。","why":"Redistribution changes the income that is compared with the line, so the same population can yield a much lower rate.","whyCN":"再分配改变了与贫困线比较的收入，因此同一群人可以得出低得多的比率。"},{"no":"06","title":"Child poverty rate","titleCN":"儿童贫困率","definition":"the share of children living in households below the line, a widely used welfare indicator","definitionCN":"生活在贫困线以下家庭的儿童所占比例，是广泛使用的福利指标","example":"The child poverty rate stayed high even as the overall rate fell.","exampleCN":"即使总贫困率下降，儿童贫困率仍居高不下。","why":"Children cannot earn, so their rate reflects household income and is treated as a distinct policy measure.","whyCN":"儿童不能挣钱，因此其比率反映家庭收入，被当作独立的政策指标。"},{"no":"07","title":"Internationally comparable rate","titleCN":"国际可比的贫困率","definition":"a rate adjusted to a common threshold so that countries can be compared","definitionCN":"按共同门槛调整后使各国可以比较的比率","example":"Researchers compare the poverty rate across countries using a shared line.","exampleCN":"研究者用一条共同的门槛比较各国贫困率。","why":"Comparison requires a common line and a common income definition, otherwise the rates are not the same thing.","whyCN":"比较需要共同的门槛与收入定义，否则两个比率并不是同一回事。"},{"no":"08","title":"Disputed measurement choice","titleCN":"存在争议的测量口径","definition":"the rate as a subject of argument about line, income definition and treatment of benefits","definitionCN":"围绕贫困线、收入定义与补贴处理方式产生争论的比率","example":"Two agencies published different poverty rates for the same year.","exampleCN":"两个机构为同一年份公布了不同的贫困率。","why":"Because the rate depends on where the line is drawn and what counts as income, it is always open to methodological dispute.","whyCN":"比率取决于线画在哪里、什么算收入，因此总会有方法上的争论。"}],"etymology":{"intro":{"en":"Poverty rate joins a Latin-derived noun for want with a Latin-derived noun for a fixed proportion. The compound belongs to modern social statistics. Dates are approximate.","cn":"贫困率由两个拉丁来源的名词组成：一个表示匮乏，一个表示固定比例。这个复合词属于现代社会统计。年代均为约数。"},"items":[{"era":"LATIN RATA","en":"Rate comes from Latin rata (pars) 'a fixed portion', from reri 'to reckon', and entered English through Old French.","cn":"比率来自拉丁语 rata（pars）「固定的份额」，出自 reri「计算」，经古法语进入英语。"},{"era":"MEDIEVAL RATE","en":"Medieval use fixed rate as an assessed charge or proportion, the ancestor of the modern ratio sense.","cn":"中世纪用该词指核定的费用或比例，是现代「比率」义的祖先。"},{"era":"THE POVERTY LINE","en":"The poverty line was devised in the nineteenth and early twentieth centuries as an income threshold for minimal needs.","cn":"贫困线在十九世纪与二十世纪初被设计出来，作为最低需要的收入门槛。"},{"era":"THE COMPOUND","en":"Poverty rate became common in twentieth-century social statistics as the share of people below that line.","cn":"贫困率在二十世纪社会统计中流行，指线下人口所占份额。"},{"era":"POLICY USE","en":"Governments adopted the rate as a headline indicator for welfare policy and international comparison.","cn":"各国政府把这个比率作为福利政策与国际比较的首要指标。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the exact first use of the compound is unrecorded, and definitions of the line vary by country.","cn":"首见年代不确定：这一复合词的最早用例未被记录，贫困线的定义也因国而异。"}]},"similar":{"note":{"en":"Group one separates rates and ratios that are easily swapped; group two holds measures of poverty and count.","cn":"第一组区分容易互换的比率与比例；第二组是衡量贫穷与计数的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"poverty line","ipa":"/ˈpɒvəti laɪn/","tag":"threshold, not a share","definition":"The poverty line is the income threshold itself; the poverty rate is the share of people below it.","definitionCN":"贫困线是收入门槛本身；贫困率是线下人口所占比例。"},{"word":"poverty gap","ipa":"/ˈpɒvəti ɡæp/","tag":"depth, not headcount","definition":"The poverty gap measures how far incomes fall short of the line, while the rate counts how many people do.","definitionCN":"贫困缺口衡量收入距线差多少，贫困率则数有多少人。"},{"word":"poor rate","ipa":"/pɔː reɪt/","tag":"historical tax, different meaning","definition":"The historical poor rate was a local tax for relief of the poor, not a share of the population.","definitionCN":"历史上的济贫税是用于救济穷人的地方税，不是人口比例。"},{"word":"ratio","ipa":"/ˈreɪʃiəʊ/","tag":"the general proportion","definition":"Ratio is the general term for one quantity divided by another; rate is the fixed-proportion word used here.","definitionCN":"比例是一个量除以另一个量的一般说法；比率在这里指固定的份额。"}]},{"heading":"NEAR MEANING","entries":[{"word":"incidence of poverty","ipa":"/ˈɪnsɪdəns əv ˈpɒvəti/","tag":"how often it occurs","definition":"Incidence of poverty is the frequency with which poverty appears in a population, close to the headcount rate.","definitionCN":"贫困发生率是贫困在人口中出现的频率，接近人头比率。"},{"word":"deprivation index","ipa":"/dɪˌpraɪˈveɪʃən ˈɪndeks/","tag":"composite measure","definition":"A deprivation index combines several lacks into one score instead of counting people below a single line.","definitionCN":"匮乏指数把多项缺失合成一个分数，而不是按单一门槛数人头。"},{"word":"headcount ratio","ipa":"/ˈhedkaʊnt ˈreɪʃiəʊ/","tag":"the counting method","definition":"Headcount ratio is the technical name for the share of people below the line.","definitionCN":"人头比率是线下人口所占比例的技术名称。"},{"word":"poverty headcount","ipa":"/ˈpɒvəti ˈhedkaʊnt/","tag":"the number itself","definition":"Poverty headcount is the raw number of poor people, from which a rate is then calculated.","definitionCN":"贫困人头数是穷人的原始人数，比率由此算出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real parts, real statistical phrases and real distinctions.","cn":"正常联想：真实的构词部分、真实的统计说法与真实的区分。"},"normal":[{"en":"A rate is a fixed proportion, so the phrase always divides one group by a larger one.","cn":"比率是固定份额，因此这个词组总是把一部分人除以全体。"},{"en":"The line is the threshold; the rate is the share below it. Keeping the two apart prevents confusion.","cn":"线是门槛，率是线下份额；把两者分开就不会混淆。"},{"en":"Before and after benefits give two different rates for the same population.","cn":"补贴前后，同一群人会得出两个不同的比率。"},{"en":"The child rate is watched separately because children cannot earn their way out.","cn":"儿童比率被单独关注，因为儿童无法靠挣钱脱困。"},{"en":"Comparisons across countries need a shared line and a shared income definition.","cn":"跨国比较需要共同的门槛与共同的收入定义。"}],"abstract":[{"en":"Picture a line painted across a room and a person at the door counting who stands on the lower side.","cn":"想象房间里画了一条线，有人在门口数站在低侧的人。"},{"en":"Picture a thermometer where the height of the mercury is the share, not the temperature.","cn":"想象一支温度计，水银高度表示的是比例，而不是温度。"},{"en":"Picture two maps of the same country shaded differently because the lines were drawn at different heights.","cn":"想象同一国家的两张地图，因为线画在不同高度而涂成不同深浅。"}]},"examples":[{"en":"The poverty rate among single-parent families remained above twenty percent.","cn":"单亲家庭的贫困率仍在百分之二十以上。"},{"en":"Official figures report the poverty rate before and after taxes.","cn":"官方数字同时报告税前与税后的贫困率。"},{"en":"A higher poverty line mechanically raises the measured poverty rate.","cn":"提高贫困线会机械地抬高测得的贫困率。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「贫困」加「比率」——先画一条线，再算线下的人占多少，就是贫困率","word":"poverty rate"},"root":"前半经古法语来自拉丁 paupertas「贫穷」，后半来自拉丁 rata（pars）「固定的份额」、出自 reri「计算」。两部分合起来，指低于贫困线者所占的固定比例。","sensesIntro":{"en":"Eight senses follow one division: a line is drawn, people below it are counted, and that count is divided, subgrouped, adjusted for taxes, compared and finally disputed.","cn":"八个义项沿同一次除法展开：画出线，数清线下的人，再做除法、分群体、调税收、作比较，最后引发争论。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line on the floor, a counter at the door, and a table of percentages on the wall.","cn":"核心意象：地上的分界线、门口的计数人、墙上的百分比表格。"},"chain":["COUNT THE POOR","DIVIDE BY POPULATION","HEADCOUNT RATIO","SUBPOPULATION","BEFORE TRANSFERS","AFTER TRANSFERS"],"branches":[{"senses":"01 · 02","en":"THE SHARE: a count of people below the line is divided into a proportion.","cn":"份额：线下人数被换算成一个比例。"},{"senses":"03 · 06","en":"THE SUBGROUP: the same division is repeated for children and other groups.","cn":"子群体：同一次除法在儿童与其他群体上重复。"},{"senses":"04 · 05","en":"THE REDISTRIBUTIVE STEP: counting before and after taxes gives two different rates.","cn":"再分配一步：税前与税后计数得出两个不同比率。"},{"senses":"07","en":"THE SHARED LINE: comparison across countries needs one common threshold.","cn":"共同线：跨国比较需要同一条门槛。"},{"senses":"08","en":"THE ARGUMENT: because the line and income rules vary, the rate can always be disputed.","cn":"争论：线与收入规则可变，比率因此总有争议。"}]},"affixes":{"intro":{"en":"The compound joins a Latin noun for want with a Latin noun for a reckoned share, and both halves build common English words.","cn":"这个复合词把拉丁语的「匮乏」与「计算出的份额」拼在一起，两部分都构成常见英语词。"},"latinIntro":{"en":"Paupertas supplies the first half; rata and reri supply the second, with ratio as a close relative.","cn":"paupertas 提供前半；rata 与 reri 提供后半，ratio 是近亲。"},"items":[{"word":"poverty","structure":"paupertas (Latin noun) through Old French","meaning":"the state of being poor","meaningCN":"贫穷","example":"Poverty remains high in the region.","exampleCN":"该地区贫困程度仍高。"},{"word":"poor","structure":"pauper (Latin adjective) through Old French","meaning":"having little money","meaningCN":"贫穷的","example":"Poor households spend most of their income on rent.","exampleCN":"贫困家庭把大部分收入花在房租上。"},{"word":"rate","structure":"rata (pars) (Latin, 'fixed portion')","meaning":"a proportion or speed","meaningCN":"比率；速度","example":"The rate stayed near eight percent.","exampleCN":"该比率维持在百分之八左右。"},{"word":"rating","structure":"rate + -ing (noun suffix)","meaning":"a classification or score","meaningCN":"评级；评分","example":"The agency issued a credit rating.","exampleCN":"该机构发布了信用评级。"},{"word":"ratio","structure":"ratio (Latin noun, from reri)","meaning":"the relation of one quantity to another","meaningCN":"比；比例","example":"The ratio of poor to rich widened.","exampleCN":"贫富比例扩大了。"},{"word":"ration","structure":"ratio (Latin noun, 'reckoning, share')","meaning":"a fixed allowance","meaningCN":"定量；配给","example":"Wartime rationing fixed each family's share.","exampleCN":"战时配给固定了每家的份额。"},{"word":"ratable","structure":"rate + -able (adjective suffix)","meaning":"able to be assessed","meaningCN":"可估价的；应课税的","example":"The land was ratable for local tax.","exampleCN":"这块地应缴地方税。"},{"word":"poverty-stricken","structure":"poverty + stricken (compound adjective)","meaning":"struck by poverty","meaningCN":"饱受贫困之苦的","example":"Aid reached the poverty-stricken district.","exampleCN":"援助到达了贫困地区。"}],"latinEntries":[{"word":"paupertas","structure":"paupertas, paupertatis (f., third declension)","meaning":"poverty, want","meaningCN":"贫穷；匮乏"},{"word":"rata","structure":"rata (pars) (f., first declension)","meaning":"a fixed portion","meaningCN":"固定的份额"},{"word":"reri","structure":"reri, ratus sum (deponent verb)","meaning":"to reckon, think","meaningCN":"计算；认为"}],"derivatives":[{"word":"poverty","pos":"n.","zh":"贫穷；贫困"},{"word":"poor","pos":"adj.","zh":"贫穷的"},{"word":"rate","pos":"n./v.","zh":"比率；速度 / 评价"},{"word":"rating","pos":"n.","zh":"评级；评分"},{"word":"ratio","pos":"n.","zh":"比；比例"},{"word":"impoverished","pos":"adj.","zh":"贫困的"}]}},{"word":"wealth","ipa_uk":"/welθ/","ipa_us":"/welθ/","definition_zh":"财富；大量钱财与资产；也指丰富、充裕","definition_en":"a large amount of money, property and other valuable assets; also an abundance of something valuable","core_image":"一间库房堆着金条、地契与粮袋，角落里还立着一架书，物质与精神都显得充足","scene":"老人把一生的积蓄、房产与藏书都写进同一份清单。The family's wealth grew from land and trade rather than from wages.","sceneCN":"此处指「大量钱财与资产」（第 1 个义项：可估价的财富总量）；句意为这家人的财富来自土地与贸易，而非工资。图中可辨识物件：金条、地契、粮袋、书架。","pos":[{"tag":"n.","zh":"财富；钱财与资产"},{"tag":"n.","zh":"丰富；大量（用于表示「大量……」的固定结构）"}],"collocations":[{"phrase":"great wealth","zh":"巨额财富"},{"phrase":"a wealth of information","zh":"大量信息"},{"phrase":"a wealth of experience","zh":"丰富的经验"},{"phrase":"accumulate wealth","zh":"积累财富"},{"phrase":"distribute wealth","zh":"分配财富"},{"phrase":"natural wealth","zh":"自然财富"},{"phrase":"the wealth of a nation","zh":"一个国家的财富"}],"forms":[{"label":"单数","form":"wealth"},{"label":"复数（罕见，指多种财富形态）","form":"wealths"}],"derivatives":[{"word":"wealthy","pos":"adj.","zh":"富有的"},{"word":"wealthier","pos":"adj.","zh":"更富有的"},{"word":"wealthiest","pos":"adj.","zh":"最富有的"},{"word":"wealthiness","pos":"n.","zh":"富有"},{"word":"commonweal","pos":"n.","zh":"公共福祉"},{"word":"weal","pos":"n.","zh":"福祉；福利（古义）"}],"senses":[{"no":"01","title":"A large amount of money and assets","titleCN":"大量钱财与资产","definition":"a great quantity of money, property, investments and other valuable things owned by a person or group","definitionCN":"个人或群体拥有的大量金钱、房产、投资及其他贵重物品","example":"Her wealth came from shares in the family firm.","exampleCN":"她的财富来自家族企业的股份。","why":"The word names a large store of what people value, so its first sense is simply the quantity of money and goods held.","whyCN":"这个词命名的是人们所看重之物的大量积蓄，因此第一义就是所持金钱与物品的数量。"},{"no":"02","title":"Total net assets of a person or group","titleCN":"个人或群体的净资产总额","definition":"the total value of assets minus debts, viewed as a stock at a point in time","definitionCN":"资产总值减去负债，作为某一时点的存量看待","example":"The survey measures household wealth as assets minus mortgage debt.","exampleCN":"这项调查把家庭财富算作资产减去房贷。","why":"Accounting turns a pile of possessions into a single net figure, which is the technical stock sense.","whyCN":"会计把一堆财物变成一个净值数字，这就是技术性的存量义。"},{"no":"03","title":"Valuable natural resources","titleCN":"有价值的自然资源","definition":"minerals, fertile land, water, forests and other natural endowments that a place possesses","definitionCN":"一个地方拥有的矿产、沃土、水源、森林等自然禀赋","example":"The region's wealth lay in its forests and rivers.","exampleCN":"该地区的财富在于森林与河流。","why":"A country can be rich without money in banks, because land and resources are also stores of value.","whyCN":"一个国家可以没有银行存款仍然富足，因为土地与资源也是价值储备。"},{"no":"04","title":"Prosperity and wellbeing","titleCN":"繁荣与福祉","definition":"the older sense of a good and flourishing condition, close to welfare rather than to money alone","definitionCN":"较古的义项，指良好兴旺的处境，接近福祉而非单指金钱","example":"The old prayer asked for health and wealth for the household.","exampleCN":"古老的祷词为全家祈求健康与兴旺。","why":"Before it meant money, the word meant a good state of life, and that older flourishing sense still colours religious and ceremonial use.","whyCN":"在指金钱之前，这个词指良好的生活状态，这一较古的兴旺义仍影响宗教与仪式用语。"},{"no":"05","title":"An abundance of a thing","titleCN":"某物的丰富、大量","definition":"a large supply or great amount of something, as in a wealth of detail or experience","definitionCN":"某物的大量供应，如大量细节或丰富经验","example":"The archive offers a wealth of detail about daily life.","exampleCN":"这座档案馆提供了关于日常生活的丰富细节。","why":"Abundance of money and abundance of anything share the same shape, so the word extends to non-material plenty.","whyCN":"钱财的充裕与任何东西的充裕形状相同，因此这个词扩展到非物质的丰富。"},{"no":"06","title":"The collective riches of a society","titleCN":"社会财富总量","definition":"the total stock of valuable assets held by a whole society or economy","definitionCN":"整个社会或经济所持有的有价值资产总量","example":"Economists study how wealth is distributed across the country.","exampleCN":"经济学家研究财富在全国如何分布。","why":"Once the word is applied to a whole society, it names an aggregate stock rather than one person's fortune.","whyCN":"这个词一旦用于整个社会，命名的就是总存量，而非某个人的财产。"},{"no":"07","title":"Inherited or accumulated stock","titleCN":"继承或积累的存量","definition":"riches passed down or built up over time rather than earned in a single transaction","definitionCN":"经继承或长期积累而非一次交易所得的钱财","example":"Much of the family's wealth had been inherited from two generations back.","exampleCN":"这家的财富很多是两代之前继承下来的。","why":"Wealth accumulates, so it often carries the idea of a stock built or handed down across time.","whyCN":"财富会累积，因此常带有跨时间积累或传下的存量意味。"},{"no":"08","title":"The common good in older usage","titleCN":"古义中的公共福祉","definition":"the public good or general wellbeing of a community, preserved in the compound commonweal","definitionCN":"共同体的公共利益或整体福祉，保留在「公共福祉」这一复合词中","example":"Old writers spoke of the wealth of the realm as its common good.","exampleCN":"古代作者把国家的财富说成公共之善。","why":"The oldest sense tied riches to the health of a community, and traces of it survive in formal and historical language.","whyCN":"最古老的义项把财富与共同体的健全相连，其痕迹仍留在正式与历史语体中。"}],"etymology":{"intro":{"en":"Wealth is native English, built from an Old English noun for wellbeing with an abstract suffix. It has no Latin ancestor and dates are approximate.","cn":"财富是英语本族词，由古英语中表示安好的名词加抽象后缀构成。它没有拉丁语祖先，年代均为约数。"},"items":[{"era":"OLD ENGLISH WELA","en":"Wela meant 'wellbeing, prosperity, riches' and was related to the word for 'well'. It described a good condition before it described money.","cn":"wela 意为「安好、兴旺、财富」，与表示「好」的词同源。它先描述良好处境，后描述钱财。"},{"era":"MIDDLE ENGLISH WELTH","en":"The abstract suffix -th turned wela into welth, the state of being well-off, in the Middle English period.","cn":"抽象后缀把 wela 变成 welth，即「富足的状态」，时在中古英语时期。"},{"era":"MEANING NARROWS","en":"By the modern period the material sense of money and property dominated, while the older wellbeing sense survived mainly in compounds and religious language.","cn":"到近现代，金钱与财产的物质义占据主导，较古的安好义主要保存在复合词与宗教语言里。"},{"era":"A WEALTH OF","en":"The phrase a wealth of extended the word from money to any large supply, such as detail, experience or evidence.","cn":"「大量的」这一说法把词义从金钱扩展到任何大量供应，如细节、经验或证据。"},{"era":"ECONOMIC STOCK","en":"Economics fixed wealth as a stock of assets held at a point in time, in contrast with income as a flow.","cn":"经济学把财富固定为某一时点的资产存量，与作为流量的收入相对。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation of the material sense): the transition from wellbeing to money is gradual and no single first use is recorded.","cn":"首见年代不确定（物质义的）：从安好到金钱的转变是渐进的，没有单一的最早用例。"}]},"similar":{"note":{"en":"Group one separates near neighbours that are often mistaken for relatives; group two holds words for large possessions.","cn":"第一组区分常被误认作同族的近邻词；第二组是表示大量财物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"health","ipa":"/helθ/","tag":"different root","definition":"Health comes from Old English hælþ 'wholeness' and is related to whole, not to wela; the shared ending is deceptive.","definitionCN":"健康来自古英语 hælþ「完整」，与「完整」一词同源，与财富的词根无关；相同的词尾容易误导。"},{"word":"welfare","ipa":"/ˈwelfeə/","tag":"well + fare, different compound","definition":"Welfare joins 'well' with 'fare' meaning journey or condition; it is a separate compound, not a derivative of wealth.","definitionCN":"福利由「好」与「行程、处境」合成，是另一个复合词，并非财富的派生词。"},{"word":"commonwealth","ipa":"/ˈkɒmənwelθ/","tag":"shares the wealth root","definition":"Commonwealth is common plus wealth, naming a political community that shares a common good; it is a relative but not a synonym.","definitionCN":"联邦由「共同」加「财富」构成，指共享公共之善的政治共同体；它是同族词，却不是同义词。"},{"word":"weal","ipa":"/wiːl/","tag":"the older root word","definition":"Weal is the older noun for wellbeing from which wealth was built, and it survives mainly in set phrases.","definitionCN":"weal 是构成财富的较古名词，意为安好，主要保留在固定说法里。"}]},{"heading":"NEAR MEANING","entries":[{"word":"riches","ipa":"/ˈrɪtʃɪz/","tag":"abundant possessions","definition":"Riches is a plural noun for abundant valuable possessions, often used figuratively for richness of experience.","definitionCN":"riches 是表示大量贵重财物的复数名词，也常比喻经验的丰富。"},{"word":"fortune","ipa":"/ˈfɔːtʃuːn/","tag":"a large private fortune","definition":"Fortune is a very large amount of money owned by one person or family, close to the personal sense of wealth.","definitionCN":"fortune 指个人或家庭拥有的大笔钱财，接近财富的个人义。"},{"word":"assets","ipa":"/ˈæsets/","tag":"balance-sheet term","definition":"Assets are the items of value on a balance sheet, the accounting parts from which net wealth is calculated.","definitionCN":"资产是资产负债表上有价值的项目，是计算净财富的会计组成部分。"},{"word":"affluence","ipa":"/əˈfluːəns/","tag":"abundant flow of goods","definition":"Affluence stresses a high level of consumption and goods rather than the stock of assets itself.","definitionCN":"富裕强调高水平的消费与商品，而不是资产存量本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real native root, real compounds and real accounting phrases.","cn":"正常联想：真实的本族词根、真实的复合词与真实的会计说法。"},"normal":[{"en":"The root meant wellbeing before it meant money, so the older sense still echoes in formal language.","cn":"词根先指安好，后指钱财，因此较古的义项仍在正式语体中回响。"},{"en":"The abstract ending turns an adjective of goodness into the state of being well-off.","cn":"抽象后缀把表示「好」的形容词变成「富足的状态」。"},{"en":"A wealth of detail and a wealth of money share the same shape: a large supply.","cn":"大量细节与大量金钱形状相同：都是一种充裕的供应。"},{"en":"Economics keeps wealth as a stock and income as a flow, and the two should not be swapped.","cn":"经济学把财富当存量、收入当流量，两者不能互换。"},{"en":"The older public-good sense survives in the compound for a political community.","cn":"较古的公共之善义保留在指政治共同体的复合词里。"}],"abstract":[{"en":"Picture a storehouse where gold, grain and books sit on the same shelf.","cn":"想象一间库房，金条、粮食与书摆在同一层架上。"},{"en":"Picture a river that keeps flowing while a reservoir holds its water still.","cn":"想象一条河不断流动，而水库把水静静存住。"},{"en":"Picture a society whose common good is written on a shared ledger.","cn":"想象一个社会，把公共之善记在一本共同的账上。"}]},"examples":[{"en":"The country's wealth is concentrated in a few coastal cities.","cn":"这个国家的财富集中在少数沿海城市。"},{"en":"She brought a wealth of experience to the negotiation.","cn":"她为谈判带来了丰富的经验。"},{"en":"Wealth can grow while wages stay flat, which widens the gap between owners and workers.","cn":"财富可以在工资停滞时增长，从而扩大所有者与劳动者之间的差距。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「围」加「思」——把金条、地契与粮食围起来反复思量，就是财富；联想「围起来的家底」","word":"wealth"},"root":"古英语 wela「安好、兴旺、财富」加抽象后缀构成，属日耳曼语本族词，没有拉丁语来源；其较古义为良好处境，后收窄为钱财与资产，并保留「大量、丰富」的引申义。","sensesIntro":{"en":"Eight senses follow one store of value: money and assets are added into a net stock, extended to land, to prosperity, to any abundance, to a society's total and finally to the common good.","cn":"八个义项沿同一份价值储存展开：钱财与资产先被加成净值，再扩展到土地、兴旺、任何充裕、社会总量，最后到公共之善。"},"semanticMap":{"core":{"en":"CORE IMAGE: a storehouse holding gold, deeds, grain and books on the same shelves.","cn":"核心意象：一间库房，金条、地契、粮袋与书都摆在同一层架上。"},"chain":["HOLD MUCH","ADD UP ASSETS","LAND AND RESOURCES","GOOD CONDITION","LARGE SUPPLY","COMMON GOOD"],"branches":[{"senses":"01 · 02","en":"THE STORE: possessions are first counted, then reduced to a net stock.","cn":"储存：财物先被清点，再折算成净存量。"},{"senses":"03","en":"THE LAND: value also lies in rivers, forests and minerals.","cn":"土地：价值也藏在河流、森林与矿藏里。"},{"senses":"04","en":"THE GOOD STATE: the oldest sense is flourishing life, not coin.","cn":"良好状态：最古老的义项是兴旺的生活，而不是钱币。"},{"senses":"05 · 06","en":"ABUNDANCE AND AGGREGATE: any large supply, and the whole society's total, share the same shape.","cn":"充裕与总量：任何大量供应与整个社会的总量，形状相同。"},{"senses":"07 · 08","en":"TIME AND THE COMMON: what is handed down, and what is held in common.","cn":"时间与公共：一边是传下的存量，一边是共同持有的福祉。"}]},"affixes":{"intro":{"en":"Wealth and its relatives are native English; no Latin source is involved, so the family is read from Old English alone.","cn":"财富及其同族词是英语本族词，不涉及拉丁语来源，因此这个词族只能从古英语读起。"},"latinIntro":{"en":"There are no Latin entries for this word: the root is Germanic and the suffixes are native or French-influenced.","cn":"这个词没有拉丁语条目：词根是日耳曼语，后缀为本族或受法语影响的形式。"},"items":[{"word":"wealth","structure":"Old English wela + -th (abstract noun suffix)","meaning":"the state of being well-off","meaningCN":"财富；富足","example":"Wealth accumulated over three generations.","exampleCN":"财富经三代积累而成。"},{"word":"wealthy","structure":"wealth + -y (adjective suffix)","meaning":"having much wealth","meaningCN":"富有的","example":"The wealthy district built its own school.","exampleCN":"这个富裕城区自建了一所学校。"},{"word":"wealthier","structure":"wealthy + -er (comparative suffix)","meaning":"more wealthy","meaningCN":"更富有的","example":"The coast grew wealthier than the interior.","exampleCN":"沿海比内陆更富有。"},{"word":"wealthiest","structure":"wealthy + -est (superlative suffix)","meaning":"most wealthy","meaningCN":"最富有的","example":"The wealthiest families owned most of the land.","exampleCN":"最富有的家族拥有大部分土地。"},{"word":"wealthiness","structure":"wealthy + -ness (noun suffix)","meaning":"the quality of being wealthy","meaningCN":"富有的状态","example":"Wealthiness brought political influence.","exampleCN":"富有带来了政治影响。"},{"word":"weal","structure":"Old English wela (noun)","meaning":"wellbeing, prosperity","meaningCN":"福祉；兴旺","example":"Old texts wished the town weal.","exampleCN":"古籍祝愿市镇兴旺。"},{"word":"commonweal","structure":"common + weal (compound noun)","meaning":"the common good","meaningCN":"公共福祉","example":"The commonweal was invoked in the debate.","exampleCN":"辩论中援引了公共福祉。"},{"word":"well","structure":"Old English wel (adverb)","meaning":"in a good way","meaningCN":"好地","example":"The scheme worked well for small farms.","exampleCN":"这项计划对小农场很有效。"}],"latinEntries":[],"derivatives":[{"word":"wealthy","pos":"adj.","zh":"富有的"},{"word":"wealthier","pos":"adj.","zh":"更富有的"},{"word":"wealthiest","pos":"adj.","zh":"最富有的"},{"word":"wealthiness","pos":"n.","zh":"富有"},{"word":"commonweal","pos":"n.","zh":"公共福祉"},{"word":"weal","pos":"n.","zh":"福祉；福利（古义）"}]}},{"word":"wealthy","ipa_uk":"/ˈwelθi/","ipa_us":"/ˈwelθi/","definition_zh":"富有的；有钱的；也指资源丰富的、充裕的","definition_en":"having a lot of money, property or other valuable assets; rich","core_image":"一座大房子有宽敞的客厅与满仓的粮食，主人不必为下一季的开销发愁","scene":"街区里最老的那栋房子换上了新屋顶，主人又买下两间店铺。The wealthy couple funded a new clinic for the village.","sceneCN":"此处指「拥有大量钱财与资产」（第 1 个义项：个人或家庭富有）；句意为这对富有的夫妇为村里建了一所新诊所。图中可辨识物件：新屋顶、店铺门面、满仓的粮袋、诊所招牌。","pos":[{"tag":"adj.","zh":"富有的；有钱的"},{"tag":"adj.","zh":"资源丰富的；充裕的"},{"tag":"n.","zh":"（与定冠词连用）富人群体"}],"collocations":[{"phrase":"a wealthy family","zh":"富裕家庭"},{"phrase":"a wealthy nation","zh":"富裕国家"},{"phrase":"wealthy in resources","zh":"资源丰富"},{"phrase":"the wealthy elite","zh":"富裕精英"},{"phrase":"grow wealthy","zh":"变得富有"},{"phrase":"wealthy investors","zh":"富有的投资者"}],"forms":[{"label":"原级","form":"wealthy"},{"label":"比较级","form":"wealthier"},{"label":"最高级","form":"wealthiest"},{"label":"名词化（作复数集合名词）","form":"the wealthy"}],"derivatives":[{"word":"wealth","pos":"n.","zh":"财富"},{"word":"wealthier","pos":"adj.","zh":"更富有的"},{"word":"wealthiest","pos":"adj.","zh":"最富有的"},{"word":"wealthiness","pos":"n.","zh":"富有"},{"word":"the wealthy","pos":"n.","zh":"富人群体"},{"word":"well","pos":"adv.","zh":"好地"}],"senses":[{"no":"01","title":"Having much money and property","titleCN":"拥有大量钱财与房产","definition":"owning a large amount of money, property, investments or other valuable assets","definitionCN":"拥有大量金钱、房产、投资或其他贵重资产","example":"The wealthy couple funded a new clinic for the village.","exampleCN":"这对富有的夫妇为村里建了一所新诊所。","why":"The adjective simply applies the noun of wealth to a person, so its first sense is having a large store of value.","whyCN":"这个形容词只是把「财富」这一名词用于人，因此第一义就是拥有大量价值储备。"},{"no":"02","title":"Rich as an individual condition","titleCN":"个人处于富有的状况","definition":"being rich as a personal condition, with enough means to live comfortably without strain","definitionCN":"个人处于富有状态，拥有足以从容生活的财力","example":"Her family was wealthy enough to travel every summer.","exampleCN":"她家足够富有，每年夏天都能出行。","why":"Applied to a person, the word describes a condition of ease rather than a precise sum.","whyCN":"用于个人时，这个词描述的是从容的处境，而不是一个精确数额。"},{"no":"03","title":"Affluent countries or regions","titleCN":"富裕的国家或地区","definition":"having a high level of national income and widespread material comfort","definitionCN":"国民收入高、物质舒适普遍","example":"Wealthy nations pledged funds for the relief effort.","exampleCN":"富裕国家承诺为救援出资。","why":"The same adjective scales up from a household to a whole economy, where it means broadly prosperous.","whyCN":"同一个形容词能从家庭放大到整个经济，在那里意为普遍繁荣。"},{"no":"04","title":"Abundant in a resource","titleCN":"在某种资源上丰富","definition":"rich in a particular natural or cultural resource, such as oil, soil or traditions","definitionCN":"在石油、土壤或传统等某类自然或文化资源上丰富","example":"The province is wealthy in timber and clean water.","exampleCN":"该省木材与清洁水源丰富。","why":"The metaphor of having much extends from money to any resource, giving the phrase wealthy in.","whyCN":"「拥有很多」的比喻从金钱扩展到任何资源，于是有了「在某方面丰富」的说法。"},{"no":"05","title":"Prosperous and flourishing","titleCN":"繁荣兴旺","definition":"enjoying success and growth, especially of a place or institution","definitionCN":"地方或机构兴旺、成功、不断发展","example":"The port grew wealthy on shipping and insurance.","exampleCN":"这个港口靠航运与保险兴旺起来。","why":"An older sense of general wellbeing survives here: wealth meant a good condition before it meant money.","whyCN":"这里保留了较古的总体安好义：财富先指良好处境，后才指金钱。"},{"no":"06","title":"A polite word for well-off","titleCN":"「宽裕」的委婉说法","definition":"a tactful or indirect way of saying that someone has plenty of money","definitionCN":"委婉或间接地说某人有充裕的钱财","example":"The newsletter described the new residents as wealthy rather than rich.","exampleCN":"通讯把新居民称作「富有」而不是「有钱」。","why":"Because rich can sound blunt, speakers often choose the longer adjective as a gentler alternative.","whyCN":"由于「有钱」听起来直白，说话者常选这个较长的形容词作为更委婉的替代。"},{"no":"07","title":"Rich by inheritance or old money","titleCN":"因继承而富有、世代富有","definition":"possessing wealth that has been handed down rather than recently earned","definitionCN":"拥有的财富是传下来的，而非近期赚得的","example":"The wealthy families of the valley had owned the orchards for centuries.","exampleCN":"河谷的富裕家族拥有这些果园已数百年。","why":"Wealth can be inherited, so the adjective often implies an established stock rather than a new fortune.","whyCN":"财富可以继承，因此这个形容词常暗示既有的家底，而非新赚的钱。"},{"no":"08","title":"The wealthy as a social group","titleCN":"作为社会群体的富人","definition":"rich people considered as a class, used with the definite article","definitionCN":"作为一个阶层来看的富人，与定冠词连用","example":"The tax fell mainly on the wealthy.","exampleCN":"这项税主要落在富人身上。","why":"An adjective with the definite article can name a whole class, which is how the wealthy works as a plural noun.","whyCN":"形容词加定冠词可以指整个阶层，「富人」就是这样作复数名词用的。"}],"etymology":{"intro":{"en":"Wealthy is the native English noun of wealth turned into an adjective by a native suffix. There is no Latin source, and dates are approximate.","cn":"该词是英语本族名词「财富」加本族形容词后缀构成。没有拉丁语来源，年代均为约数。"},"items":[{"era":"OLD ENGLISH WELA","en":"The root wela meant 'wellbeing, prosperity, riches' and was related to the word for 'well'.","cn":"词根 wela 意为「安好、兴旺、财富」，与表示「好」的词同源。"},{"era":"MIDDLE ENGLISH WELTH","en":"The abstract noun welth named the state of being well-off before it narrowed to money and property.","cn":"抽象名词 welth 先指富足的状态，后来才收窄为金钱与财产。"},{"era":"ADJECTIVE SUFFIX","en":"A native adjective suffix meaning 'having the quality of' turned the noun into wealthy, 'having much wealth'.","cn":"一个表示「具有某种性质」的本族形容词后缀把名词变成「拥有大量财富的」。"},{"era":"CLASS NOUN","en":"With the definite article, the adjective came to name rich people as a group, a use fixed by the nineteenth century.","cn":"加定冠词后，这个形容词开始指富人群体，这一用法在十九世纪定型。"},{"era":"POLITE USE","en":"Modern style often prefers wealthy to rich in formal writing because it sounds less blunt.","cn":"现代正式写作常用它代替「有钱」，因为听起来不那么直白。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation of the adjective): the earliest recorded use is not precisely dated, and the suffix has many parallel forms.","cn":"首见年代不确定（形容词）：最早用例没有确切年代，同类后缀形式也很多。"}]},"similar":{"note":{"en":"Group one separates adjectives that look alike but have other roots; group two holds words for being rich.","cn":"第一组区分形近却另有词源的形容词；第二组是表示富有的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"healthy","ipa":"/ˈhelθi/","tag":"different root","definition":"Healthy comes from health, whose root means 'whole', not from wealth; the two adjectives differ by one letter in appearance only.","definitionCN":"healthy 来自 health，词根意为「完整」，与财富无关；两个形容词只是外观上差一个字母。"},{"word":"worthy","ipa":"/ˈwɜːði/","tag":"different root","definition":"Worthy means deserving respect and comes from worth, a different noun from wealth.","definitionCN":"worthy 意为值得尊敬的，来自 worth 这一不同的名词。"},{"word":"wealth","ipa":"/welθ/","tag":"the noun behind the adjective","definition":"Wealth is the noun; wealthy is the adjective describing one who has it.","definitionCN":"wealth 是名词；wealthy 是描述拥有它的形容词。"},{"word":"well-off","ipa":"/ˌwel ˈɒf/","tag":"plainer synonym","definition":"Well-off is a plainer, more conversational way to say wealthy, often suggesting comfort rather than great riches.","definitionCN":"well-off 是更朴素口语的说法，常指宽裕而非巨额财富。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rich","ipa":"/rɪtʃ/","tag":"the direct everyday word","definition":"Rich is the direct everyday adjective for having much money; wealthy is its more formal and slightly politer counterpart.","definitionCN":"rich 是表示有钱的直接日常形容词；wealthy 更正式也更委婉。"},{"word":"affluent","ipa":"/ˈæfluənt/","tag":"high consumption","definition":"Affluent stresses a high level of spending and goods rather than the size of the asset stock.","definitionCN":"affluent 强调高消费与大量商品，而非资产存量的大小。"},{"word":"prosperous","ipa":"/ˈprɒspərəs/","tag":"success and growth","definition":"Prosperous describes a place or person enjoying success and growth, which usually implies wealth but does not name it.","definitionCN":"prosperous 描述地方或个人兴旺发展，通常意味着富有，却不直接点明财富。"},{"word":"well-to-do","ipa":"/ˌwel tə ˈduː/","tag":"comfortable circumstances","definition":"Well-to-do means having enough money for a comfortable life without being extremely rich.","definitionCN":"well-to-do 指有足够钱财过舒适生活，但并不极富。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun behind the adjective, real comparisons and real class use.","cn":"正常联想：形容词背后的真实名词、真实的比较级与真实的阶层用法。"},"normal":[{"en":"The adjective is simply the noun of wealth plus a suffix meaning 'having'.","cn":"这个形容词就是「财富」名词加一个表示「具有」的后缀。"},{"en":"Comparison is regular: wealthier and wealthiest.","cn":"比较级与最高级规则：更富有、最富有。"},{"en":"With the definite article it names a whole class, the rich as a group.","cn":"加定冠词后它指整个阶层，即富人群体。"},{"en":"It also works with in for resources: wealthy in timber, wealthy in talent.","cn":"它也能与表示「在……方面」的介词连用：木材丰富、人才丰富。"},{"en":"It is the politer choice beside the blunt everyday word for rich.","cn":"与直白的日常「有钱」相比，它是更委婉的选择。"}],"abstract":[{"en":"Picture a house with a wide roof and a full granary, where no season feels threatening.","cn":"想象一座屋顶宽大、粮仓充盈的房子，任何季节都不显威胁。"},{"en":"Picture a person who never checks the price before putting something in the basket.","cn":"想象一个人往篮子里放东西前从不看价钱。"},{"en":"Picture a class of people whose names appear on the same old deeds.","cn":"想象一个阶层，名字都写在同一批旧地契上。"}]},"examples":[{"en":"The wealthy districts spend far more on schools than the poor ones.","cn":"富裕城区在学校上的花费远高于贫困城区。"},{"en":"A wealthy economy can still have many people living in poverty.","cn":"富裕的经济体仍可能有许多人生活在贫困中。"},{"en":"The country is wealthy in forests but poor in arable land.","cn":"这个国家森林丰富，宜耕地却很少。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「围」加「西」——把金条与地契围在屋里，日子就宽裕，于是富有","word":"wealthy"},"root":"由古英语 wela「安好、兴旺、财富」加抽象后缀构成名词，再加表示「具有」的形容词后缀；属日耳曼语本族词，没有拉丁语来源。","sensesIntro":{"en":"Eight senses follow one adjective: a person first has much, then lives at ease, then a whole country is affluent, then any resource is abundant, then a place thrives, then politeness softens the word, then inheritance marks it and finally a class is named.","cn":"八个义项沿同一个形容词展开：人先拥有很多，继而生活从容，再指国家富裕，又指资源丰富，再指地方兴旺，再作委婉语，再带上继承意味，最后指整个阶层。"},"semanticMap":{"core":{"en":"CORE IMAGE: a house with a wide roof, a full granary and no worry about the next season.","cn":"核心意象：屋顶宽大、粮仓充盈、不必担心下一季的房子。"},"chain":["HAVE MUCH","LIVE AT EASE","AFFLUENT COUNTRY","RICH IN A RESOURCE","THRIVING PLACE","A SOCIAL CLASS"],"branches":[{"senses":"01 · 02","en":"THE POSSESSION: much value held, and a life lived without strain.","cn":"拥有：掌握大量价值，生活没有紧绷感。"},{"senses":"03","en":"THE SCALE-UP: one household's ease becomes a nation's affluence.","cn":"放大：一户人家的从容变成一国的富裕。"},{"senses":"04","en":"THE RESOURCE: the same adjective describes timber, water or talent.","cn":"资源：同一个形容词也能形容木材、水源或人才。"},{"senses":"05 · 07","en":"TIME: a place thrives, and a family's riches may be inherited.","cn":"时间：地方会兴旺，家族的钱财也可能继承而来。"},{"senses":"06 · 08","en":"SOCIAL POLITENESS: a gentler word for rich, and a name for the class itself.","cn":"社会委婉：既是「有钱」的温和说法，也是阶层本身的名称。"}]},"affixes":{"intro":{"en":"The adjective belongs entirely to native English; no Latin source is involved, and its relatives are built with ordinary suffixes.","cn":"这个形容词完全属于英语本族词，不涉及拉丁语来源，其同族词由普通后缀构成。"},"latinIntro":{"en":"There are no Latin entries: the root and the suffixes are Germanic or native English.","cn":"没有拉丁语条目：词根与后缀均为日耳曼语或英语本族形式。"},"items":[{"word":"wealthy","structure":"wealth + -y (adjective suffix 'having')","meaning":"having much wealth","meaningCN":"富有的","example":"Wealthy families own most of the land.","exampleCN":"富裕家庭拥有大部分土地。"},{"word":"wealth","structure":"Old English wela + -th (abstract noun suffix)","meaning":"the state of being well-off","meaningCN":"财富","example":"Wealth grew slowly over the century.","exampleCN":"财富在这个世纪里缓慢增长。"},{"word":"wealthier","structure":"wealthy + -er (comparative suffix)","meaning":"more wealthy","meaningCN":"更富有的","example":"The city grew wealthier after the port opened.","exampleCN":"港口开放后这座城市更富有了。"},{"word":"wealthiest","structure":"wealthy + -est (superlative suffix)","meaning":"most wealthy","meaningCN":"最富有的","example":"The wealthiest households pay the top rate.","exampleCN":"最富有的家庭缴纳最高税率。"},{"word":"wealthiness","structure":"wealthy + -ness (noun suffix)","meaning":"the quality of being rich","meaningCN":"富有的状态","example":"Wealthiness did not bring happiness.","exampleCN":"富有并未带来幸福。"},{"word":"well-off","structure":"well + off (compound adjective)","meaning":"comfortably provided for","meaningCN":"宽裕的","example":"The well-off suburbs have good clinics.","exampleCN":"宽裕的郊区有好诊所。"},{"word":"wealthy in","structure":"wealthy + in (prepositional pattern)","meaning":"rich in a resource","meaningCN":"在……方面丰富","example":"The island is wealthy in fish.","exampleCN":"这座岛鱼类丰富。"},{"word":"the wealthy","structure":"the + wealthy (class noun)","meaning":"rich people as a group","meaningCN":"富人群体","example":"The tax fell mainly on the wealthy.","exampleCN":"这项税主要落在富人身上。"}],"latinEntries":[],"derivatives":[{"word":"wealth","pos":"n.","zh":"财富"},{"word":"wealthier","pos":"adj.","zh":"更富有的"},{"word":"wealthiest","pos":"adj.","zh":"最富有的"},{"word":"wealthiness","pos":"n.","zh":"富有"},{"word":"the wealthy","pos":"n.","zh":"富人群体"}]}},{"word":"financial","ipa_uk":"/fɪˈnænʃəl/","ipa_us":"/fəˈnænʃəl/","definition_zh":"财政的；金融的；财务的；与金钱和资金管理有关的","definition_en":"relating to money, banking, investments or the management of funds","core_image":"一张桌子上摊着账本、股票凭证与银行贷款单，所有纸页都指向同一件事：钱怎么来、怎么去","scene":"公司会计把去年的账目、贷款合同与投资记录整理成一册。The board delayed the project until the financial review was complete.","sceneCN":"此处指「与金钱和资金管理有关」（第 1 个义项：涉及钱款与资金安排）；句意为董事会把项目推迟到财务审查完成之后。图中可辨识物件：账本、股票凭证、贷款合同、计算器。","pos":[{"tag":"adj.","zh":"财政的；金融的；财务的"},{"tag":"adj.","zh":"（作定语）经济上的；金钱上的"}],"collocations":[{"phrase":"financial support","zh":"资金支持"},{"phrase":"financial year","zh":"财政年度"},{"phrase":"financial market","zh":"金融市场"},{"phrase":"financial crisis","zh":"金融危机"},{"phrase":"financial statements","zh":"财务报表"},{"phrase":"financial aid","zh":"经济援助；助学金"},{"phrase":"financial management","zh":"财务管理"}],"forms":[{"label":"原级","form":"financial"},{"label":"比较级（分析式）","form":"more financial"},{"label":"最高级（分析式）","form":"most financial"},{"label":"副词形式","form":"financially"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"}],"senses":[{"no":"01","title":"Relating to money matters","titleCN":"与金钱事务有关","definition":"connected with money, especially money used, earned or lent","definitionCN":"与金钱有关，尤指使用、赚取或借出的钱","example":"The board delayed the project until the financial review was complete.","exampleCN":"董事会把项目推迟到财务审查完成之后。","why":"The adjective names the whole domain of money, so its broadest sense simply marks anything connected with it.","whyCN":"这个形容词命名整个金钱领域，因此最宽的义项就是标示任何与钱有关的东西。"},{"no":"02","title":"Corporate accounts and statements","titleCN":"公司账目与报表","definition":"relating to a company's accounts, bookkeeping and reporting of results","definitionCN":"与公司的账目、记账与业绩报告有关","example":"Auditors examined the financial statements before the annual meeting.","exampleCN":"审计人员在年会前检查了财务报表。","why":"Within a company the money question becomes a matter of accounts, so the adjective attaches to statements and records.","whyCN":"在公司内部，钱的问题变成账目问题，因此这个形容词常与报表和记录连用。"},{"no":"03","title":"Banking and investment markets","titleCN":"银行与投资市场","definition":"relating to banks, securities, funds and the institutions that move capital","definitionCN":"与银行、证券、基金及调动资本的机构有关","example":"The financial market reacted sharply to the rate decision.","exampleCN":"金融市场对利率决定反应剧烈。","why":"Where money is traded and lent at scale, the word shifts from personal accounts to the market itself.","whyCN":"在钱被大规模借贷与交易的地方，这个词从个人账目转向市场本身。"},{"no":"04","title":"Government fiscal matters","titleCN":"政府财政事务","definition":"relating to public revenue, taxation and government spending","definitionCN":"与公共收入、税收与政府支出有关","example":"The ministry published its financial plan for the coming year.","exampleCN":"该部公布了下一年的财政计划。","why":"Public money is managed on the same logic as private money, so the adjective also covers state budgets and taxes.","whyCN":"公共钱财按与私人钱财相同的逻辑管理，因此这个形容词也涵盖国家预算与税收。"},{"no":"05","title":"Monetary resources for a purpose","titleCN":"用于特定目的的资金","definition":"describing the money needed or provided for a particular activity","definitionCN":"描述某项活动所需或所提供的钱","example":"The lab lacked the financial resources to buy new equipment.","exampleCN":"实验室缺乏购买新设备所需的资金。","why":"A project's needs are counted in money, so the adjective marks the resources that must be found.","whyCN":"项目的需要以钱计算，因此这个形容词标示必须筹到的资源。"},{"no":"06","title":"A person's economic situation","titleCN":"个人的经济状况","definition":"relating to someone's income, debts and overall ability to pay","definitionCN":"与某人的收入、债务与整体支付能力有关","example":"The family's financial position improved after the second wage earner returned to work.","exampleCN":"第二个人重新工作后，这家的经济状况改善了。","why":"For a household the same word describes solvency: what comes in, what is owed and what can be afforded.","whyCN":"对家庭而言，同一个词描述偿付能力：进多少、欠多少、能负担什么。"},{"no":"07","title":"Monetary cost","titleCN":"金钱上的费用","definition":"measured in money rather than in time, effort or other costs","definitionCN":"以金钱而非时间、精力或其他代价来衡量","example":"The delay had a serious financial cost for the contractor.","exampleCN":"延误给承包商带来了严重的金钱损失。","why":"Costs can be counted in several currencies, and the adjective picks out the one measured in money.","whyCN":"代价可以用多种尺度计算，这个形容词挑出以钱计的那一种。"},{"no":"08","title":"The financial sector as a whole","titleCN":"整个金融界","definition":"belonging to the industry of banking, insurance and investment","definitionCN":"属于银行、保险与投资这一行业","example":"Financial firms moved their offices to the new district.","exampleCN":"金融公司把办公室搬到了新区。","why":"Once enough institutions share the same money business, the adjective becomes the label of an industry.","whyCN":"当足够多的机构从事同一门金钱生意，这个形容词就成了一个行业的标签。"}],"etymology":{"intro":{"en":"Financial is built on finance, which came through French from Latin finis 'end', originally in the sense of settling a debt. Dates are approximate.","cn":"这个词由「财政」加形容词后缀构成，而「财政」经法语来自拉丁语 finis「终点」，原指了结债务。年代均为约数。"},"items":[{"era":"LATIN FINIS","en":"Finis meant 'end, boundary, limit'. Settling a matter meant bringing it to an end, and settling a debt followed the same image.","cn":"finis 意为「终点、边界、界限」。了结一件事就是把它带到终点，了结债务沿用同一意象。"},{"era":"OLD FRENCH FINER","en":"Old French finer meant 'to end, to settle', and its noun finance named the settling of a debt or payment.","cn":"古法语 finer 意为「结束、了结」，其名词 finance 指债务或款项的了结。"},{"era":"ENGLISH FINANCE","en":"English borrowed finance for money matters and the management of revenue, first in royal and state contexts.","cn":"英语借入该词指金钱事务与岁入管理，最早用于王室与国家语境。"},{"era":"FINANCIAL","en":"The adjective appeared later, formed with a Latin-derived adjective suffix, to mean 'of money matters'.","cn":"形容词出现较晚，由拉丁来源的形容词后缀构成，意为「金钱事务的」。"},{"era":"MODERN BROADENING","en":"In the nineteenth and twentieth centuries the adjective spread from state budgets to companies, markets and personal affairs.","cn":"到十九与二十世纪，这个形容词从国家预算扩展到公司、市场与个人事务。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation of the adjective): the exact earliest use is unrecorded, and the noun has changed meaning several times.","cn":"首见年代不确定（形容词）：确切最早用例未被记录，这一名词也数次改变含义。"}]},"similar":{"note":{"en":"Group one separates words from the same money family that are used differently; group two holds adjectives about money.","cn":"第一组区分同属金钱词族却用法不同的词；第二组是其他表示金钱的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"finance","ipa":"/ˈfaɪnæns/","tag":"the noun and verb","definition":"Finance is the noun for the field and the verb for providing money; financial is only the adjective.","definitionCN":"finance 是领域名词，也作「提供资金」的动词；financial 只是形容词。"},{"word":"financially","ipa":"/fɪˈnænʃəli/","tag":"the adverb","definition":"Financially is the adverb, describing how something is done in money terms.","definitionCN":"financially 是副词，描述某事在金钱层面如何完成。"},{"word":"fiscal","ipa":"/ˈfɪskəl/","tag":"different root, public money","definition":"Fiscal comes from Latin fiscus 'money basket' and refers especially to government revenue, not to money in general.","definitionCN":"fiscal 来自拉丁 fiscus「钱篮」，尤其指政府岁入，而非泛指金钱。"},{"word":"monetary","ipa":"/ˈmʌnɪtəri/","tag":"different root, money supply","definition":"Monetary comes from Latin moneta 'mint' and refers to money as a medium and system, especially the money supply.","definitionCN":"monetary 来自拉丁 moneta「铸币厂」，指作为媒介与制度的货币，尤指货币供应。"}]},{"heading":"NEAR MEANING","entries":[{"word":"economic","ipa":"/ˌiːkəˈnɒmɪk/","tag":"the whole economy","definition":"Economic concerns production, trade and the economy as a whole, while financial concerns money and funds specifically.","definitionCN":"economic 关注生产、贸易与整体经济，financial 则具体关注金钱与资金。"},{"word":"budgetary","ipa":"/ˈbʌdʒɪtəri/","tag":"relating to a budget","definition":"Budgetary means relating to a planned budget, a narrower slice of financial matters.","definitionCN":"budgetary 意为与预算计划有关，是财务事务中更窄的一块。"},{"word":"commercial","ipa":"/kəˈmɜːʃəl/","tag":"trade and profit","definition":"Commercial concerns buying and selling for profit, which may involve finance but is not limited to it.","definitionCN":"commercial 关注以获利为目的的买卖，可能涉及资金但不限于此。"},{"word":"pecuniary","ipa":"/pɪˈkjuːniəri/","tag":"money in a narrow legal sense","definition":"Pecuniary is a formal word for money-related matters, especially penalties and interests measured in cash.","definitionCN":"pecuniary 是正式用语，指与金钱有关的事，尤指以现金衡量的罚金与利益。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real noun family and the real fixed phrases.","cn":"正常联想：真实的拉丁词根、真实的名词词族与真实的固定搭配。"},"normal":[{"en":"The Latin root meant end, and settling a debt is bringing it to an end.","cn":"拉丁词根意为终点，了结债务就是把它带到终点。"},{"en":"The noun names the field or the act of funding; the adjective only describes.","cn":"名词指领域或出资行为；形容词只作描述。"},{"en":"Fixed phrases mark company use: financial statements, financial year, financial review.","cn":"固定搭配标出公司用法：财务报表、财政年度、财务审查。"},{"en":"Fixed phrases mark market use: financial market, financial crisis, financial sector.","cn":"固定搭配标出市场用法：金融市场、金融危机、金融部门。"},{"en":"It is narrower than economic and broader than budgetary.","cn":"它比「经济的」窄，比「预算的」宽。"}],"abstract":[{"en":"Picture a desk where every paper is a claim on money, none of it about goods themselves.","cn":"想象一张桌子，每张纸都是对钱的主张，没有一张直接关于货物。"},{"en":"Picture a river of capital with banks as locks and markets as channels.","cn":"想象一条资本之河，银行是闸门，市场是河渠。"},{"en":"Picture a household ledger and a national budget written in the same handwriting.","cn":"想象家庭账本与国家预算用同一种笔迹写成。"}]},"examples":[{"en":"The company published its financial results after the market closed.","cn":"公司在市场收盘后公布了财务业绩。"},{"en":"Students may apply for financial aid before the end of the term.","cn":"学生可在学期结束前申请经济援助。"},{"en":"The crisis began in the financial sector and spread to the wider economy.","cn":"危机始于金融部门，随后扩散到整个经济。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「费」加「难说」——一笔钱怎么花、怎么还，往往最难说清，于是凡与钱款安排有关的都称财务的","word":"financial"},"root":"经古法语来自拉丁 finis「终点、界限」，原指了结债务；名词进入英语后指金钱事务与岁入管理，再加形容词后缀构成财务的、金融的。词根与「结束、了结」相关，「精细」义的同形词也同出这一词根，只是语义分叉不同。","sensesIntro":{"en":"Eight senses follow one domain of money: the general field narrows to company accounts, then to markets, to public budgets, to project resources, to personal solvency, to monetary cost and finally to an industry.","cn":"八个义项沿同一个金钱领域展开：从一般领域收窄到公司账目，再到市场、公共预算、项目资金、个人偿付、金钱代价，最后到一个行业。"},"semanticMap":{"core":{"en":"CORE IMAGE: a desk covered with ledgers, share certificates and loan contracts, every page about money.","cn":"核心意象：一张桌子铺满账本、股票凭证与贷款合同，每一页都关于钱。"},"chain":["MONEY IN GENERAL","ACCOUNTS","MARKETS","PUBLIC BUDGET","PROJECT FUNDS","MONETARY COST"],"branches":[{"senses":"01","en":"THE FIELD: anything touching money falls under the adjective at its widest.","cn":"领域：只要触及金钱，就落在最宽意义上的这个形容词下。"},{"senses":"02","en":"THE BOOKS: inside a firm the money question becomes accounts and statements.","cn":"账册：在公司内部，金钱问题变成账目与报表。"},{"senses":"03 · 08","en":"THE MARKET AND THE INDUSTRY: trading money at scale creates a sector of its own.","cn":"市场与行业：大规模金钱交易自成一个部门。"},{"senses":"04 · 05","en":"PUBLIC AND PROJECT MONEY: budgets and grants are money assigned to a purpose.","cn":"公共与项目资金：预算与拨款都是被指定用途的钱。"},{"senses":"06 · 07","en":"PERSONAL SOLVENCY AND COST: what a household can bear, and what a delay is worth in cash.","cn":"个人偿付与代价：一个家庭能承受什么，以及延误折成多少钱。"}]},"affixes":{"intro":{"en":"Financial belongs to the Latin family of finis 'end', which also gives finish, final and fine; the money sense grew from settling a debt.","cn":"这个词属于拉丁 finis「终点」的词族，该词族还衍生出完成、最终与罚金等词；金钱义从了结债务生长出来。"},"latinIntro":{"en":"Finis and finire supply the root; the English noun and adjective were built on top of them through French.","cn":"finis 与 finire 提供词根，英语名词与形容词经法语在其上构成。"},"items":[{"word":"finance","structure":"Old French finance (settlement of a debt)","meaning":"the management of money","meaningCN":"财政；金融","example":"Finance became a separate department.","exampleCN":"财务成了一个独立部门。"},{"word":"financial","structure":"finance + -ial (adjective suffix)","meaning":"relating to money","meaningCN":"财务的；金融的","example":"Financial records must be kept for seven years.","exampleCN":"财务记录须保存七年。"},{"word":"financially","structure":"financial + -ly (adverb suffix)","meaning":"in money terms","meaningCN":"在财务上","example":"The branch is financially independent.","exampleCN":"这个分支机构财务独立。"},{"word":"financier","structure":"finance + -ier (person suffix)","meaning":"one who deals in large sums","meaningCN":"金融家","example":"A financier arranged the loan.","exampleCN":"一位金融家安排了这笔贷款。"},{"word":"financing","structure":"finance + -ing (noun suffix)","meaning":"the act of providing funds","meaningCN":"融资","example":"The financing came from two banks.","exampleCN":"融资来自两家银行。"},{"word":"refinance","structure":"re- (prefix 'again') + finance","meaning":"to fund again","meaningCN":"重新融资","example":"The firm refinanced its debt.","exampleCN":"公司重组了债务。"},{"word":"final","structure":"finis (Latin noun 'end') + -al (adjective suffix)","meaning":"coming at the end","meaningCN":"最终的","example":"The final payment is due in June.","exampleCN":"最后一笔款六月到期。"},{"word":"finish","structure":"Old French finir (to end)","meaning":"to bring to an end","meaningCN":"完成；结束","example":"They finished the audit early.","exampleCN":"他们提前完成了审计。"},{"word":"fine","structure":"finis (Latin noun 'end') through French","meaning":"a penalty that ends a case","meaningCN":"罚款","example":"The court imposed a fine.","exampleCN":"法院判了罚款。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (m./f., third declension)","meaning":"end, boundary, limit","meaningCN":"终点；边界；界限"},{"word":"finire","structure":"finire, finivi, finitum (verb, fourth conjugation)","meaning":"to end, to bound","meaningCN":"结束；限定"},{"word":"fiscalis","structure":"fiscalis, fiscale (adj., third declension)","meaning":"of the treasury","meaningCN":"国库的；财政的"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"}]}},{"word":"financially","ipa_uk":"/fɪˈnænʃəli/","ipa_us":"/fəˈnænʃəli/","definition_zh":"在财务上；在经济上；从金钱角度","definition_en":"in relation to money or finances; from a financial point of view","core_image":"一个人在账本上把收入与支出两栏对齐，数字决定他能做什么、不能做什么","scene":"她算完房租、学费与药费，发现这个月已经撑不住。The family was financially unable to repair the roof after the storm.","sceneCN":"此处指「在金钱与财务状况方面」（第 1 个义项：就钱款而言）；句意为这家人经济上无力在风暴后修屋顶。图中可辨识物件：两栏对齐的账本、房租单、学费单、药费单。","pos":[{"tag":"adv.","zh":"在财务上；在经济上"},{"tag":"adv.","zh":"从金钱角度（作句子状语）"}],"collocations":[{"phrase":"financially independent","zh":"经济独立"},{"phrase":"financially viable","zh":"财务上可行"},{"phrase":"financially dependent","zh":"经济上依赖"},{"phrase":"financially secure","zh":"经济上有保障"},{"phrase":"financially supported","zh":"获得资金支持"},{"phrase":"financially speaking","zh":"从经济上说"}],"forms":[{"label":"原级","form":"financially"},{"label":"比较级（分析式）","form":"more financially"},{"label":"最高级（分析式）","form":"most financially"},{"label":"形容词形式","form":"financial"}],"derivatives":[{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"},{"word":"finances","pos":"n.","zh":"财务状况；财力"}],"senses":[{"no":"01","title":"In money terms","titleCN":"在金钱方面","definition":"in terms of money, especially income, cost or available funds","definitionCN":"就金钱而言，尤指收入、费用或可用资金","example":"The family was financially unable to repair the roof after the storm.","exampleCN":"这家人经济上无力在风暴后修屋顶。","why":"The adverb simply carries the adjective's money meaning into how an action is possible or impossible.","whyCN":"这个副词只是把形容词的「金钱」含义带入一个动作能否完成的条件里。"},{"no":"02","title":"From a financial standpoint","titleCN":"从财务角度看","definition":"when judged from the point of view of money rather than of time, law or sentiment","definitionCN":"从金钱而非时间、法律或情感的角度判断","example":"Financially, the merger made sense even though it hurt local pride.","exampleCN":"从财务角度看，这次合并是合理的，尽管它伤了地方自尊。","why":"A sentence adverb can frame the whole judgment, so the word often opens a sentence to mark the money angle.","whyCN":"句子状语能为整个判断定框，因此这个词常置于句首，标出金钱视角。"},{"no":"03","title":"With respect to personal solvency","titleCN":"就个人偿付能力而言","definition":"in relation to someone's ability to pay debts and cover regular costs","definitionCN":"与某人偿还债务、支付日常开支的能力有关","example":"She was financially sound before the hospital bills arrived.","exampleCN":"在医院账单到来之前，她的财务状况良好。","why":"For a person the money question is solvency, so the adverb often pairs with words for soundness or ruin.","whyCN":"对个人而言，钱的问题是偿付能力，因此这个副词常与表示稳健或破产的词连用。"},{"no":"04","title":"In a way that involves funds","titleCN":"以涉及资金的方式","definition":"by means of money or funding rather than by other forms of support","definitionCN":"通过金钱或资金而非其他形式的支持","example":"The project was financially backed by three foundations.","exampleCN":"这个项目由三家基金会提供资金支持。","why":"Support can be given in labour, advice or money, and the adverb picks out the money channel.","whyCN":"支持可以用劳力、建议或金钱给出，这个副词挑出的是金钱这一渠道。"},{"no":"05","title":"As regards company accounts","titleCN":"就公司账目而言","definition":"in relation to a company's books, results and reporting obligations","definitionCN":"与公司的账簿、业绩与报告义务有关","example":"The branch is financially separate from the parent company.","exampleCN":"这个分支机构在财务上与母公司分开。","why":"Within a firm the money view is the accounts view, so the adverb attaches to separation, reporting and results.","whyCN":"在公司内部，金钱视角就是账目视角，因此这个副词常与独立、报告与业绩搭配。"},{"no":"06","title":"Supported by money, especially dependence","titleCN":"在经济上受供养","definition":"in a condition of relying on another person's money for daily needs","definitionCN":"处于依靠他人钱财满足日常需要的状态","example":"The students remained financially dependent on their parents.","exampleCN":"这些学生在经济上仍依赖父母。","why":"When money comes from someone else, the adverb marks dependence rather than mere accounting.","whyCN":"当钱来自别人时，这个副词标示的是依赖，而不只是记账。"},{"no":"07","title":"In monetary compensation","titleCN":"以金钱报酬的方式","definition":"by paying money, as opposed to offering time, goods or favours","definitionCN":"通过支付金钱，而非提供时间、实物或人情","example":"Volunteers were not financially rewarded for their hours.","exampleCN":"志愿者投入的时间没有获得金钱报酬。","why":"Rewards can be material or monetary, and the adverb specifies the monetary kind.","whyCN":"回报可以是实物也可以是金钱，这个副词明确的是金钱那一种。"},{"no":"08","title":"As a sentence-level hedge","titleCN":"作句子层面的限定语","definition":"used at the start of a clause to limit a claim to the money dimension","definitionCN":"用于从句开头，把论断限定在金钱维度","example":"Financially speaking, the village gained more than it lost.","exampleCN":"从经济上说，这个村庄所得多于所失。","why":"Speakers need a way to say 'on this one dimension', and the adverb at the front of a clause does exactly that.","whyCN":"说话者需要一种方式来表示「只就这一维度而言」，置于句首的副词正好承担这一功能。"}],"etymology":{"intro":{"en":"Financially is the adverb of financial, built on finance, which came through French from Latin finis 'end'. Dates are approximate.","cn":"这个词是「财务的」的副词形式，而「财务的」建立在「财政」之上，后者经法语来自拉丁 finis「终点」。年代均为约数。"},"items":[{"era":"LATIN FINIS","en":"Finis meant 'end, boundary, limit', and settling a debt was pictured as bringing it to an end.","cn":"finis 意为「终点、边界、界限」，了结债务被想象成把它带到终点。"},{"era":"OLD FRENCH FINANCE","en":"Old French finance named the settling of a debt and the management of revenue.","cn":"古法语 finance 指债务的了结与岁入的管理。"},{"era":"ENGLISH ADJECTIVE","en":"English formed financial from finance to describe anything connected with money matters.","cn":"英语从「财政」构成形容词，用来描述与金钱事务有关的一切。"},{"era":"ADVERB SUFFIX","en":"The native adverb suffix -ly turned the adjective into financially, 'in a money way'.","cn":"本族副词后缀把形容词变成「在金钱方面地」。"},{"era":"MODERN USE","en":"In modern writing the adverb spreads from household budgets to companies, projects and whole economies.","cn":"在现代写作中，这个副词从家庭预算扩展到公司、项目与整个经济。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation of the adverb): the earliest recorded use is not precisely dated.","cn":"首见年代不确定（副词）：最早用例没有确切年代。"}]},"similar":{"note":{"en":"Group one separates the adjective, noun and adverb of the same family; group two holds other money-related adverbs and phrases.","cn":"第一组区分同一词族的形容词、名词与副词；第二组是其他与金钱有关的副词与说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"financial","ipa":"/fɪˈnænʃəl/","tag":"the adjective","definition":"Financial describes a noun; financially describes a verb, adjective or whole clause.","definitionCN":"financial 修饰名词；financially 修饰动词、形容词或整个从句。"},{"word":"finance","ipa":"/ˈfaɪnæns/","tag":"noun and verb","definition":"Finance names the field or the act of funding; it cannot stand where the adverb is needed.","definitionCN":"finance 指领域或出资行为，不能代替副词出现的位置。"},{"word":"financing","ipa":"/ˈfaɪnænsɪŋ/","tag":"the noun of funding","definition":"Financing is the activity or arrangement of funds, a noun rather than a manner adverb.","definitionCN":"financing 是融资活动或安排，是名词而非方式副词。"},{"word":"fiscally","ipa":"/ˈfɪskəli/","tag":"public money only","definition":"Fiscally means in terms of government revenue and taxation, a narrower public-money sense.","definitionCN":"fiscally 指就政府岁入与税收而言，是更窄的公共财政义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"economically","ipa":"/ˌiːkəˈnɒmɪkli/","tag":"the wider economy","definition":"Economically refers to the economy, production and efficiency, not only to money and funds.","definitionCN":"economically 指经济、生产与效率，不只是金钱与资金。"},{"word":"monetarily","ipa":"/ˈmʌnɪtərəli/","tag":"money as a system","definition":"Monetarily refers to money as a medium or to the money supply, a technical and narrower usage.","definitionCN":"monetarily 指作为媒介的货币或货币供应，是技术性更窄的用法。"},{"word":"in monetary terms","ipa":"/ɪn ˈmʌnɪtəri tɜːmz/","tag":"a phrase, not an adverb","definition":"In monetary terms is the phrase counterpart, often used where a single adverb would sound stiff.","definitionCN":"「以金钱计」是词组形式的对应说法，在单个副词显得生硬时常用。"},{"word":"at a cost","ipa":"/ət ə kɒst/","tag":"price, not perspective","definition":"At a cost states that something was paid for, while financially states the dimension being judged.","definitionCN":"「付出代价」说明某事花了钱，而 financially 说明判断所用的维度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffix, the real family and the real sentence position.","cn":"正常联想：真实的后缀、真实的词族与真实的句法位置。"},"normal":[{"en":"The adverb is the adjective plus the ordinary adverb suffix.","cn":"这个副词就是形容词加普通副词后缀。"},{"en":"It can sit at the front of a sentence to frame the whole claim as a money claim.","cn":"它可以放在句首，把整个论断框定为金钱论断。"},{"en":"It pairs naturally with sound, secure, dependent, viable and unable.","cn":"它自然与稳健、有保障、依赖、可行、无力等词搭配。"},{"en":"The adjective modifies nouns; the adverb modifies everything else.","cn":"形容词修饰名词，副词修饰其余成分。"},{"en":"Public-money adverbs are narrower and usually replace it only in official writing.","cn":"公共财政类副词更窄，通常只在官方写作中替换它。"}],"abstract":[{"en":"Picture a pair of glasses that shows only price tags and balances, hiding everything else.","cn":"想象一副眼镜只显示价签与余额，把其他都遮住。"},{"en":"Picture two columns, income and outgoings, deciding what the day will allow.","cn":"想象收入与支出两栏，决定这一天能做什么。"},{"en":"Picture a sentence with a small gate in front, marked money only.","cn":"想象一个句子前面立着一道小门，写着「只谈钱」。"}]},"examples":[{"en":"The service is financially sustainable because costs are shared.","cn":"这项服务在财务上可持续，因为成本由多方分担。"},{"en":"Financially, the family was better off after moving to the city.","cn":"从经济上说，这家人搬到城市后更宽裕了。"},{"en":"The scheme is financially supported by the regional government.","cn":"这项计划由地区政府提供资金支持。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「费」加「难说」再加「里」——钱怎么花最难说清，从这个角度去看，就是「在财务上」","word":"financially"},"root":"由「财政、金融」加形容词后缀构成「财务的」，再加本族副词后缀；其词根经古法语来自拉丁 finis「终点、界限」，原指了结债务，后指金钱事务的管理。","sensesIntro":{"en":"Eight uses follow one money lens: it first states what money allows, then frames a judgment, tests solvency, marks funding, separates company books, shows dependence, specifies monetary reward and finally limits a whole sentence.","cn":"八种用法沿同一枚金钱镜片展开：先说钱允许什么，再为判断定框，检验偿付能力，标示出资，区分公司账目，显示依赖，指明金钱报酬，最后限定整个句子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pair of glasses that shows only price tags and balances.","cn":"核心意象：一副只显示价签与余额的眼镜。"},"chain":["MONEY ALLOWS","MONEY VIEW","SOLVENCY","FUNDING","COMPANY BOOKS","MONEY ONLY"],"branches":[{"senses":"01","en":"THE ENABLING CONDITION: money decides whether an action is possible.","cn":"使能条件：钱决定一个动作是否可行。"},{"senses":"02","en":"THE FRAME: the adverb sets the money dimension for a whole judgment.","cn":"取景框：副词为整个判断设定金钱维度。"},{"senses":"03 · 06","en":"SOLVENCY AND DEPENDENCE: one's own ability to pay, or reliance on another's money.","cn":"偿付与依赖：自己付得起，或依靠别人的钱。"},{"senses":"04 · 07","en":"THE MONEY CHANNEL: support and reward arrive as funds rather than as goods or time.","cn":"金钱渠道：支持与回报以资金而非实物或时间的形式到来。"},{"senses":"05 · 08","en":"BOOKS AND CLAUSE: company accounts, and a sentence hedged to the money dimension.","cn":"账目与从句：公司账册，以及被限定在金钱维度的句子。"}]},"affixes":{"intro":{"en":"Financially is a regularly built adverb; its whole family comes from the Latin noun for an end or limit.","cn":"这个副词是规则构成的形式，其整个词族来自拉丁语中表示终点或界限的名词。"},"latinIntro":{"en":"Finis and finire supply the root; English added the noun, the adjective and the adverb in turn.","cn":"finis 与 finire 提供词根，英语依次加上名词、形容词与副词。"},"items":[{"word":"financial","structure":"finance + -ial (adjective suffix)","meaning":"relating to money","meaningCN":"财务的","example":"Financial records must be audited.","exampleCN":"财务记录必须审计。"},{"word":"financially","structure":"financial + -ly (adverb suffix)","meaning":"in money terms","meaningCN":"在财务上","example":"The branch is financially independent.","exampleCN":"这个分支机构财务独立。"},{"word":"finance","structure":"Old French finance (settlement of debt)","meaning":"management of money","meaningCN":"财政；金融","example":"Finance approved the budget.","exampleCN":"财务部门批准了预算。"},{"word":"finances","structure":"finance + -s (plural noun)","meaning":"the money situation of a person or body","meaningCN":"财力；财务状况","example":"The club's finances improved.","exampleCN":"俱乐部的财务状况改善了。"},{"word":"financing","structure":"finance + -ing (noun suffix)","meaning":"the act of providing funds","meaningCN":"融资","example":"Financing came from a single lender.","exampleCN":"融资来自一个出借方。"},{"word":"financier","structure":"finance + -ier (person suffix)","meaning":"one who handles large sums","meaningCN":"金融家","example":"A financier backed the scheme.","exampleCN":"一位金融家支持了这项计划。"},{"word":"refinance","structure":"re- (prefix 'again') + finance","meaning":"to fund again","meaningCN":"重新融资","example":"They refinanced the loan last year.","exampleCN":"他们去年重新融资了这笔贷款。"},{"word":"fine","structure":"finis (Latin noun 'end') through French","meaning":"a penalty that ends a case","meaningCN":"罚款","example":"The fine was paid at once.","exampleCN":"罚款当即缴清。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (m./f., third declension)","meaning":"end, boundary, limit","meaningCN":"终点；边界；界限"},{"word":"finire","structure":"finire, finivi, finitum (verb, fourth conjugation)","meaning":"to end, to bound","meaningCN":"结束；限定"}],"derivatives":[{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"}]}},{"word":"financier","ipa_uk":"/fɪˈnænsɪə/","ipa_us":"/ˌfɪnənˈsɪr/","definition_zh":"金融家；财政家；为大型项目或企业提供资金的人","definition_en":"a person who manages large sums of money, invests in enterprises or provides funding for projects","core_image":"一位穿深色外套的人坐在长桌一端，面前摊着多家公司的账目与融资方案","scene":"铁路公司靠少数几个出资人筹到建线所需的巨款。A financier arranged the loan that kept the railway company alive.","sceneCN":"此处指「为大型项目或企业提供资金的人」（第 3 个义项：为企业出资者）；句意为一位金融家安排了让铁路公司得以存续的贷款。图中可辨识物件：长桌、融资方案、铁路地图、贷款合同。","pos":[{"tag":"n.","zh":"金融家；财政家"},{"tag":"n.","zh":"为项目或企业提供资金的人"},{"tag":"v.","zh":"为……融资（罕用）"}],"collocations":[{"phrase":"a leading financier","zh":"知名金融家"},{"phrase":"an international financier","zh":"国际金融家"},{"phrase":"a railway financier","zh":"铁路金融家"},{"phrase":"financier and investor","zh":"金融家与投资者"},{"phrase":"a powerful financier","zh":"权势很大的金融家"},{"phrase":"a financier of the arts","zh":"艺术事业的资助者"}],"forms":[{"label":"单数","form":"financier"},{"label":"复数","form":"financiers"},{"label":"动词三单","form":"financiers"},{"label":"动词过去式","form":"financiered"},{"label":"动词过去分词","form":"financiered"},{"label":"动词现在分词","form":"financiering"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"},{"word":"financed","pos":"adj.","zh":"获得资金支持的"}],"senses":[{"no":"01","title":"A person who deals in large sums","titleCN":"从事大额资金业务的人","definition":"a person whose business is the handling and movement of large amounts of money","definitionCN":"以处理与调动大额资金为业的人","example":"The financier moved capital between three countries in a week.","exampleCN":"这位金融家一周内在三个国家之间调动资本。","why":"The agent suffix marks a person who does the action of finance, so the first sense is simply one who deals in money at scale.","whyCN":"表示施动者的后缀标示做「融资」这件事的人，因此第一义就是在很大规模上处理金钱的人。"},{"no":"02","title":"A banker or investment expert","titleCN":"银行家或投资专家","definition":"a senior banker or investment professional who advises on and arranges capital","definitionCN":"为资本安排与咨询的高级银行或投资专业人士","example":"The financier advised the board on how to raise the money.","exampleCN":"这位金融家就如何筹资向董事会提供建议。","why":"Banking is the institutional home of large money dealing, so the word often means a senior banker or investment specialist.","whyCN":"银行是大额金钱交易的主要机构，因此这个词常指高级银行家或投资专家。"},{"no":"03","title":"One who funds an enterprise","titleCN":"为企业出资的人","definition":"a person who provides the capital that lets a company or project operate","definitionCN":"提供让公司或项目得以运转的资本的人","example":"A financier arranged the loan that kept the railway company alive.","exampleCN":"一位金融家安排了让铁路公司得以存续的贷款。","why":"Capital has to come from somewhere, and the person who supplies it is named by this word in its funding sense.","whyCN":"资本必须有来源，提供资本的人就由这个词的出资义来命名。"},{"no":"04","title":"A backer of a specific project","titleCN":"特定项目的资助者","definition":"a supporter who puts money into a particular venture, expedition or institution","definitionCN":"为特定事业、探险或机构投入金钱的支持者","example":"The expedition found a financier willing to pay for the ships.","exampleCN":"探险队找到了一位愿意为船只出资的资助者。","why":"The word scales down from general finance to one venture when a single backer makes the project possible.","whyCN":"当单个支持者让项目成为可能时，这个词就从一般金融缩小到一项事业。"},{"no":"05","title":"A financial adviser","titleCN":"财政顾问","definition":"an expert who gives advice on money, credit and the structure of a deal","definitionCN":"就金钱、信贷与交易结构提供建议的专家","example":"The government hired a financier to restructure its debt.","exampleCN":"政府聘请一位财政专家重组债务。","why":"Advice about money is a service in its own right, so the person-word also covers the advisory role.","whyCN":"关于钱的建议本身是一种服务，因此这个指人的词也涵盖顾问角色。"},{"no":"06","title":"A state financier in historical use","titleCN":"历史用法中的国家财政管理者","definition":"a historical official who managed public revenue for a ruler or state","definitionCN":"历史上为君主或国家管理公共岁入的官员","example":"The old treasury was run by a financier answerable only to the king.","exampleCN":"旧时的国库由一位只对国王负责的财政官管理。","why":"Before modern corporations, the biggest money manager was the state, so the word once named a public treasury official.","whyCN":"在现代公司出现之前，最大的资金管理者是国家，因此这个词曾指公共财政官员。"},{"no":"07","title":"A speculator, often pejorative","titleCN":"常含贬义的投机者","definition":"a money dealer pictured as profiting from deals that do not create real goods, used as a criticism","definitionCN":"被描绘成从不创造实物的交易中获利的金钱经营者，带批评意味","example":"Critics called the buyers financiers who never built anything.","exampleCN":"批评者把这些买家称作从不建设任何东西的金融投机者。","why":"When money dealing is seen as detached from production, the word acquires a mocking tone.","whyCN":"当金钱交易被视为脱离生产时，这个词就带上嘲讽口吻。"},{"no":"08","title":"To act as a financier","titleCN":"动词：充当出资人","definition":"to arrange or provide the money for an enterprise, a rare verbal use","definitionCN":"为企业安排或提供资金，属罕用的动词用法","example":"A small group financed the whole venture.","exampleCN":"一个小团体为整个事业提供了资金。","why":"Nouns for roles often turn into verbs meaning 'to perform that role', and this word followed the same path.","whyCN":"表示角色的名词常转为「履行该角色」的动词，这个词也走了同一条路。"}],"etymology":{"intro":{"en":"Financier comes through French from the noun finance, with an agent suffix meaning a person who acts. The root is Latin finis 'end'. Dates are approximate.","cn":"该词经法语来自名词「财政」，加上表示施动者的后缀，即「做这件事的人」。词根为拉丁 finis「终点」。年代均为约数。"},"items":[{"era":"LATIN FINIS","en":"Finis meant 'end, boundary, limit'; settling a debt was seen as bringing it to an end.","cn":"finis 意为「终点、边界、界限」；了结债务被看作把它带到终点。"},{"era":"FRENCH FINANCE","en":"French finance named the settling of payments and the management of revenue, and it passed into English in the eighteenth century.","cn":"法语 finance 指款项的了结与岁入管理，于十八世纪进入英语。"},{"era":"AGENT SUFFIX","en":"A French agent suffix, from Latin -arius, was added to finance to name the person who handles it.","cn":"一个经法语来自拉丁的后缀被加到「财政」上，用来命名处理它的人。"},{"era":"NINETEENTH CENTURY","en":"The word spread with railway building and government borrowing, when large projects needed private backers.","cn":"随着铁路建设与政府借债，这个词流行起来，因为大型项目需要私人出资者。"},{"era":"PEJORATIVE TONE","en":"In political writing the word could suggest a dealer profiting without producing anything, and that critical shade survives.","cn":"在政治写作中，这个词可暗示不事生产却获利的经营者，这一批评色彩保留至今。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the earliest recorded use in English is not precisely dated, and French usage predates it.","cn":"首见年代不确定：英语中确切的最早用例没有年代，法语用法更早。"}]},"similar":{"note":{"en":"Group one separates the person-word from the activity and the adjective; group two holds other words for people who supply money.","cn":"第一组把指人的词与活动、形容词分开；第二组是其他表示出钱者的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"finance","ipa":"/ˈfaɪnæns/","tag":"the field, not the person","definition":"Finance is the field or the act of funding; financier is the person who does it.","definitionCN":"finance 是领域或出资行为；financier 是做这件事的人。"},{"word":"financing","ipa":"/ˈfaɪnænsɪŋ/","tag":"the activity","definition":"Financing is the activity of raising funds; it cannot name a person.","definitionCN":"financing 是筹资活动，不能用来指人。"},{"word":"financial","ipa":"/fɪˈnænʃəl/","tag":"the adjective","definition":"Financial describes money matters and never stands for a person.","definitionCN":"financial 描述金钱事务，从不指人。"},{"word":"financier","ipa":"/fɪˈnænsɪə/","tag":"person and rare verb","definition":"The same spelling serves as a rare verb meaning to fund an enterprise, so context decides the part of speech.","definitionCN":"同一拼写也可作罕用动词，意为为企业出资，因此要靠语境判断词性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"banker","ipa":"/ˈbæŋkə/","tag":"works inside a bank","definition":"A banker works within a banking institution, while a financier may operate across institutions and markets.","definitionCN":"banker 在银行机构内工作，financier 则可能跨机构与市场运作。"},{"word":"investor","ipa":"/ɪnˈvestə/","tag":"puts money into assets","definition":"An investor puts money into assets expecting a return, a narrower role than arranging finance.","definitionCN":"investor 把钱投入资产以期待回报，比安排融资的角色更窄。"},{"word":"backer","ipa":"/ˈbækə/","tag":"supports one venture","definition":"A backer funds a particular venture, often informally, while a financier usually works at a larger scale.","definitionCN":"backer 为特定事业出资，常较非正式；financier 通常规模更大。"},{"word":"magnate","ipa":"/ˈmæɡneɪt/","tag":"industrial wealth, not finance as such","definition":"A magnate is a powerful figure in an industry, whose wealth may be industrial rather than financial.","definitionCN":"magnate 是某一产业中的权势人物，其财富可能来自工业而非金融。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real agent suffix, the real family and the real historical shift.","cn":"正常联想：真实的施动后缀、真实的词族与真实的历史变化。"},"normal":[{"en":"The suffix marks the doer: finance plus agent ending equals the person who handles money.","cn":"后缀标示施动者：财政加施动词尾，就是处理金钱的人。"},{"en":"It is a person word, unlike the field noun and the activity noun beside it.","cn":"它是指人的词，与旁边的领域名词、活动名词不同。"},{"en":"Railways and government debt made the role prominent in the nineteenth century.","cn":"铁路与政府债务让这一角色在十九世纪显要起来。"},{"en":"It can sound critical when money dealing seems detached from production.","cn":"当金钱交易看似脱离生产时，它可能带批评意味。"},{"en":"It also works as a rare verb, so the same spelling can be a noun or an action.","cn":"它也可作罕用动词，因此同一拼写既可是名词也可是动作。"}],"abstract":[{"en":"Picture a person at the end of a long table with other people's plans spread out.","cn":"想象一个人坐在长桌一端，桌上摊着别人的计划。"},{"en":"Picture a hand moving a line of credit from one city to another overnight.","cn":"想象一只手一夜之间把一笔信贷从一个城市移到另一个城市。"},{"en":"Picture a railway map drawn on top of a loan contract.","cn":"想象一张铁路地图画在贷款合同上面。"}]},"examples":[{"en":"A financier bought the failing line and rebuilt it within a year.","cn":"一位金融家买下这条亏损的线路，一年内重建完成。"},{"en":"The financier was criticized for earning fees without taking any risk.","cn":"这位金融家因只收费用却不承担风险而受到批评。"},{"en":"She worked as a financier for museums, raising funds for new wings.","cn":"她为博物馆担任筹资人，为新展馆筹款。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「费」加「难说」再加「人」——专门替大项目把钱凑齐的人，就是金融家","word":"financier"},"root":"经法语来自名词「财政、金融」，原指债务的了结与岁入管理；加上表示施动者的后缀，指处理大额资金的人。词根为拉丁 finis「终点、界限」，与「结束、了结」相关。","sensesIntro":{"en":"Eight senses follow one person: a dealer in large sums becomes a senior banker, then a funder of enterprises, a backer of one venture, an adviser, a state official, a criticized speculator and finally a rare verb.","cn":"八个义项沿同一个人展开：大额资金经营者先成为高级银行家，再成为企业出资者、单项事业资助者、顾问、国家财政官、受批评的投机者，最后转为罕用动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a figure at the end of a long table, other people's plans spread out before him.","cn":"核心意象：长桌一端的人，面前摊着别人的计划。"},"chain":["DEAL IN MONEY","SENIOR BANKER","FUND AN ENTERPRISE","BACK ONE VENTURE","ADVISE","PUBLIC TREASURY"],"branches":[{"senses":"01 · 02","en":"THE PROFESSIONAL: large money dealing and the senior banking role.","cn":"专业人士：大额资金交易与高级银行角色。"},{"senses":"03 · 04","en":"THE FUNDER: capital for a company, and money for one expedition.","cn":"出资者：为一家公司提供资本，也为一次探险出钱。"},{"senses":"05","en":"THE ADVISER: money knowledge sold as counsel.","cn":"顾问：把金钱知识作为建议出售。"},{"senses":"06","en":"THE STATE: before corporations, the treasury was the biggest money office.","cn":"国家：在公司出现之前，国库是最大的资金机构。"},{"senses":"07 · 08","en":"THE CRITICISM AND THE VERB: detached dealing is mocked, and the role becomes an action.","cn":"批评与动词：脱离实业的交易受嘲讽，角色也转为动作。"}]},"affixes":{"intro":{"en":"The person-word is built from the noun of money management plus an agent suffix, and the whole family shares one Latin root.","cn":"这个指人的词由「资金管理」名词加施动后缀构成，整个词族共享一个拉丁词根。"},"latinIntro":{"en":"Finis and finire supply the root; the French agent ending supplies the person.","cn":"finis 与 finire 提供词根，法语施动词尾提供「人」的含义。"},"items":[{"word":"financier","structure":"finance + -ier (agent suffix, from Latin -arius)","meaning":"one who handles money","meaningCN":"金融家","example":"A financier arranged the loan.","exampleCN":"一位金融家安排了贷款。"},{"word":"finance","structure":"Old French finance (settlement of debt)","meaning":"money management","meaningCN":"财政；金融","example":"Finance approved the plan.","exampleCN":"财务部门批准了计划。"},{"word":"financial","structure":"finance + -ial (adjective suffix)","meaning":"relating to money","meaningCN":"财务的","example":"The financial review took a month.","exampleCN":"财务审查花了一个月。"},{"word":"financially","structure":"financial + -ly (adverb suffix)","meaning":"in money terms","meaningCN":"在财务上","example":"The firm is financially sound.","exampleCN":"这家公司财务稳健。"},{"word":"financing","structure":"finance + -ing (noun suffix)","meaning":"the act of funding","meaningCN":"融资","example":"Financing was arranged abroad.","exampleCN":"融资在海外安排。"},{"word":"financed","structure":"finance + -ed (adjective suffix)","meaning":"provided with funds","meaningCN":"获得资金支持的","example":"The line was privately financed.","exampleCN":"这条线路由私人出资。"},{"word":"refinance","structure":"re- (prefix 'again') + finance","meaning":"to fund again","meaningCN":"重新融资","example":"The city refinanced its bonds.","exampleCN":"该市重组了债券。"},{"word":"fine","structure":"finis (Latin noun 'end') through French","meaning":"a penalty that ends a case","meaningCN":"罚款","example":"The company paid a fine.","exampleCN":"公司缴纳了罚款。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (m./f., third declension)","meaning":"end, boundary, limit","meaningCN":"终点；边界；界限"},{"word":"finire","structure":"finire, finivi, finitum (verb, fourth conjugation)","meaning":"to end, to bound","meaningCN":"结束；限定"},{"word":"financiarius","structure":"financiarius (m., second declension, Medieval Latin)","meaning":"one who manages revenue","meaningCN":"管理岁入者"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financing","pos":"n.","zh":"融资"},{"word":"refinance","pos":"v.","zh":"重新融资"}]}},{"word":"financing","ipa_uk":"/fɪˈnænsɪŋ/","ipa_us":"/ˈfaɪnænsɪŋ/","definition_zh":"融资；为项目、企业或购买提供资金的行为与安排","definition_en":"the act or process of providing money for a project, business or purchase, and the arrangements through which it is raised","core_image":"一张桌上摊着银行贷款单、投资协议与还款时间表，几条资金渠道汇向同一个项目","scene":"新厂房的设备还没运到，会计先把贷款、股本与分期付款方案排成一列。The company secured financing for the new plant before construction began.","sceneCN":"此处指「为项目提供资金的行为与安排」（第 1 个义项：筹措资金的过程）；句意为公司在动工之前就为新厂房落实了融资。图中可辨识物件：贷款单、投资协议、还款时间表、厂房图纸。","pos":[{"tag":"n.","zh":"融资；筹资（行为与安排）"},{"tag":"n.","zh":"（具体的）融资方式或资金方案"}],"collocations":[{"phrase":"secure financing","zh":"落实融资"},{"phrase":"debt financing","zh":"债务融资"},{"phrase":"equity financing","zh":"股权融资"},{"phrase":"project financing","zh":"项目融资"},{"phrase":"financing costs","zh":"融资成本"},{"phrase":"a financing gap","zh":"资金缺口"},{"phrase":"short-term financing","zh":"短期融资"}],"forms":[{"label":"单数（不可数）","form":"financing"},{"label":"复数（罕见的多种融资安排）","form":"financings"},{"label":"动词原形（其来源动词）","form":"finance"},{"label":"动词现在分词","form":"financing"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"refinance","pos":"v.","zh":"重新融资"},{"word":"financed","pos":"adj.","zh":"获得资金支持的"}],"senses":[{"no":"01","title":"The act of providing funds","titleCN":"提供资金的行为","definition":"the act of supplying money so that a project, purchase or business can go ahead","definitionCN":"为使项目、购买或企业得以推进而提供金钱的行为","example":"The company secured financing for the new plant before construction began.","exampleCN":"公司在动工之前就为新厂房落实了融资。","why":"The noun of action turns the verb 'to fund' into the whole process of finding and supplying money.","whyCN":"表示动作的名词把「出资」这个动词变成寻找并提供资金的整个过程。"},{"no":"02","title":"A funding arrangement","titleCN":"具体的融资安排","definition":"a particular structure of loans, shares or credit arranged to pay for something","definitionCN":"为支付某项开支而安排的贷款、股份或信贷结构","example":"The financing combined a bank loan with a share issue.","exampleCN":"这项融资把银行贷款与股票发行结合起来。","why":"Money rarely arrives loose; it comes in a structured package, and the word names that package.","whyCN":"钱很少以散钱形式到来，而是以有结构的方案出现，这个词命名的正是这个方案。"},{"no":"03","title":"Debt financing","titleCN":"债务融资","definition":"raising money by borrowing, with repayment and interest obligations","definitionCN":"通过借款筹钱，并承担还本付息义务","example":"Debt financing raised the money quickly but added a fixed charge.","exampleCN":"债务融资很快筹到钱，却增加了固定支出。","why":"Borrowing is one of two main channels, so the word often appears with debt to specify that channel.","whyCN":"借款是两大渠道之一，因此这个词常与「债务」连用，指明这一渠道。"},{"no":"04","title":"Equity financing","titleCN":"股权融资","definition":"raising money by selling ownership shares rather than by borrowing","definitionCN":"通过出售所有权股份而非借款来筹钱","example":"Equity financing left the founders with less control.","exampleCN":"股权融资让创始人减少了控制权。","why":"The other main channel sells part of the business, and the word marks that choice as well.","whyCN":"另一主渠道是卖掉企业的一部分，这个词同样标示这一选择。"},{"no":"05","title":"Project financing","titleCN":"项目融资","definition":"a structure in which lenders are repaid from the cash flow of a specific project rather than from the whole company","definitionCN":"出借方靠某一项目自身的现金流而非整个公司获得偿还的结构","example":"Project financing kept the new road's debt off the city's main books.","exampleCN":"项目融资让新公路的债务不进入城市的主账。","why":"When a single large asset can stand on its own cash flow, finance can be ring-fenced around it.","whyCN":"当单个大型资产能靠自身现金流立足时，融资就可以围绕它隔离起来。"},{"no":"06","title":"The cost of raising money","titleCN":"融资成本","definition":"the interest, fees and other charges paid in order to obtain funds","definitionCN":"为获得资金而支付的利息、费用及其他支出","example":"Financing costs rose when the central rate went up.","exampleCN":"中心利率上升时，融资成本随之提高。","why":"Obtaining money is itself priced, so the word extends from the act to what the act costs.","whyCN":"取得金钱本身有价格，因此这个词从行为扩展到行为的花费。"},{"no":"07","title":"A shortfall of funds","titleCN":"资金缺口","definition":"the gap between the money a project needs and the money already secured","definitionCN":"项目所需资金与已落实资金之间的差额","example":"The final financing gap was covered by a grant.","exampleCN":"最后的资金缺口由一笔拨款填补。","why":"Plans often need more money than is first raised, and the word marks whatever remains unfunded.","whyCN":"计划所需常多于最初所筹，这个词就标示仍未筹到的那部分。"},{"no":"08","title":"The corporate funding function","titleCN":"公司的融资职能","definition":"the department or activity within an organisation that raises and manages capital","definitionCN":"组织内部筹集与管理资本的部门或活动","example":"Financing moved under the chief financial officer last year.","exampleCN":"融资职能去年划归财务总监管辖。","why":"In a firm the act becomes an ongoing function, with staff, policy and a place in the organisation.","whyCN":"在公司里，这一行为变成持续的职能，有人员、政策与组织位置。"}],"etymology":{"intro":{"en":"Financing is the action noun of the verb finance, whose root is Latin finis 'end', originally in the sense of settling a debt. Dates are approximate.","cn":"这个词是动词「为……融资」的动作名词，其词根为拉丁 finis「终点」，原指了结债务。年代均为约数。"},"items":[{"era":"LATIN FINIS","en":"Finis meant 'end, boundary, limit'; settling an account was pictured as bringing it to an end.","cn":"finis 意为「终点、边界、界限」；结清账目被想象成把它带到终点。"},{"era":"FRENCH FINANCE","en":"French finance named the settlement of payments and the management of revenue.","cn":"法语 finance 指款项结清与岁入管理。"},{"era":"ENGLISH NOUN","en":"English borrowed the noun for money management and later made a verb from it.","cn":"英语先借入这个表示资金管理的名词，后来又从它造出动词。"},{"era":"ACTION SUFFIX","en":"The English action suffix -ing turned the verb into a noun naming the whole process of funding.","cn":"英语的动作后缀把动词变成名词，命名整个筹资过程。"},{"era":"PROJECT FINANCE","en":"In the twentieth century the word spread from state revenue to corporate and project funding, where it now does most of its work.","cn":"到二十世纪，这个词从国家岁入扩展到公司与项目筹资，如今主要在这一领域使用。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation of the action noun): the earliest recorded use is not precisely dated.","cn":"首见年代不确定（动作名词）：最早用例没有确切年代。"}]},"similar":{"note":{"en":"Group one separates the process from the field and the person; group two holds words for money supplied and money owed.","cn":"第一组把过程与领域、人物分开；第二组是表示提供资金与欠款的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"finance","ipa":"/ˈfaɪnæns/","tag":"field or single act","definition":"Finance names the field or one act of funding, while financing stresses the process and its arrangements.","definitionCN":"finance 指领域或单次出资，financing 强调过程及其安排。"},{"word":"funding","ipa":"/ˈfʌndɪŋ/","tag":"the money itself","definition":"Funding often means the money supplied, whereas financing stresses how the money is raised and structured.","definitionCN":"funding 常指所提供的钱本身，financing 强调钱如何筹得与安排。"},{"word":"financier","ipa":"/fɪˈnænsɪə/","tag":"the person","definition":"A financier is a person who supplies or arranges capital, not the process of doing so.","definitionCN":"financier 是提供或安排资本的人，而不是这一过程。"},{"word":"financial","ipa":"/fɪˈnænʃəl/","tag":"the adjective","definition":"Financial describes money matters in general and does not name a process.","definitionCN":"financial 泛指金钱事务，不命名过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"capital","ipa":"/ˈkæpɪtl/","tag":"the stock of money","definition":"Capital is the money or assets available for investment, the substance that financing brings in.","definitionCN":"资本是可用于投资的资金或资产，是融资带来的东西。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"borrowing capacity","definition":"Credit is the capacity to borrow, one channel through which financing is obtained.","definitionCN":"信贷是借款能力，是获得融资的一条渠道。"},{"word":"investment","ipa":"/ɪnˈvestmənt/","tag":"money put into assets","definition":"Investment is money placed in assets for a return, often the purpose for which financing is raised.","definitionCN":"投资是为回报而投入资产的钱，常是融资所服务的目的。"},{"word":"loan","ipa":"/ləʊn/","tag":"one kind of funding","definition":"A loan is a single sum borrowed and repaid with interest, one building block of debt financing.","definitionCN":"贷款是一笔借入并还本付息的款项，是债务融资的组成部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real action suffix, the real family and the real channels.","cn":"正常联想：真实的动作后缀、真实的词族与真实的资金渠道。"},"normal":[{"en":"The action suffix turns the verb into the whole process of finding and supplying money.","cn":"动作后缀把动词变成寻找并提供资金的整个过程。"},{"en":"The two main channels are debt and equity, and the word pairs with both.","cn":"两大渠道是债务与股权，这个词与两者都能搭配。"},{"en":"A project can be funded on its own cash flow, which is what project financing means.","cn":"项目可以靠自身现金流筹资，这就是项目融资。"},{"en":"Raising money has a price, so financing costs appear beside the act itself.","cn":"筹钱有价格，因此融资成本与行为本身并列出现。"},{"en":"In a company the act becomes a standing function with staff and policy.","cn":"在公司里，这一行为成为有人员与政策的常设职能。"}],"abstract":[{"en":"Picture several pipes of money converging on one construction site.","cn":"想象几股资金管道汇向同一个工地。"},{"en":"Picture a bridge built of loans and shares, each plank labelled by its lender.","cn":"想象一座由贷款与股份搭成的桥，每块板都标着出借方。"},{"en":"Picture a gap in the budget being filled by a grant at the last moment.","cn":"想象预算中的缺口在最后一刻被一笔拨款填上。"}]},"examples":[{"en":"The firm arranged financing before it signed the construction contract.","cn":"这家公司在签建筑合同前就安排了融资。"},{"en":"Debt financing was cheaper then, but it raised the fixed burden.","cn":"当时债务融资更便宜，却提高了固定负担。"},{"en":"Project financing separated the new line's accounts from the operator's other debts.","cn":"项目融资把新线路的账目与运营者的其他债务分开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「费」加「难说」再加「进行」——把钱凑齐这件事正在推进，就是融资","word":"financing"},"root":"由动词「为……融资」加动作名词后缀构成；该动词经古法语来自拉丁 finis「终点、界限」，原指了结债务，后指资金管理。整个词表示筹措与安排资金的持续过程。","sensesIntro":{"en":"Eight senses follow one flow of money: funds are raised, structured, split into debt or equity, ring-fenced for a project, priced, short-filled and finally run as a standing function.","cn":"八个义项沿同一条资金流展开：钱被筹来、被安排成形、分为债务或股权、为项目隔离、被定价、出现缺口，最后成为常设职能。"},"semanticMap":{"core":{"en":"CORE IMAGE: several pipes of money converging on one construction site.","cn":"核心意象：几股资金管道汇向同一个工地。"},"chain":["RAISE MONEY","STRUCTURE THE PACKAGE","DEBT OR EQUITY","RING-FENCE A PROJECT","PRICE THE MONEY","CLOSE THE GAP"],"branches":[{"senses":"01 · 02","en":"THE FLOW AND THE PACKAGE: money is supplied, and the supply is shaped into a deal.","cn":"流动与方案：钱被提供出来，并提供方式被塑成一个交易。"},{"senses":"03 · 04","en":"THE TWO CHANNELS: borrowing and selling shares are the two main ways to raise funds.","cn":"两条渠道：借款与出售股份是筹钱的两条主路。"},{"senses":"05","en":"THE RING-FENCE: one project's cash flow can carry its own debt.","cn":"隔离：一个项目自身的现金流可以承担自己的债务。"},{"senses":"06 · 07","en":"THE PRICE AND THE HOLE: money costs something, and often falls short.","cn":"价格与缺口：钱有代价，而且常常不够。"},{"senses":"08","en":"THE FUNCTION: inside a firm, raising money becomes a permanent department.","cn":"职能：在公司内部，筹资成为常设部门。"}]},"affixes":{"intro":{"en":"Financing belongs to the Latin family of finis, and its relatives cover money, endings and penalties.","cn":"这个词属于拉丁 finis 词族，其同族词涵盖金钱、终结与罚金。"},"latinIntro":{"en":"Finis and finire supply the root; the action suffix supplies the process.","cn":"finis 与 finire 提供词根，动作后缀提供「过程」的含义。"},"items":[{"word":"financing","structure":"finance + -ing (action noun suffix)","meaning":"the process of providing funds","meaningCN":"融资","example":"Financing took three months to arrange.","exampleCN":"融资花了三个月才安排好。"},{"word":"finance","structure":"Old French finance (settlement of debt)","meaning":"money management","meaningCN":"财政；金融","example":"Finance approved the loan.","exampleCN":"财务部门批准了贷款。"},{"word":"financial","structure":"finance + -ial (adjective suffix)","meaning":"relating to money","meaningCN":"财务的；金融的","example":"Financial costs rose sharply.","exampleCN":"财务成本急剧上升。"},{"word":"financially","structure":"financial + -ly (adverb suffix)","meaning":"in money terms","meaningCN":"在财务上","example":"The project is financially feasible.","exampleCN":"这个项目在财务上可行。"},{"word":"financier","structure":"finance + -ier (agent suffix)","meaning":"one who handles large sums","meaningCN":"金融家","example":"A financier joined the board.","exampleCN":"一位金融家加入了董事会。"},{"word":"financed","structure":"finance + -ed (adjective suffix)","meaning":"provided with funds","meaningCN":"获得资金支持的","example":"The bridge was publicly financed.","exampleCN":"这座桥由公共资金支持。"},{"word":"refinance","structure":"re- (prefix 'again') + finance","meaning":"to fund again","meaningCN":"重新融资","example":"They refinanced at a lower rate.","exampleCN":"他们以更低利率重新融资。"},{"word":"fine","structure":"finis (Latin noun 'end') through French","meaning":"a penalty that ends a case","meaningCN":"罚款","example":"The bank paid a fine.","exampleCN":"这家银行缴纳了罚款。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (m./f., third declension)","meaning":"end, boundary, limit","meaningCN":"终点；边界；界限"},{"word":"finire","structure":"finire, finivi, finitum (verb, fourth conjugation)","meaning":"to end, to bound","meaningCN":"结束；限定"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"financially","pos":"adv.","zh":"在财务上"},{"word":"financier","pos":"n.","zh":"金融家"},{"word":"refinance","pos":"v.","zh":"重新融资"}]}},{"word":"financial institution","ipa_uk":"/fɪˈnænʃəl ˌɪnstɪˈtjuːʃən/","ipa_us":"/fəˈnænʃəl ˌɪnstɪˈtuːʃən/","definition_zh":"金融机构；从事吸收存款、发放贷款、投资或保险等金融业务的机构","definition_en":"an organization that provides financial services such as taking deposits, lending money, investing or insuring risks","core_image":"一条街上并排立着银行、保险公司与投资公司的门面，招牌不同，柜台后做的都是钱的生意","scene":"监管名单把银行、保险公司与信用社分在同一类。Regulators require every financial institution to report its capital position.","sceneCN":"此处指「从事金融业务的机构」（第 1 个义项：提供金融服务的组织）；句意为监管者要求每家金融机构报告资本状况。图中可辨识物件：银行门面、保险招牌、投资公司柜台、监管名单。","pos":[{"tag":"n.","zh":"金融机构（提供存款、贷款、投资或保险等服务的组织）"},{"tag":"n.","zh":"（法律与监管语境中的）金融机构类别"}],"collocations":[{"phrase":"a licensed financial institution","zh":"持牌金融机构"},{"phrase":"a regulated financial institution","zh":"受监管的金融机构"},{"phrase":"a major financial institution","zh":"大型金融机构"},{"phrase":"the failure of a financial institution","zh":"金融机构倒闭"},{"phrase":"non-bank financial institutions","zh":"非银行金融机构"},{"phrase":"international financial institutions","zh":"国际金融机构"}],"forms":[{"label":"单数","form":"financial institution"},{"label":"复数","form":"financial institutions"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"institution","pos":"n.","zh":"机构；制度"},{"word":"institutional","pos":"adj.","zh":"机构的；制度的"},{"word":"institutionalize","pos":"v.","zh":"使制度化"},{"word":"financier","pos":"n.","zh":"金融家"}],"senses":[{"no":"01","title":"An organization providing financial services","titleCN":"提供金融服务的组织","definition":"an organization whose business is to provide money-related services to customers or clients","definitionCN":"以向客户提供与金钱有关的服务为业的组织","example":"Regulators require every financial institution to report its capital position.","exampleCN":"监管者要求每家金融机构报告资本状况。","why":"The phrase joins the money domain with the general word for an established organization, giving the widest category sense.","whyCN":"这个词组把「金钱领域」与「常设组织」的一般词拼在一起，形成最宽的类别义。"},{"no":"02","title":"A bank","titleCN":"银行","definition":"a deposit-taking and lending institution, the central example of the category","definitionCN":"吸收存款并发放贷款的机构，是该类别的核心例子","example":"The local financial institution holds the town's savings.","exampleCN":"这家本地银行保管着全镇的储蓄。","why":"Banks are the prototype that the category was built around, so the phrase often simply means a bank.","whyCN":"银行是这个类别赖以成形的原型，因此这个词组常直接指银行。"},{"no":"03","title":"A non-bank lender or credit union","titleCN":"非银行放贷机构或信用社","definition":"a cooperative or specialist lender that takes deposits or makes loans without being a full bank","definitionCN":"非完整银行却吸收存款或发放贷款的合作社或专业放贷机构","example":"Credit unions count as financial institutions under the same rule.","exampleCN":"信用社按同一规则也算金融机构。","why":"Once the category is defined by function rather than charter, similar bodies that are not banks also fit.","whyCN":"一旦这个类别按功能而非牌照定义，不是银行的类似机构也纳入其中。"},{"no":"04","title":"An insurance company","titleCN":"保险公司","definition":"a firm that pools risk and pays claims, treated as financial because it holds and invests funds","definitionCN":"汇集风险并支付赔款的公司，因持有并投资基金而被视为金融机构","example":"Insurers are financial institutions because they invest the premiums they collect.","exampleCN":"保险公司属于金融机构，因为它们会投资所收保费。","why":"Risk pooling involves large invested funds, which brings insurers into the financial category.","whyCN":"风险汇集涉及大笔投资资金，这把保险公司带入金融类别。"},{"no":"05","title":"An investment firm","titleCN":"投资机构","definition":"a company that manages funds, trades securities or advises on investments","definitionCN":"管理基金、交易证券或提供投资建议的公司","example":"The pension fund hired a financial institution to manage its bonds.","exampleCN":"养老基金聘请一家金融机构管理其债券。","why":"Managing other people's money is a financial service even when no deposits are taken.","whyCN":"管理他人的钱即使不收存款也是金融服务。"},{"no":"06","title":"A regulated legal category","titleCN":"受监管的法律类别","definition":"the class of firms defined by law for licensing and supervision","definitionCN":"法律为发牌与监管而界定的机构类别","example":"The law lists which bodies count as financial institutions.","exampleCN":"法律列明哪些机构算作金融机构。","why":"Law needs a fixed list to know whom to supervise, so the phrase becomes a defined category.","whyCN":"法律需要固定名单才知道监管谁，因此这个词组成为被定义的类别。"},{"no":"07","title":"An international institution","titleCN":"国际金融机构","definition":"a multilateral body that lends to governments or stabilises markets across countries","definitionCN":"向各国政府贷款或稳定跨国市场的多边机构","example":"International financial institutions demanded a review of the budget.","exampleCN":"国际金融机构要求审查预算。","why":"When many states pool money for cross-border lending, the same phrase scales up to the multilateral level.","whyCN":"当多国汇集资金进行跨境放贷时，同一个词组就放大到多边层面。"},{"no":"08","title":"A payment or clearing institution","titleCN":"支付或清算机构","definition":"a body that moves payments or settles transactions between other institutions","definitionCN":"在其他机构之间转移支付或清算交易的机构","example":"Payment systems now include financial institutions that hold no customer deposits.","exampleCN":"支付系统如今包括不持有客户存款的金融机构。","why":"As payment systems grew separate from banks, the functional category had to absorb them too.","whyCN":"当支付系统逐渐与银行分离，功能类别也不得不把它们纳入。"}],"etymology":{"intro":{"en":"The phrase joins financial, from Latin finis 'end' through French, with institution, from Latin instituere 'to set up'. Dates are approximate.","cn":"这个词组把经法语来自拉丁 finis「终点」的「财务的」，与来自拉丁 instituere「设立」的「机构」拼在一起。年代均为约数。"},"items":[{"era":"LATIN FINIS","en":"Finis meant 'end, boundary, limit'; finance grew from the settling of debts.","cn":"finis 意为「终点、边界、界限」；「财政」从了结债务生长而来。"},{"era":"LATIN INSTITUERE","en":"Instituere meant 'to set up, establish, ordain', built from a prefix plus statuere 'to place, stand'.","cn":"instituere 意为「设立、建立、规定」，由前缀加 statuere「放置、站立」构成。"},{"era":"INSTITUTION IN ENGLISH","en":"Institution entered English through French for an established custom, law or organization.","cn":"「机构」经法语进入英语，指确立的习俗、法律或组织。"},{"era":"COMPOUND TERM","en":"The full phrase became common in law and regulation when states needed a class of firms to license and supervise.","cn":"当国家需要一类公司来发牌与监管时，完整词组在法律与监管中流行起来。"},{"era":"GLOBAL EXTENSION","en":"In the twentieth century the phrase extended to multilateral lenders and payment bodies.","cn":"到二十世纪，这个词组扩展到多边贷款机构与支付机构。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the exact earliest use of the compound is not recorded, and legal definitions differ between countries.","cn":"首见年代不确定：这一复合词的最早用例未被记录，各国法律定义也有差异。"}]},"similar":{"note":{"en":"Group one separates the category from individual kinds of firms; group two holds words for banks and for rule-making bodies.","cn":"第一组把类别与单类公司分开；第二组是表示银行与规则制定机构的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bank","ipa":"/bæŋk/","tag":"one member of the category","definition":"A bank is one kind of financial institution, the deposit-taking and lending prototype.","definitionCN":"银行是金融机构的一种，是吸收存款并放贷的原型。"},{"word":"financial firm","ipa":"/fɪˈnænʃəl fɜːm/","tag":"business, not legal category","definition":"Financial firm is a loose business term, while financial institution carries legal and regulatory weight.","definitionCN":"金融公司是宽松的商业说法，金融机构则带有法律与监管分量。"},{"word":"financial system","ipa":"/fɪˈnænʃəl ˈsɪstəm/","tag":"the network, not an organisation","definition":"The financial system is the whole network of institutions and markets, not a single organization.","definitionCN":"金融体系是机构与市场的整张网络，不是单一组织。"},{"word":"financial intermediary","ipa":"/fɪˈnænʃəl ˌɪntəˈmiːdiəri/","tag":"the middleman role","definition":"A financial intermediary stands between savers and borrowers, a functional description rather than a legal class.","definitionCN":"金融中介站在储蓄者与借款者之间，是功能描述而非法律类别。"}]},{"heading":"NEAR MEANING","entries":[{"word":"central bank","ipa":"/ˈsentrəl bæŋk/","tag":"the public monetary authority","definition":"A central bank manages a currency and the banking system, a special public kind of financial institution.","definitionCN":"中央银行管理货币与银行体系，是特殊而公共的一类金融机构。"},{"word":"credit union","ipa":"/ˈkredɪt ˈjuːniən/","tag":"member-owned lender","definition":"A credit union is a member-owned financial institution that lends to its own members.","definitionCN":"信用社是成员共有的金融机构，向本成员放贷。"},{"word":"investment bank","ipa":"/ɪnˈvestmənt bæŋk/","tag":"deal-making bank","definition":"An investment bank raises capital and advises on deals rather than mainly taking deposits.","definitionCN":"投资银行主要筹资并为交易提供建议，而非主要吸收存款。"},{"word":"regulator","ipa":"/ˈreɡjuleɪtə/","tag":"the supervisor, not the supervised","definition":"A regulator is the public body that supervises financial institutions rather than one of them.","definitionCN":"监管者是监督金融机构的公共机构，本身不是被监管的机构。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real two roots, the real legal phrase and the real functional range.","cn":"正常联想：真实的两部分词根、真实的法律说法与真实的功能范围。"},"normal":[{"en":"One half names money matters, the other names an established organization.","cn":"一半命名金钱事务，另一半命名常设组织。"},{"en":"A bank is the prototype; insurance and investment firms join by function.","cn":"银行是原型；保险与投资公司按功能加入。"},{"en":"The phrase matters most in law, where a fixed list decides who is supervised.","cn":"这个词组在法律中最重要，因为固定名单决定谁受监管。"},{"en":"International lenders use the same phrase at a larger scale.","cn":"国际贷款机构在更大尺度上使用同一个词组。"},{"en":"Payment and clearing bodies now fit the category even without deposits.","cn":"支付与清算机构即使不收存款，如今也纳入这一类别。"}],"abstract":[{"en":"Picture a street where every sign is different but every counter deals in money.","cn":"想象一条街，招牌各不相同，柜台后却都在做钱的生意。"},{"en":"Picture a rulebook with a list of names, each one a place that holds other people's money.","cn":"想象一本规则手册列着名单，每个名字都是保管他人钱财的地方。"},{"en":"Picture a network of nodes passing payments from one to another.","cn":"想象一张网络，节点之间彼此传递支付。"}]},"examples":[{"en":"Every financial institution must keep records of its capital and loans.","cn":"每家金融机构都必须保存资本与贷款记录。"},{"en":"The crisis spread because several financial institutions held similar risks.","cn":"危机扩散，是因为多家金融机构持有相似风险。"},{"en":"International financial institutions offered credit to the government.","cn":"国际金融机构向政府提供了信贷。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「财务的」加「机构」——凡是替人管钱、放贷、投资或保险的正规组织，就是金融机构","word":"financial institution"},"root":"前半经古法语来自拉丁 finis「终点、界限」，指金钱事务；后半经法语来自拉丁 instituere「设立、建立」，指常设组织。两部分合指以金钱服务为业的机构。","sensesIntro":{"en":"Eight senses follow one category: a broad class of money-serving organizations narrows to banks, then widens to non-bank lenders, insurers, investment firms, a legal class, multilateral bodies and payment systems.","cn":"八个义项沿同一个类别展开：先是一个宽泛的金钱服务机构类，再收窄到银行，又扩展到非银行放贷者、保险公司、投资机构、法律类别、多边机构与支付系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a street of different signs over counters that all deal in money.","cn":"核心意象：一条街上招牌各异，柜台后却都在做钱的生意。"},"chain":["SERVE MONEY","TAKE DEPOSITS AND LEND","NON-BANK LENDER","POOL RISK","MANAGE FUNDS","LEGAL CLASS"],"branches":[{"senses":"01 · 02","en":"THE CATEGORY AND ITS PROTOTYPE: a broad class, with the bank as its central case.","cn":"类别与原型：一个宽泛类别，以银行为核心例子。"},{"senses":"03","en":"THE FUNCTIONAL EDGE: similar bodies that are not full banks still fit.","cn":"功能边缘：不是完整银行的类似机构仍可纳入。"},{"senses":"04 · 05","en":"RISK AND FUNDS: insurers pool risk, investment firms manage money.","cn":"风险与资金：保险公司汇集风险，投资机构管理资金。"},{"senses":"06 · 07","en":"THE LAW AND THE WORLD: a licensed class, and multilateral lenders at a larger scale.","cn":"法律与世界：既是持牌类别，也在更大尺度上指多边贷款者。"},{"senses":"08","en":"THE PLUMBING: payment and clearing bodies join the category by function.","cn":"管道：支付与清算机构按功能加入这一类别。"}]},"affixes":{"intro":{"en":"The phrase combines two Latin-derived halves; together they name an organization whose business is money.","cn":"这个词组由两个拉丁来源的部分组成，合起来命名以金钱为业的组织。"},"latinIntro":{"en":"Finis and instituere supply the two halves, and both build large English families.","cn":"finis 与 instituere 提供两半，二者都衍生出大批英语词。"},"items":[{"word":"finance","structure":"Old French finance (settlement of debt)","meaning":"money management","meaningCN":"财政；金融","example":"Finance approved the plan.","exampleCN":"财务部门批准了计划。"},{"word":"financial","structure":"finance + -ial (adjective suffix)","meaning":"relating to money","meaningCN":"财务的；金融的","example":"Financial rules tightened.","exampleCN":"金融规则收紧了。"},{"word":"financially","structure":"financial + -ly (adverb suffix)","meaning":"in money terms","meaningCN":"在财务上","example":"The body is financially independent.","exampleCN":"该机构财务独立。"},{"word":"institution","structure":"instituere (Latin verb) + -ion (noun suffix)","meaning":"an established organization","meaningCN":"机构；制度","example":"The institution dates from the last century.","exampleCN":"该机构始于上个世纪。"},{"word":"institutional","structure":"institution + -al (adjective suffix)","meaning":"of an institution","meaningCN":"机构的；制度的","example":"Institutional investors bought the bonds.","exampleCN":"机构投资者买入了债券。"},{"word":"institutionalize","structure":"institutional + -ize (verb suffix)","meaning":"to make into a settled practice","meaningCN":"使制度化","example":"The rule was institutionalized in law.","exampleCN":"这条规则被写入法律。"},{"word":"financier","structure":"finance + -ier (agent suffix)","meaning":"one who handles large sums","meaningCN":"金融家","example":"A financier advised the treasury.","exampleCN":"一位金融家为国库提供建议。"},{"word":"financing","structure":"finance + -ing (action noun suffix)","meaning":"the act of providing funds","meaningCN":"融资","example":"Financing came from abroad.","exampleCN":"融资来自海外。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (m./f., third declension)","meaning":"end, boundary, limit","meaningCN":"终点；边界；界限"},{"word":"instituere","structure":"instituere, institui, institutum (verb, third conjugation)","meaning":"to set up, establish","meaningCN":"设立；建立"},{"word":"institutio","structure":"institutio, institutionis (f., third declension)","meaning":"a setting up, arrangement","meaningCN":"设立；制度"},{"word":"statuere","structure":"statuere, statui, statutum (verb, third conjugation)","meaning":"to place, set up","meaningCN":"放置；设立"}],"derivatives":[{"word":"finance","pos":"n./v.","zh":"财政；金融 / 为……融资"},{"word":"financial","pos":"adj.","zh":"财务的；金融的"},{"word":"institution","pos":"n.","zh":"机构；制度"},{"word":"institutional","pos":"adj.","zh":"机构的；制度的"},{"word":"institutionalize","pos":"v.","zh":"使制度化"},{"word":"financier","pos":"n.","zh":"金融家"}]}},{"word":"banking","ipa_uk":"/ˈbæŋkɪŋ/","ipa_us":"/ˈbæŋkɪŋ/","definition_zh":"银行业；银行从事的业务；也指银行部门的整体活动","definition_en":"the business carried on by banks, including taking deposits, lending and managing payments; the banking sector as a whole","core_image":"一排柜台后坐着出纳，窗口前的人存钱、取钱、转账，所有动作都围绕同一本账","scene":"街角的老楼里，出纳替人存钱、汇款，也替商户办理贷款。Banking grew quickly once the city allowed branch offices.","sceneCN":"此处指「银行从事的业务」（第 1 个义项：银行业的经营活动）；句意为城市允许开设分行之后，银行业迅速扩张。图中可辨识物件：柜台、存折、汇款单、贷款合同。","pos":[{"tag":"n.","zh":"银行业；银行业务"},{"tag":"n.","zh":"银行部门（作定语时指与银行有关的）"}],"collocations":[{"phrase":"retail banking","zh":"零售银行业务"},{"phrase":"commercial banking","zh":"商业银行业务"},{"phrase":"investment banking","zh":"投资银行业务"},{"phrase":"central banking","zh":"中央银行事务"},{"phrase":"the banking sector","zh":"银行部门"},{"phrase":"banking regulation","zh":"银行监管"},{"phrase":"online banking","zh":"网上银行服务"}],"forms":[{"label":"单数（不可数）","form":"banking"},{"label":"复数（罕见的多种银行体系）","form":"bankings"},{"label":"动词原形（其来源动词）","form":"bank"},{"label":"动词过去式","form":"banked"},{"label":"动词过去分词","form":"banked"}],"derivatives":[{"word":"bank","pos":"n./v.","zh":"银行 / 存钱；依赖"},{"word":"banker","pos":"n.","zh":"银行家"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的；可靠的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为……提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"},{"word":"embankment","pos":"n.","zh":"堤岸"}],"senses":[{"no":"01","title":"The business of banks","titleCN":"银行的业务活动","definition":"the business of taking deposits, lending money, transferring payments and keeping accounts for customers","definitionCN":"吸收存款、发放贷款、转移支付并为客户记账的业务","example":"Banking grew quickly once the city allowed branch offices.","exampleCN":"城市允许开设分行之后，银行业迅速扩张。","why":"The action noun turns the work done at a bank into the name of the whole industry.","whyCN":"动作名词把银行里做的事变成整个行业的名称。"},{"no":"02","title":"Retail banking","titleCN":"零售银行业务","definition":"services offered to individuals and small businesses, such as current accounts, savings and personal loans","definitionCN":"向个人与小企业提供的服务，如活期账户、储蓄与个人贷款","example":"Retail banking moved most of its branches online.","exampleCN":"零售银行业务把大部分网点搬到了线上。","why":"One branch of the industry serves ordinary customers, and the word often appears with retail to mark that side.","whyCN":"行业的一支服务普通客户，这个词常与「零售」连用标明这一面。"},{"no":"03","title":"Commercial banking","titleCN":"商业银行业务","definition":"lending and deposit services for companies, as distinct from investment dealing","definitionCN":"面向公司的贷款与存款服务，与投资交易相区别","example":"Commercial banking and investment banking were once kept apart by law.","exampleCN":"商业银行业务与投资银行业务曾由法律分开。","why":"The industry has a deposit side and a deal side, and commercial banking names the deposit and lending side.","whyCN":"这个行业有存款一侧与交易一侧，商业银行业务命名的是存款与放贷一侧。"},{"no":"04","title":"Investment banking","titleCN":"投资银行业务","definition":"raising capital and advising on mergers and securities for large clients","definitionCN":"为大客户筹资，并就并购与证券提供建议","example":"Investment banking earned more in fees than in interest.","exampleCN":"投资银行业务赚取的费用多于利息。","why":"The industry split into a deposit side and a deal side, and the word covers both.","whyCN":"这个行业分成存款一侧与交易一侧，这个词两面都涵盖。"},{"no":"05","title":"Central banking","titleCN":"中央银行事务","definition":"the public function of managing a currency, interest rates and the stability of the banking system","definitionCN":"管理货币、利率与银行体系稳定的公共职能","example":"Central banking became the main tool of crisis response.","exampleCN":"中央银行事务成为危机应对的主要工具。","why":"Above private banks sits a public authority, and its work is named by the same word with central in front.","whyCN":"私人银行之上还有公共当局，其工作由同一个词加「中央」来命名。"},{"no":"06","title":"The banking sector","titleCN":"银行部门","definition":"the industry as a whole, including all the firms that take deposits and lend","definitionCN":"整个行业，包括所有吸收存款并放贷的公司","example":"Banking employs more people in the city than shipping does.","exampleCN":"在这座城市，银行业雇用的员工多于航运业。","why":"A collection of firms doing the same work becomes a sector, and the word names that sector.","whyCN":"做同一件事的一批公司构成一个部门，这个词命名该部门。"},{"no":"07","title":"Banking services","titleCN":"银行服务","definition":"the concrete services customers receive, from payments to safe custody","definitionCN":"客户获得的具体服务，从支付到安全保管","example":"Mobile banking made payments possible without a branch.","exampleCN":"手机银行让支付不必再去网点。","why":"The abstract industry shows up in daily services, so the word also labels what a customer uses.","whyCN":"抽象行业体现在日常服务中，因此这个词也标示客户所使用的东西。"},{"no":"08","title":"Banking regulation","titleCN":"银行监管（定语用法）","definition":"the rules and supervision applied to banks, used as a modifier before nouns","definitionCN":"适用于银行的规则与监督，用作名词前的修饰语","example":"Banking rules tightened after the crisis.","exampleCN":"危机之后银行监管规则收紧了。","why":"An industry name used before a noun becomes an adjective-like label, which is how banking regulation and banking law work.","whyCN":"行业名称放在名词前就带上形容功能，银行监管、银行法就是这样构成的。"}],"etymology":{"intro":{"en":"Banking is the action noun of bank, whose money sense comes from Italian banca 'bench' and Medieval Latin bancus. Dates are approximate.","cn":"这个词是「银行」的动作名词，其金钱义来自意大利语 banca「长凳」与中世纪拉丁 bancus。年代均为约数。"},"items":[{"era":"GERMANIC BENCH","en":"The money sense of bank goes back to a Germanic word for a bench, the table at which a money changer worked.","cn":"银行的金钱义可追溯到日耳曼语中表示「长凳」的词，即钱币兑换商工作的桌子。"},{"era":"ITALIAN BANCA","en":"Italian banca named the bench and then the money changer's business, and it is the direct source of the financial sense.","cn":"意大利语 banca 先指长凳，后指钱币兑换商的生意，是金融义的直接来源。"},{"era":"MEDIEVAL LATIN BANCUS","en":"Medieval Latin bancus recorded the same bench and business, and it supplied the form that English borrowed.","cn":"中世纪拉丁 bancus 记录了同样的长凳与生意，并提供英语借入的形式。"},{"era":"ENGLISH BANK","en":"English bank first named the money business and later the institution itself.","cn":"英语先以这个词指金钱生意，后指机构本身。"},{"era":"ACTION NOUN","en":"The English action suffix -ing produced banking, naming the business and then the whole sector.","cn":"英语动作后缀产生这个词，先指生意，后指整个部门。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the exact date of the action noun is not recorded, and the river sense of bank is a separate homonym.","cn":"首见年代不确定：动作名词的确切年代未被记录，而「河岸」义是另一个同形异源词。"}]},"similar":{"note":{"en":"Group one separates banking from the institution, the person and the adjective; group two holds kinds of finance and the places money is kept.","cn":"第一组把银行业务与机构、人物、形容词分开；第二组是融资金融的种类与保管金钱的处所。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bank","ipa":"/bæŋk/","tag":"the institution itself","definition":"Bank is the institution or the verb to deposit; banking is the business carried on by such institutions.","definitionCN":"bank 是机构或「存钱」动词；banking 是这些机构从事的业务。"},{"word":"banker","ipa":"/ˈbæŋkə/","tag":"the person","definition":"A banker is a person who works in or owns a bank, not the industry.","definitionCN":"banker 是在银行工作或拥有银行的人，不是行业。"},{"word":"bankable","ipa":"/ˈbæŋkəbl/","tag":"the adjective","definition":"Bankable describes something a bank will accept or finance, not the business itself.","definitionCN":"bankable 描述银行愿意接受或提供资金的东西，不是业务本身。"},{"word":"embankment","ipa":"/ɪmˈbæŋkmənt/","tag":"river sense, different root line","definition":"Embankment belongs to the river-bank sense of bank and has nothing to do with money.","definitionCN":"embankment 属于「河岸」义，与金钱无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"finance","ipa":"/ˈfaɪnæns/","tag":"the wider money field","definition":"Finance is the broader field of money management, of which banking is one organised part.","definitionCN":"finance 是更宽的资金管理领域，banking 是其中有组织的一部分。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"lending capacity","definition":"Credit is the capacity to borrow or the lending itself, a core activity within banking.","definitionCN":"credit 是借款能力或放贷本身，是银行业务中的核心活动。"},{"word":"financial services","ipa":"/fɪˈnænʃəl ˈsɜːvɪsɪz/","tag":"the wider industry label","definition":"Financial services covers banking plus insurance, investment and payments.","definitionCN":"financial services 涵盖银行以及保险、投资与支付。"},{"word":"treasury","ipa":"/ˈtrezəri/","tag":"the place funds are held","definition":"A treasury is the office or account where funds are kept, a function banks also perform.","definitionCN":"treasury 是保管资金的部门或账户，银行也承担这一职能。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real bench origin, the real suffixes and the real sector phrases.","cn":"正常联想：真实的长凳词源、真实的后缀与真实的部门说法。"},"normal":[{"en":"The money word began at a bench where coins were changed.","cn":"金钱义始于兑换钱币的长凳。"},{"en":"The action suffix turns the work into the name of a business and then of a sector.","cn":"动作后缀把工作变成生意名称，再变成部门名称。"},{"en":"Retail, commercial, investment and central mark the four main branches of the industry.","cn":"零售、商业、投资与中央标出这个行业的四个主要分支。"},{"en":"Banking regulation and banking law use the industry name as a modifier.","cn":"银行监管与银行法把行业名当作修饰语。"},{"en":"The river sense of bank is a different word and must not be mixed in.","cn":"「河岸」义属于另一个词，不可混入。"}],"abstract":[{"en":"Picture a row of counters where money moves from hand to hand all day.","cn":"想象一排柜台，钱整天在手中流转。"},{"en":"Picture a bench that grew walls, a roof and a vault without changing its purpose.","cn":"想象一张长凳长出墙壁、屋顶与金库，用途却没变。"},{"en":"Picture a city where the tallest buildings are all full of accounts.","cn":"想象一座城市，最高的楼里全是账目。"}]},"examples":[{"en":"Banking provides the payment system on which the rest of the economy depends.","cn":"银行业提供支付系统，其他经济部门都依赖它。"},{"en":"Online banking reduced the number of branch visits.","cn":"网上银行减少了到网点的次数。"},{"en":"Central banking became the first line of defence in the crisis.","cn":"中央银行事务成为危机中的第一道防线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「板」加「金」——兑换商在长板桌后做金钱生意，这种行当就是银行业","word":"banking"},"root":"由「银行」加动作名词后缀构成。「银行」的金钱义来自意大利语 banca「长凳」，经中世纪拉丁 bancus 进入英语，指钱币兑换商工作的桌子及其生意；「河岸」义为另一同形异源词。","sensesIntro":{"en":"Eight senses follow one business: the work at the counter becomes an industry, then splits into retail, commercial, investment and central branches, becomes a sector, appears as daily services and finally as a modifier for rules.","cn":"八个义项沿同一门生意展开：柜台后的工作先成为行业，再分为零售、商业、投资与中央四支，成为部门，体现为日常服务，最后成为规则的修饰语。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of counters where money moves from hand to hand all day.","cn":"核心意象：一排柜台，钱整天在手中流转。"},"chain":["TAKE DEPOSITS","LEND MONEY","RETAIL COUNTER","COMMERCIAL LENDING","INVESTMENT DEALS","PUBLIC AUTHORITY"],"branches":[{"senses":"01 · 06","en":"THE BUSINESS AND THE SECTOR: counter work becomes a trade, then a whole industry.","cn":"业务与部门：柜台工作先成为行当，再成为整个行业。"},{"senses":"02","en":"THE ORDINARY COUNTER: individuals and small firms are served at the retail side.","cn":"普通柜台：个人与小企业由零售一侧服务。"},{"senses":"03 · 04","en":"THE TWO DEALS: lending to companies and raising capital for large clients.","cn":"两种交易：向公司放贷，以及为大客户筹资。"},{"senses":"05","en":"THE PUBLIC ROOF: a central authority manages the currency and the system.","cn":"公共屋顶：中央当局管理货币与体系。"},{"senses":"07 · 08","en":"THE SERVICE AND THE RULE: what a customer uses, and what regulators impose.","cn":"服务与规则：客户使用的东西，以及监管者施加的要求。"}]},"affixes":{"intro":{"en":"Banking belongs to the bench family of words; its money sense and its river sense are separate homonyms.","cn":"这个词属于「长凳」词族；其金钱义与河岸义是两个独立的同形异源词。"},"latinIntro":{"en":"Medieval Latin bancus supplies the money sense; the river sense comes from a different northern source.","cn":"中世纪拉丁 bancus 提供金钱义；河岸义来自另一个北方来源。"},"items":[{"word":"bank","structure":"Italian banca (bench) through Medieval Latin bancus","meaning":"a money institution","meaningCN":"银行","example":"The bank opened a new branch.","exampleCN":"这家银行开设了新分行。"},{"word":"banking","structure":"bank + -ing (action noun suffix)","meaning":"the business of banks","meaningCN":"银行业；银行业务","example":"Banking employs many graduates.","exampleCN":"银行业雇用许多毕业生。"},{"word":"banker","structure":"bank + -er (agent suffix)","meaning":"one who works in a bank","meaningCN":"银行家","example":"The banker approved the loan.","exampleCN":"银行家批准了贷款。"},{"word":"bankable","structure":"bank + -able (adjective suffix)","meaning":"acceptable to a bank","meaningCN":"可获银行支持的","example":"The plan is bankable.","exampleCN":"这个计划可获得银行支持。"},{"word":"bankroll","structure":"bank + roll (compound noun)","meaning":"a supply of money","meaningCN":"资金","example":"An investor provided the bankroll.","exampleCN":"一位投资者提供了资金。"},{"word":"banknote","structure":"bank + note (compound noun)","meaning":"paper money issued by a bank","meaningCN":"纸币","example":"The old banknote is now a collector's item.","exampleCN":"旧纸币如今成了收藏品。"},{"word":"embankment","structure":"em- (prefix 'in') + bank (river sense) + -ment","meaning":"a raised bank of earth","meaningCN":"堤岸","example":"The embankment held back the flood.","exampleCN":"堤岸挡住了洪水。"},{"word":"banked","structure":"bank + -ed (past participle)","meaning":"deposited or tilted","meaningCN":"已存入的；倾斜的","example":"The plane banked sharply.","exampleCN":"飞机急剧倾斜。"}],"latinEntries":[{"word":"bancus","structure":"bancus, banci (m., second declension, Medieval Latin)","meaning":"bench, money table","meaningCN":"长凳；钱桌"},{"word":"bancarius","structure":"bancarius, bancarii (m., second declension, Medieval Latin)","meaning":"money changer","meaningCN":"钱币兑换商"}],"derivatives":[{"word":"bank","pos":"n./v.","zh":"银行 / 存钱；依赖"},{"word":"banker","pos":"n.","zh":"银行家"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为……提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"}]}},{"word":"bank","ipa_uk":"/bæŋk/","ipa_us":"/bæŋk/","definition_zh":"银行；岸、堤；堆、储存库；也作动词：存钱、依赖、使倾斜","definition_en":"an institution that holds money and lends it; also the edge of a river, a mass or store of something, and a verb meaning to deposit, rely on or tilt","core_image":"一边是柜台与金库，另一边是河岸与土堆，同一个拼写装着两种完全不同的东西","scene":"她每月把工资的一部分存进街角的银行。The bank approved the loan after reviewing the shop's accounts.","sceneCN":"此处指「银行机构」（第 1 个义项：吸收存款并放贷的机构）；句意为银行在审阅店铺账目后批准了贷款。图中可辨识物件：柜台、金库门、存折、河岸与土堆（用于对照另一义项）。","pos":[{"tag":"n.","zh":"银行（吸收存款并发放贷款的机构）"},{"tag":"n.","zh":"岸；堤；（河、湖的）边坡"},{"tag":"n.","zh":"堆；储存库（如血库、数据库）"},{"tag":"n.","zh":"一排（同类物件，如一排开关）"},{"tag":"v.","zh":"把（钱）存入银行"},{"tag":"v.","zh":"依赖；指望（后接介词，表示所依赖的对象）"},{"tag":"v.","zh":"使（飞机）倾斜转弯"}],"collocations":[{"phrase":"bank account","zh":"银行账户"},{"phrase":"bank loan","zh":"银行贷款"},{"phrase":"the bank of a river","zh":"河岸"},{"phrase":"a blood bank","zh":"血库"},{"phrase":"a bank of clouds","zh":"一堆积云"},{"phrase":"bank on","zh":"依赖；指望"},{"phrase":"bank the plane","zh":"使飞机倾斜"}],"forms":[{"label":"单数","form":"bank"},{"label":"复数","form":"banks"},{"label":"动词三单","form":"banks"},{"label":"动词过去式","form":"banked"},{"label":"动词过去分词","form":"banked"},{"label":"动词现在分词","form":"banking"}],"derivatives":[{"word":"banker","pos":"n.","zh":"银行家"},{"word":"banking","pos":"n.","zh":"银行业务"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为……提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"},{"word":"embankment","pos":"n.","zh":"堤岸"}],"senses":[{"no":"01","title":"A financial institution","titleCN":"银行机构","definition":"an institution that takes deposits, lends money and provides payment services","definitionCN":"吸收存款、发放贷款并提供支付服务的机构","example":"The bank approved the loan after reviewing the shop's accounts.","exampleCN":"银行在审阅店铺账目后批准了贷款。","why":"The money sense began at a changer's bench, and the bench became the institution, so this is the word's first modern sense.","whyCN":"金钱义始于兑换商的长凳，长凳后来变成机构，因此这是这个词的首要现代义。"},{"no":"02","title":"The edge of a river","titleCN":"河岸","definition":"the raised ground along the side of a river or canal","definitionCN":"河流或运河两侧高出水面的地面","example":"Willows line the bank of the river below the mill.","exampleCN":"磨坊下游的河岸上长着一排柳树。","why":"This sense comes from a different northern word for a raised edge, not from the money bench, though the spelling merged.","whyCN":"这一义项来自另一个表示隆起边缘的北方词，而非金钱长凳，只是拼写合并了。"},{"no":"03","title":"A mass or store of something","titleCN":"堆；储存库","definition":"a large mass of material, or a place where something is kept for later use","definitionCN":"大量堆积的物料，或为以后使用而保存某物的地方","example":"The hospital opened a blood bank for emergencies.","exampleCN":"医院为急救开设了血库。","why":"A heap of snow resembles a raised edge, and a store arranged in heaps became a bank of data or blood.","whyCN":"积雪堆的形状像隆起的边，按堆存放东西的地方就成了数据库或血库。"},{"no":"04","title":"To deposit money","titleCN":"把钱存入银行","definition":"to put money into a bank account","definitionCN":"把钱放进银行账户","example":"She banks her wages on the first day of each month.","exampleCN":"她每月第一天把工资存入银行。","why":"The verb simply makes the institution's core action into an action word.","whyCN":"动词只是把机构的核心动作变成动作词。"},{"no":"05","title":"To rely on","titleCN":"依赖；指望","definition":"to depend on something happening, used in the phrase bank on","definitionCN":"指望某事发生，用于固定说法","example":"Do not bank on the grant arriving before the deadline.","exampleCN":"不要指望拨款在截止前到账。","why":"Reliance is pictured as leaning on a solid support, and a raised bank is exactly such a support.","whyCN":"依赖被想象成倚靠稳固的支撑，而隆起的河岸正是这样的支撑。"},{"no":"06","title":"The house in a gambling game","titleCN":"赌局中的庄家","definition":"the reserve of money held by the house, or the house itself, in games of chance","definitionCN":"赌局中庄家持有的资金储备，或庄家一方","example":"The bank won three rounds before the players recovered.","exampleCN":"庄家连赢三局后，玩家才扳回一些。","why":"A pool of money kept by one side is a reserve, and a reserve was already called by the same word in the storage sense.","whyCN":"由一方保管的一笔钱就是储备，而储备在储存义中早已用同一个词表示。"},{"no":"07","title":"To tilt an aircraft","titleCN":"使飞机倾斜","definition":"to turn an aircraft so that one wing is higher than the other","definitionCN":"使飞机一侧机翼高于另一侧地转弯","example":"The pilot banked sharply to avoid the storm.","exampleCN":"飞行员急剧倾斜转弯以避开风暴。","why":"A tilted surface resembles a sloping bank of earth, so the aviation term borrows the slope image.","whyCN":"倾斜的表面像斜坡状的土堤，航空术语因此借用了斜坡意象。"},{"no":"08","title":"A row of similar objects","titleCN":"一排同类物件","definition":"a row or tier of similar things arranged side by side, as switches or seats","definitionCN":"并排排列的一排或一层同类物，如开关或座位","example":"He flipped the whole bank of switches before leaving.","exampleCN":"离开前他关掉了整排开关。","why":"Things arranged in a long row look like a raised ridge, which is how the row sense arose.","whyCN":"排成长串的物件看起来像隆起的脊，这就是「一排」义的来由。"},{"no":"09","title":"A raised slope or terrace","titleCN":"隆起的斜坡或台地","definition":"a long raised slope, terrace or mound of earth","definitionCN":"长长隆起的斜坡、台地或土丘","example":"The children rolled down the grassy bank behind the school.","exampleCN":"孩子们从学校后面的草坡滚下来。","why":"The oldest image in this word family is a raised edge or mound, and this sense keeps that image most purely.","whyCN":"这个词族最古老的意象就是隆起的边缘或土丘，这一义项最纯粹地保留了它。"}],"etymology":{"intro":{"en":"Bank has two separate histories that merged in spelling: a money word from Italian banca and a landscape word from northern Germanic. Dates are approximate.","cn":"这个词有两条独立的历史在拼写上合并：一条来自意大利语 banca 的金钱词，一条来自北方日耳曼语的地形词。年代均为约数。"},"items":[{"era":"GERMANIC BENCH","en":"A Germanic word for a bench or raised shelf gave the money sense through the table where coins were changed.","cn":"日耳曼语中表示长凳或高台的一个词，经兑换钱币的桌子，给出了金钱义。"},{"era":"ITALIAN BANCA","en":"Italian banca named the bench and then the business conducted at it, and this is the direct source of the financial word.","cn":"意大利语 banca 先指长凳，后指在长凳上做的生意，是金融词的直接来源。"},{"era":"MEDIEVAL LATIN BANCUS","en":"Medieval Latin bancus recorded the bench and the money trade, and English borrowed the form in the sixteenth century.","cn":"中世纪拉丁 bancus 记录了长凳与金钱交易，英语在十六世纪借入该形式。"},{"era":"RIVER SENSE","en":"The river sense came from a northern word for a raised edge or slope and is not related to the money bench at all.","cn":"河岸义来自北方表示隆起边缘或斜坡的词，与金钱长凳毫无关系。"},{"era":"SENSE EXPANSION","en":"From the money institution the word extended to reserves, stores, rows and the verb to deposit or rely.","cn":"从金钱机构出发，这个词扩展到储备、储存、成排之物，以及存钱或依赖的动词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (pre-Italian origin): the deeper origin of banca is not settled, and the exact date when the two words merged in spelling is not recorded.","cn":"来源不确定（意大利语之前的来源）：banca 的更早来源无定论，两个词合并拼写的确切年代也未被记录。"}]},"similar":{"note":{"en":"Group one separates the many senses that share one spelling; group two holds words for money institutions and sloping ground.","cn":"第一组区分共享同一拼写的多个义项；第二组是表示金钱机构与倾斜地面的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"banking","ipa":"/ˈbæŋkɪŋ/","tag":"the industry","definition":"Banking is the business carried on by banks, not the institution or the river edge.","definitionCN":"banking 是银行从事的业务，不是机构或河岸。"},{"word":"banker","ipa":"/ˈbæŋkə/","tag":"the person","definition":"A banker works in a bank; bank is the place and the verb.","definitionCN":"banker 在银行工作；bank 是机构与动词。"},{"word":"bench","ipa":"/bentʃ/","tag":"the word behind the money sense","definition":"Bench is the literal seat that gave the money sense its name; bank and bench are relatives, not synonyms.","definitionCN":"bench 是给金钱义命名的字面长凳；bank 与 bench 是同族词，却不是同义词。"},{"word":"banque","ipa":"/bɑːŋk/","tag":"French cousin","definition":"The French form banque is a cousin of the money sense and has no river meaning.","definitionCN":"法语形式 banque 是金钱义的同族词，没有河岸义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shore","ipa":"/ʃɔː/","tag":"land at water","definition":"Shore is the general word for land along a sea or lake; bank is used more for rivers and canals.","definitionCN":"shore 是海边或湖边的通称；bank 更常用于河流与运河。"},{"word":"slope","ipa":"/sləʊp/","tag":"inclined ground","definition":"Slope is any inclined surface, while bank suggests a raised edge beside water or a long mound.","definitionCN":"slope 指任何倾斜面；bank 暗示水边隆起的边或长长的土丘。"},{"word":"treasury","ipa":"/ˈtrezəri/","tag":"where funds are kept","definition":"Treasury is the office or account holding funds, a narrower function than a bank.","definitionCN":"treasury 是保管资金的部门或账户，职能比银行窄。"},{"word":"deposit","ipa":"/dɪˈpɒzɪt/","tag":"the act bank also names","definition":"Deposit is the act of placing money somewhere, which the verb bank can also express.","definitionCN":"deposit 是把钱放入某处的动作，动词 bank 也能表达这层意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real bench origin, the real homonym split and the real verb family.","cn":"正常联想：真实的长凳词源、真实的同形异源分裂与真实的动词词族。"},"normal":[{"en":"The money sense began at a bench; the river sense began as a raised edge.","cn":"金钱义始于一张长凳；河岸义始于隆起的边缘。"},{"en":"The same spelling covers heaps, stores, rows and a gambling reserve because all look like raised piles.","cn":"同一拼写涵盖堆、储存、成排之物与赌本，因为它们都像隆起的堆积。"},{"en":"The verb means to deposit, to rely on, or to tilt, each from a different image of support or slope.","cn":"动词意为存钱、依赖或倾斜，各自来自支撑或斜坡的不同意象。"},{"en":"Bank on is the fixed phrase for reliance and takes a clause or noun.","cn":"「指望」是依赖义的固定说法，后接从句或名词。"},{"en":"The river sense must not be linked to the money origin in etymology.","cn":"河岸义在词源上不能与金钱来源相连。"}],"abstract":[{"en":"Picture a bench on one side of a road and a grassy river edge on the other, sharing one name.","cn":"想象路的一侧是长凳，另一侧是长草的河岸，二者共用一个名字。"},{"en":"Picture a pile of snow that looks like a place where value is stored.","cn":"想象一堆雪，看起来像存放价值的地方。"},{"en":"Picture a plane leaning like a slope as it turns.","cn":"想象飞机转弯时像斜坡一样倾斜。"}]},"examples":[{"en":"The bank waived the fee for the first year.","cn":"这家银行免除了第一年的费用。"},{"en":"They sat on the bank and watched the boats pass.","cn":"他们坐在河岸上看船只驶过。"},{"en":"You can bank on the trains being late in the fog.","cn":"雾天里你可以指望火车晚点。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「板」加「克」——兑换商靠一块长板桌做生意，这块板后来变成银行；河岸也像隆起的板","word":"bank"},"root":"金钱义来自意大利语 banca「长凳」，经中世纪拉丁 bancus 进入英语，指兑换商的钱桌及其生意；河岸义来自北方日耳曼语中表示隆起边缘的词，与金钱义无关。两组义项拼写合并后，又扩展出储存、成排、存钱、依赖与倾斜等用法。","sensesIntro":{"en":"Nine senses follow two merged histories: a money institution and a raised edge each grow their own branches, then share verbs of depositing, relying, tilting and rows.","cn":"九个义项沿两条合并的历史展开：金钱机构与隆起边缘各自长出分支，再共享存钱、依赖、倾斜与成排等动词与名词用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a money counter on one side and a grassy river edge on the other, both called by one name.","cn":"核心意象：一边是金钱柜台，一边是长草的河岸，二者共用一个名字。"},"chain":["MONEY TABLE","INSTITUTION","RESERVE OR STORE","DEPOSIT","RELY ON","RAISED EDGE"],"branches":[{"senses":"01 · 04","en":"THE MONEY LINE: a bench becomes an institution, and its core act becomes a verb.","cn":"金钱线：长凳变成机构，其核心动作变成动词。"},{"senses":"02 · 09","en":"THE LAND LINE: river edge and grassy slope share one raised-edge image.","cn":"土地线：河岸与草坡共享同一个隆起边缘意象。"},{"senses":"03 · 06","en":"THE STORE: heaps and reserves are piles kept for later.","cn":"储存：堆与储备都是留待后用的堆积。"},{"senses":"05","en":"THE SUPPORT: relying on something is leaning on a firm edge.","cn":"支撑：依赖某物就是倚在稳固的边上。"},{"senses":"07 · 08","en":"THE SLOPE AND THE ROW: a tilted plane and a long line both follow the ridge image.","cn":"斜面与长排：倾斜的平面与长长的行列都沿用了脊状意象。"}]},"affixes":{"intro":{"en":"Bank has two source lines that merged in spelling, and its large family of words grows mostly from the money line.","cn":"这个词有两条在拼写上合并的来源线，其庞大的词族主要从金钱线生长。"},"latinIntro":{"en":"Medieval Latin bancus supplies the money form; the river sense has no Latin source.","cn":"中世纪拉丁 bancus 提供金钱义形式；河岸义没有拉丁语来源。"},"items":[{"word":"bank","structure":"Italian banca (bench) through Medieval Latin bancus","meaning":"a money institution","meaningCN":"银行","example":"The bank opened late.","exampleCN":"这家银行开门晚。"},{"word":"banker","structure":"bank + -er (agent suffix)","meaning":"one who works in a bank","meaningCN":"银行家","example":"The banker signed the draft.","exampleCN":"银行家签了汇票。"},{"word":"banking","structure":"bank + -ing (action noun suffix)","meaning":"the business of banks","meaningCN":"银行业务","example":"Banking expanded rapidly.","exampleCN":"银行业务迅速扩张。"},{"word":"bankable","structure":"bank + -able (adjective suffix)","meaning":"acceptable to a bank","meaningCN":"可获银行支持的","example":"The proposal is bankable.","exampleCN":"这份提案可获得银行支持。"},{"word":"bankroll","structure":"bank + roll (compound noun)","meaning":"a supply of money","meaningCN":"资金","example":"He supplied the bankroll.","exampleCN":"他提供了资金。"},{"word":"banknote","structure":"bank + note (compound noun)","meaning":"paper money","meaningCN":"纸币","example":"The banknote was torn.","exampleCN":"这张纸币破损了。"},{"word":"embankment","structure":"em- (prefix 'in') + bank (river sense) + -ment","meaning":"a raised bank of earth","meaningCN":"堤岸","example":"The embankment held.","exampleCN":"堤岸没有溃决。"},{"word":"banked","structure":"bank + -ed (past participle)","meaning":"deposited or tilted","meaningCN":"已存入的；倾斜的","example":"The plane banked left.","exampleCN":"飞机向左倾斜。"}],"latinEntries":[{"word":"bancus","structure":"bancus, banci (m., second declension, Medieval Latin)","meaning":"bench, money table","meaningCN":"长凳；钱桌"},{"word":"bancarius","structure":"bancarius, bancarii (m., second declension, Medieval Latin)","meaning":"money changer","meaningCN":"钱币兑换商"}],"derivatives":[{"word":"banker","pos":"n.","zh":"银行家"},{"word":"banking","pos":"n.","zh":"银行业务"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为……提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"},{"word":"embankment","pos":"n.","zh":"堤岸"}]}},{"word":"banker","ipa_uk":"/ˈbæŋkə/","ipa_us":"/ˈbæŋkər/","definition_zh":"银行家；银行经理或高级职员；也指赌局中的庄家","definition_en":"a senior officer or owner of a bank; also the person who keeps the table's funds in some gambling games","core_image":"一位穿西装的人坐在银行柜台后的办公室里，手边是账册与印章；牌桌另一端，另一个人守着筹码箱","scene":"分行经理在贷款文件上盖章，随后把副本交给客户。The banker refused to lend more until the accounts were audited.","sceneCN":"此处指「银行经理或高级职员」（第 1 个义项：银行中的高级任职者）；句意为这位银行经理坚持账目审计完成前不再放贷。图中可辨识物件：账册、印章、贷款文件、筹码箱（用于对照赌博义）。","pos":[{"tag":"n.","zh":"银行家；银行经理或高级职员"},{"tag":"n.","zh":"赌局中的庄家"},{"tag":"n.","zh":"（口语）十拿九稳的事"}],"collocations":[{"phrase":"an investment banker","zh":"投资银行家"},{"phrase":"a central banker","zh":"中央银行家"},{"phrase":"a private banker","zh":"私人银行家"},{"phrase":"a merchant banker","zh":"商人银行家"},{"phrase":"a banker's draft","zh":"银行汇票"},{"phrase":"a banker's dozen","zh":"（旧）十三，多给一个"}],"forms":[{"label":"单数","form":"banker"},{"label":"复数","form":"bankers"},{"label":"所有格","form":"banker's"},{"label":"复数所有格","form":"bankers'"}],"derivatives":[{"word":"bank","pos":"n./v.","zh":"银行 / 存钱；依赖"},{"word":"banking","pos":"n.","zh":"银行业务"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为……提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"},{"word":"embankment","pos":"n.","zh":"堤岸"}],"senses":[{"no":"01","title":"A senior bank officer","titleCN":"银行高级职员","definition":"a senior manager or officer who works in a bank and decides on loans and accounts","definitionCN":"在银行工作、负责贷款与账户的高级经理或职员","example":"The banker refused to lend more until the accounts were audited.","exampleCN":"这位银行经理坚持账目审计完成前不再放贷。","why":"The agent suffix marks the person who does the bank's work, so the first sense is a senior person inside the institution.","whyCN":"施动后缀标示做银行业务的人，因此第一义就是机构内的高级任职者。"},{"no":"02","title":"An owner or principal of a bank","titleCN":"银行所有者或主要负责人","definition":"the owner or principal of a banking house, especially in private banking","definitionCN":"银行钱庄的所有者或主要负责人，尤指私人银行","example":"The banker staked his own fortune on the new branch.","exampleCN":"这位银行家把自己的财产押在新分行上。","why":"Where banks were family firms, the person who owned the house was the bank, and the word kept that personal sense.","whyCN":"当银行是家族企业时，拥有钱庄的人就是银行，这个词保留了这种人身义。"},{"no":"03","title":"An investment banker","titleCN":"投资银行家","definition":"a professional who raises capital and advises on mergers, acquisitions and securities","definitionCN":"负责筹资并就并购与证券提供建议的专业人士","example":"The investment banker valued the company before the sale.","exampleCN":"投资银行家在出售前对这家公司作了估值。","why":"Investment banking created a separate professional identity, and the word followed that specialisation.","whyCN":"投资银行业务造就了独立的职业身份，这个词也随之专指这一行。"},{"no":"04","title":"A central banker","titleCN":"中央银行家","definition":"an official of a central bank who sets monetary policy or supervises the banking system","definitionCN":"制定货币政策或监督银行体系的中央银行官员","example":"Central bankers met to discuss the interest rate.","exampleCN":"中央银行家们开会讨论利率。","why":"Public monetary authority is a distinct role, and the word with central in front names its officials.","whyCN":"公共货币当局是另一种角色，这个词加「中央」即指其官员。"},{"no":"05","title":"The keeper of a gambling table's funds","titleCN":"赌局资金的掌管者","definition":"the person who holds and pays out the table's money in certain gambling games","definitionCN":"在某些赌局中保管并支付桌面资金的人","example":"The banker dealt the cards and covered the bets.","exampleCN":"庄家发牌并赔付赌注。","why":"A bank also meant a reserve of money, so the person who kept the table's reserve took the same name.","whyCN":"这个词也指一笔资金储备，掌管桌面储备的人因此得了同一个名称。"},{"no":"06","title":"The house side in a game","titleCN":"赌局中的庄家一方","definition":"the side that holds the reserve and against which other players bet","definitionCN":"持有资金储备、其他玩家与之对赌的一方","example":"The banker won back the losses in the last round.","exampleCN":"庄家方在最后一局赢回了损失。","why":"The person and the side blur in play, so the word also names the house as an opponent.","whyCN":"在牌局中人与一方会混同，因此这个词也指作为对手的庄家。"},{"no":"07","title":"An informal certainty","titleCN":"口语中十拿九稳的事","definition":"something regarded as certain to succeed, used in informal British speech","definitionCN":"被认为必定成功的事，用于非正式的英式口语","example":"The deal is a banker if the board agrees.","exampleCN":"只要董事会同意，这笔交易就十拿九稳。","why":"A reliable bank was a safe place for money, and the person-word became slang for a sure thing.","whyCN":"可靠的银行是存钱的安全处，指人的词因此成为表示「稳赢」的俚语。"},{"no":"08","title":"A financial adviser or expert","titleCN":"金融顾问或专家","definition":"an expert who advises governments or firms on money, credit and financial structure","definitionCN":"就金钱、信贷与财务结构向政府或公司提供建议的专家","example":"The treasury hired a banker to restructure its debt.","exampleCN":"国库聘请一位金融专家重组债务。","why":"Expertise in money is a service, so the person-word also covers the advisory role outside a bank.","whyCN":"金钱方面的专长是一种服务，因此这个指人的词也涵盖银行之外的顾问角色。"}],"etymology":{"intro":{"en":"Banker is bank plus an agent suffix from Latin -arius through French. The money sense of bank comes from Italian banca 'bench'. Dates are approximate.","cn":"这个词是「银行」加施动后缀，该后缀经法语来自拉丁语的施动者词尾。银行的金钱义来自意大利语 banca「长凳」。年代均为约数。"},"items":[{"era":"ITALIAN BANCA","en":"Banca named the bench where money was changed and then the business carried on there.","cn":"banca 先指兑换钱币的长凳，后指在那里做的生意。"},{"era":"MEDIEVAL LATIN BANCUS","en":"Medieval Latin bancus recorded the bench and the money trade and supplied the English form.","cn":"中世纪拉丁 bancus 记录了长凳与金钱交易，并提供英语形式。"},{"era":"ENGLISH BANK","en":"English bank named the money business and the institution, and from it the person-word was formed.","cn":"英语以这个词指金钱生意与机构，再由它构成指人的词。"},{"era":"AGENT SUFFIX","en":"A French agent suffix from Latin -arius marked the person who performs the action, giving banker.","cn":"一个经法语来自拉丁的施动后缀标示执行动作的人，构成这个词。"},{"era":"GAMBLING EXTENSION","en":"Because a bank also meant a reserve of money, the keeper of a gambling table's reserve was called a banker too.","cn":"由于这个词也指资金储备，保管赌桌储备的人也被赋予了同一名称。"},{"era":"UNCERTAIN DETAILS","en":"Attestation uncertain (first citation): the earliest recorded use of the person-word is not precisely dated, and the gambling sense may be older than the banking one.","cn":"首见年代不确定：指人词的最早用例没有确切年代，赌博义可能比银行义更早。"}]},"similar":{"note":{"en":"Group one separates the person from the institution and the business; group two holds people who handle money and the rival role at a table.","cn":"第一组把人物与机构、业务分开；第二组是处理金钱的人与牌桌上的对手角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bank","ipa":"/bæŋk/","tag":"the institution","definition":"Bank is the institution or the verb; banker is the person who works in or owns it.","definitionCN":"bank 是机构或动词；banker 是在其中工作或拥有它的人。"},{"word":"banking","ipa":"/ˈbæŋkɪŋ/","tag":"the business","definition":"Banking is the business carried on, not a person.","definitionCN":"banking 是从事的业务，不是人。"},{"word":"bankable","ipa":"/ˈbæŋkəbl/","tag":"the adjective","definition":"Bankable describes what a bank will accept, not a person.","definitionCN":"bankable 描述银行愿意接受的东西，不指人。"},{"word":"broker","ipa":"/ˈbrəʊkə/","tag":"different role","definition":"A broker matches buyers and sellers for a fee, a different function from a banker's lending and advising.","definitionCN":"broker 收取费用撮合买卖双方，与银行家的放贷和咨询职能不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"financier","ipa":"/fɪˈnænsɪə/","tag":"larger scale, across markets","definition":"A financier operates across institutions and large deals, while a banker usually works inside one bank.","definitionCN":"financier 跨机构与大型交易运作，banker 通常在一家银行内工作。"},{"word":"teller","ipa":"/ˈtelə/","tag":"counter staff","definition":"A teller serves customers at the counter, far below the senior officer a banker usually is.","definitionCN":"teller 在柜台服务客户，地位远低于通常意义上的银行高级职员。"},{"word":"cashier","ipa":"/kəˈʃɪə/","tag":"till keeper","definition":"A cashier keeps the till and handles payments, a narrower front-line role.","definitionCN":"cashier 掌管收银台并处理付款，是更窄的一线角色。"},{"word":"dealer","ipa":"/ˈdiːlə/","tag":"trades for the house","definition":"A dealer trades securities or holds the table's position, overlapping with the gambling sense but not the banking one.","definitionCN":"dealer 交易证券或持有桌面头寸，与赌博义重叠，却不属银行义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real agent suffix, the real bank family and the real double life of the word.","cn":"正常联想：真实的施动后缀、真实的银行词族与这个词真实的两面生活。"},"normal":[{"en":"The suffix marks the person: bank plus agent ending equals the one who does the bank's work.","cn":"后缀标示人物：银行加施动词尾，就是在银行做事的人。"},{"en":"It covers owners, senior officers, investment specialists and central officials.","cn":"它涵盖所有者、高级职员、投资专家与中央官员。"},{"en":"Because a bank can be a reserve, the keeper of a gambling reserve also takes the name.","cn":"由于这个词也可指储备，保管赌局储备的人也得到这个名称。"},{"en":"In informal British speech a banker is a sure thing, from the safety of a reliable bank.","cn":"在非正式英式口语中，这个词指稳赢的事，源自可靠银行的安全感。"},{"en":"It is a person word, unlike the institution and the industry beside it.","cn":"它是指人的词，与旁边的机构和行业不同。"}],"abstract":[{"en":"Picture a person behind a heavy door, deciding which projects will be funded.","cn":"想象一个人坐在厚重的门后，决定哪些项目能获得资金。"},{"en":"Picture a second person at a card table guarding a box of chips.","cn":"想象另一个人在牌桌旁守着一箱筹码。"},{"en":"Picture a word that can sit in an office and at a gaming table on the same day.","cn":"想象一个词，同一天既能坐在办公室，也能坐在赌桌旁。"}]},"examples":[{"en":"The banker asked for two years of accounts before agreeing to the loan.","cn":"这位银行家在同意贷款前要求提供两年的账目。"},{"en":"Central bankers raised rates to slow the price rise.","cn":"中央银行家提高利率以减缓物价上涨。"},{"en":"At the card table the banker held the chips and paid the winners.","cn":"牌桌上庄家持有筹码并赔付赢家。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「板」加「客」——在长板桌后替人管钱、放贷的客人，就是银行家","word":"banker"},"root":"由「银行」加施动后缀构成，该后缀经法语来自拉丁语的施动者词尾；银行的金钱义来自意大利语 banca「长凳」，经中世纪拉丁 bancus 进入英语。因这个词亦指资金储备，赌局中掌管储备的人也得此名。","sensesIntro":{"en":"Eight senses follow one person: a senior officer becomes an owner, an investment specialist, a central official, a gambling keeper, the house side, an informal certainty and finally an adviser.","cn":"八个义项沿同一个人展开：高级职员先成为所有者、投资专家、中央官员、赌局掌管者、庄家一方、口语中的稳赢之事，最后成为顾问。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person behind a bank's heavy door and another at a card table, sharing one name.","cn":"核心意象：一个人在银行厚门之后，另一个人在牌桌旁，共用一个名字。"},"chain":["SENIOR OFFICER","BANK OWNER","INVESTMENT SPECIALIST","CENTRAL OFFICIAL","TABLE KEEPER","SURE THING"],"branches":[{"senses":"01 · 02","en":"THE INSTITUTION'S PEOPLE: senior staff and the owning principal.","cn":"机构中的人：高级职员与拥有银行的主要负责人。"},{"senses":"03 · 04","en":"THE SPECIALISTS: deal-making bankers and public monetary officials.","cn":"专家：做交易的银行家与公共货币官员。"},{"senses":"05 · 06","en":"THE TABLE: the keeper of the reserve and the house side in play.","cn":"牌桌：储备的掌管者与对赌的庄家一方。"},{"senses":"07","en":"THE SLANG: a reliable bank becomes a sure thing.","cn":"俚语：可靠的银行变成「稳赢的事」。"},{"senses":"08","en":"THE ADVISER: money expertise sold outside a bank.","cn":"顾问：在银行之外出售的金钱专长。"}]},"affixes":{"intro":{"en":"Banker is a person-word built on the money word bank, and it shares the whole bank family.","cn":"这个指人的词建立在金钱词「银行」之上，并共享整个银行词族。"},"latinIntro":{"en":"Medieval Latin bancus supplies the money form; the agent suffix comes from Latin -arius through French.","cn":"中世纪拉丁 bancus 提供金钱义形式；施动后缀经法语来自拉丁语的施动者词尾。"},"items":[{"word":"banker","structure":"bank + -er (agent suffix, from Latin -arius)","meaning":"one who works in a bank","meaningCN":"银行家","example":"The banker approved the draft.","exampleCN":"银行家批准了汇票。"},{"word":"bank","structure":"Italian banca (bench) through Medieval Latin bancus","meaning":"a money institution","meaningCN":"银行","example":"The bank closed early.","exampleCN":"这家银行提前关门。"},{"word":"banking","structure":"bank + -ing (action noun suffix)","meaning":"the business of banks","meaningCN":"银行业务","example":"Banking expanded abroad.","exampleCN":"银行业务向海外扩张。"},{"word":"bankable","structure":"bank + -able (adjective suffix)","meaning":"acceptable to a bank","meaningCN":"可获银行支持的","example":"The plan is bankable.","exampleCN":"这个计划可获得银行支持。"},{"word":"bankroll","structure":"bank + roll (compound noun)","meaning":"a supply of money","meaningCN":"资金","example":"A backer supplied the bankroll.","exampleCN":"一位支持者提供了资金。"},{"word":"banknote","structure":"bank + note (compound noun)","meaning":"paper money","meaningCN":"纸币","example":"The banknote was old.","exampleCN":"这张纸币很旧。"},{"word":"embankment","structure":"em- (prefix 'in') + bank (river sense) + -ment","meaning":"a raised bank of earth","meaningCN":"堤岸","example":"The embankment was repaired.","exampleCN":"堤岸修好了。"},{"word":"banked","structure":"bank + -ed (past participle)","meaning":"deposited or tilted","meaningCN":"已存入的；倾斜的","example":"The plane banked right.","exampleCN":"飞机向右倾斜。"}],"latinEntries":[{"word":"bancus","structure":"bancus, banci (m., second declension, Medieval Latin)","meaning":"bench, money table","meaningCN":"长凳；钱桌"},{"word":"bancarius","structure":"bancarius, bancarii (m., second declension, Medieval Latin)","meaning":"money changer","meaningCN":"钱币兑换商"}],"derivatives":[{"word":"bank","pos":"n./v.","zh":"银行 / 存钱；依赖"},{"word":"banking","pos":"n.","zh":"银行业务"},{"word":"bankable","pos":"adj.","zh":"可获银行支持的"},{"word":"bankroll","pos":"n./v.","zh":"资金 / 为…提供资金"},{"word":"banknote","pos":"n.","zh":"纸币"}]}}]);
